window.HB_TR["1-kings"]["ks"]=["1. وۅنۍ اوس بادشاہ ڈیوڈ وٲنسہِ وٲنسہِ منز مبتلا گومُت۔ تہٕ تِمو اوس أمِس پلو ؤلِتھ، مگر تٔمِس اوس نہٕ کانہہ گرمی میلان۔ {مُتٲثر...: ہیب۔ دۅہن منز دٲخل گٔیہ}\n2. اَمہِ مۄکھٕ ووٚن تٔمِس خادمَو زِ میانہِ آقا بادشاہ سٕندِ خٲطرٕ گژھہِ اکھ جوان کنوارِ، تہٕ سُہ گژھہِ بادشاہس برونہہ کُن کھڑا تہٕ أمِس رژھرُن تہٕ پنہٕ نِس چھۅکہِ مَنٛز روزُن، یُتھ میانہِ آقا بادشاہس گرمی میلہِ۔ {تتہِ گژھہِ...: ہیب۔ تِم ژھانڈٕن} {اکھ نوجوان...: ہیب۔ اکھ لڑکی، اکھ کنوار} {رژھر...: ہیب۔ أمِس خٲطرٕ گژھ اکھ شیریشر}\n3.\\tیِمو ژھانڈ اِسرٲیلِس سٲرۍسٕے ساحلس منز أکِس خۅش لڑکی تہٕ لٔبِکھ ابیشاگ اکھ شُنَمِت، تہٕ أنِکھ سُہ بادشاہس نِش۔ \n4.\\tتہٕ لڑکی ٲس سٮ۪ٹھاہ خوبصورت، تہٕ ٲسٕن بادشاہس رژھرٕن، تہٕ أمِس خدمت کٔرٕن، مگر بادشاہ اوس نہٕ أمِس خبر۔ \n5. اَمہِ پَتہٕ ووٚن ہگِتھ سٕندِ نیچِوِ اڈونیاہَن پانَس تھزرٲوِتھ وَنُن زِ بہٕ بَنہٕ بادشاہ تہٕ تٔمۍ کٔرٕن أمِس برونہہ کُن رَتھ تہٕ گُرِ سوارِ تہٕ پنٛژاہ نفر تیار۔ {بادشاہ بٔنِو: ہیب۔ حُکوٗمت}\n6.\\tتہٕ تٔمۍ سٕندِس مٲلس اوس نہٕ کُنہِ تہِ وِزِ یہِ ونِتھ ناراض گومُت، ژے کیازِ کورُکھ یہِ؟ تہٕ سُہ تہِ اوس سٮ۪ٹھاہ نیک {انسان}۔ تہٕ {تسٕنزِ ماجہ} اوس أمِس ابسالوم پتہٕ زٲنِتھ۔ {کُنہِ تہِ...: حب۔ تٔمۍ سٕندِس دۅہہٕ پیٹھ}\n7.\\tتہٕ تٔمۍ کٔر زرویاہ سٕندِس نیچوِس یوآبس سٍتـ̡ تہٕ پادٕرۍ ابیاتھرس سٍتـ̡ کتھ باتھ: تہٕ تِمو کٔر ادونیاہ سٍتـ̡ مدد۔ {سُہ...: حب۔ تٔمۍ سٕندِ کلام} سٍتـ̡ {مندرجہ ذیل ...: ہیب۔ ادونیاہ سٍتـ̡ مدد}\n8.\\tمگر زادوک پادٕر، تہٕ یہویاداہُک نیچو بنایا، تہٕ ناتھن پیغمبر، تہٕ شعیعی، تہٕ رئی، تہٕ طاقتور نفر یِم داؤد سٕندِس سٍتـ̡ ٲسۍ، ٲسۍ نہٕ عدونیاہ سٍتـ̡ سٍتـ̡ ۔ \n9. تہٕ ادونیاہ ہن مارۍ زوہلیتھ کِس کٔنہِ سٍتـ̡ کٔرِتھ تہٕ موٚٹۍ چاروٲے یُس {چُھ} اینروگیلن سٍتـ̡ بُلاونہٕ آمُت، تہٕ بُلووُن پنٕنـ̡ سارِنٕے بٲے بادشاہ سٕندِ نیچِو، تہٕ یہوداہ کِس سارِنٕے مردس بادشاہ سٕندِ خادم: {Enrogel: یا، کُل روگل}\n10.\\tمگر ناتھن پیغمبر، تہٕ بنیاہ تہٕ طاقتور مرد تہٕ سُلیمان، تٔمۍ سُند بٲے آو نہٕ۔ \n11. کیازِ کوٚر ناتھنن سُلیمان سٕنزِ ماجہِ بَتشیبا سٍتـ̡ کتھ کٔرِتھ وَنُن زِ ژے چُھہ نہٕ بوزمُت زِ حگیث سُند نیچو چُھ ادونیاہ سُند راج کران، تہٕ سٲنِس آقا داؤدس چُھہ نہٕ پتاہ ۔ \n12.\\tتێلہِ یێلہِ یێلہِ بہٕ ژے دُعا کٔرِتھ ژے پنُن زُو تہٕ پنُن نیچو سلیمان سُند زُو بچٲوِتھ تہٕ ژے کٔرِو پنُن زُو بچاونہٕ۔ \n13.\\tگژھ تہٕ بادشاہ داؤدس نِش اژُن، تہٕ ونُن زِ کیا ژے کٔر نہٕ میانہِ آقا، اے بادشاہ، پننہِ خادمہِ ہُند قسم، یٔژ سُلیمان، تُہند نیچو کرِ میانہِ پتہٕ بادشاہی، تہٕ سُہ بِہِتھ میٲنِس تختس پیٹھ؟ تیلہِ کیازِ چُھ ادونیاہ بادشاہ؟ \n14.\\tوُچھِو، یێلہِ تہِ ژے بادشاہس سٍتـ̡ کتھ کٔرِتھ، بہٕ تہِ یِیہٕ ژے پَتہٕ تہٕ چانہِ کَلامٕچ تصدیق کٔرِتھ۔ {تصدیق: ہیب۔ بٔرِتھ کٔرِو}\n15.\\tتہٕ بیت شیبا ژاو بادشاہس نِش کمرس منز، تہٕ بادشاہ اوس واریاہ بُزرگ۔ تہٕ ابیشاگ شُنمیتن کٔر بادشاہس خدمت۔ \n16.\\tتہٕ بَتشیبا کٔر نَمان، تہٕ کٔرٕن بادشاہس سَجود۔ تہٕ بادشاہن ووٚن، ژیہ کیا چُھہ؟ {کیا...: ہیب۔ ژے کیا چُھہ؟}\n17. تہٕ تٔمۍ ووٚن أمِس زِ میانہِ آقا، تُہۍ چُھکھ خداوند سٕندِ خدایہِ سٕندِ سٍتـ̡ پَنٕنـ̡ دٔسۍ پَنٕنـ̡ دٔرِتھ تہٕ سُہ بِہِتھ میانہِ تختس پیٹھ۔ \n18.\\tتہٕ وُچھِو، ادونیاہ چُھ بادشاہ۔ تہٕ وُن، میانہِ آقا بادشاہ، ژے چُھہ نہٕ یہِ زانان: \n19.\\tتہٕ تٔمۍ کٔرِن بیل تہٕ موٚٹۍ چاروٲے تہٕ کۅکرِ کٔرِتھ تہٕ بادشاہ سٕندِس سارِنٕے نیچوِس تہٕ پادٕرۍ ابیاتھر تہٕ لشکرُک کپتان، مگر سُلیمانس چُھنہٕ تُہند خادم بُلاونہٕ آمُت۔ \n20. تہٕ تۅہہ، میانہِ آقا، اے بادشاہ، سارِنٕے اسرٲیلٕچ نظر چھے ژے کُن، یُس تِمن وَنُن زِ تٔمِس پتہٕ کُس بِہِہِ میٲنِس آقا بادشاہ سٕندِس تختس پیٹھ۔ \n21. نتہٕ گژھہِ یہِ سپدِ، ییلہ میون آقا بادشاہ پننین مٲلن سٍتـ̡ شوٚنگِ، زِ بہٕ تہٕ میون نیچو سلیمان گژھن مُجرِم شمار کرنہٕ۔ {مُجرِم: حب۔ گۅنہگار}\n22.\\tتہِ ییلہ سۅ بادشاہس سٍتۍ کتھ کران ٲس، ناتھن پیغمبر تہِ آو اندر۔ \n23.\\tتہٕ تِمو ووٚن بادشاہس وُچھِتھ وُچھِو ناتھن پیغمبر۔ تہٕ ییلہ سُہ بادشاہس برونہہ کُن آو، تٔمۍ کٔر بادشاہس برونہہ کُن بُتھ کٔرِتھ نمُن۔ \n24. تہٕ ناتھنن ووٚن، اے بادشاہ، کیا ژے ووٚنمُت زِ ادونیاہ کرِ میانہِ پتہٕ بادشاہ، تہٕ سُہ بِہہِ میٲنِس تختس پیٹھ؟ \n25.\\tتِکیازِ سُہ چُھ اَمہ دۅہہ ژٔلِتھ تہٕ کٔرِن گاوِ تہٕ موٚٹۍ چاروٲے تہٕ کۅکرِ کٔرِتھ تہٕ بادشاہ سٕندِس سارِنٕے نیچوِس تہٕ لشکرٕکۍ سردار تہٕ پادٕرۍ ابیاتھر بُلٲوِتھ ۔ تہٕ وُچھِتھ چھِ تِم أمِس برونہہ کُن کھٮ۪وان تہٕ چیوان تہٕ ونان زِ خدایہ رژھ بادشاہ ادونیاہ ۔ {خدا...: عبرانی۔ بادشاہ ادونیاہ زندٕ روزُن}\n26. مگر میہ تہِ چُھس تُہند خادم تہٕ زادوک پادٕر، تہٕ یہویادہ سُند نیچو بنایاہ تہٕ تُہند خادم سلیمان، تٔمۍ چُھ نہٕ بُلاونہٕ آمُت۔ \n27.\\tکیا یہ کتھ چھیہ میانہِ آقا بادشاہن کٔرمٕژ، تہٕ ژے چُھہ نہٕ پننِس خادمس ہٲومُت، یُس میانہِ آقا بادشاہ سٕندِس تختس پیٹھ بِہِتھ آسہِ۔ \n28.\\tبادشاہ داؤد دیت جواب تہ وونُن میہ بتھ شیبا وونُن۔ تہٕ سۅ آیہِ بادشاہ سٕندِس حٲضِرس منز تہٕ گٔیہِ بادشاہس برونہہ کُن۔ {into...: ہیب۔ بادشاہس برونہہ کُن}\n29. تہٕ بادشاہن ووٚن قسم، تہٕ وونُن، {یێلہِ} خداوند زندٕ چُھ، یٔمۍ میون روح تمام مصیبتو نِش نجات دِژمُت، \n30. یێلہِ بہٕ چُھس تۅہہِ سٍتـ̡ اسرٲیلِکِس خدایہِ سٕندِ سٍتـ̡ قَسم کَران، یێلہِ بێیہِ سُہ میانہِ بدلہٕ میانہِ تختس پیٹھ بِہِتھ۔ یێلہِ تہِ بہٕ کَرٕ یێلہِ یێلہِ تہٕ یێلہِ تہِ کَرٕ بہٕ یێلہِ تہٕ یێلہِ تہِ بہٕ یێلہِ تہٕ یێلہِ تہِ بِہِتھ بہٕ یێلہِ تہٕ یێلہِ بێیہِ یێلہِ تہٕ یێلہِ تہِ بِہُنـ̡ ۔ \n31. تمہ پتہ کٔر باتھ شیبا زمینس برونہہ کُن نمُن، تہٕ کوٚرُن بادشاہس احترام، تہٕ وونُن، میانہِ آقا بادشاہ داوُد ہمیشہٕ زندٕ۔ \n32.\\tتہٕ بادشاہ داؤد ووٚن زِ مے وَنُن زادوک پادٕر، تہٕ ناتھن پیغمبر تہٕ بنیاہ یہویادہ سُند نیچو۔ تہٕ تِم وٲتۍ بادشاہس برونہہ کُن۔ \n33.\\tبادشاہن ووٚن تِمن تہِ زِ پنہٕ نِس آقا سٕندِس خادمَس نِش نِیُن تہٕ سُلیمانس نیچو میانہِ خچرس پیٹھ سوار تہٕ أنِو سُہ گِہونَس نِش: {میٲنۍ ...: حب۔ یُس میہ سُند چُھ}\n34. تہٕ زادوک پادٕرۍ تہٕ ناتھن پیغمبرن دِیُن تتہِ اسرٲیلِس پیٹھ بادشاہ مسح کرنہٕ، تہٕ وَنُن زِ خدایہ بَچھ بادشاہ سُلیمان۔ \n35. تیلہِ گژھِو تٔمِس پَتہٕ یِنہٕ تہٕ سُہ یِنہٕ تہٕ میٲنِس تختس پیٹھ بِہِتھ۔ تِکیازِ سُہ آسہِ میانہِ بدلہٕ بادشاہ۔ تہٕ مے چُھس سُہ اسرٲیلِس تہٕ یہوداہَس پیٹھ حُکُمران مقرر کوٚرمُت۔ \n36.\\tتہٕ یہوعیادا سٕندِ نیچو بنیاہ دِژ بادشاہس جواب تہٕ وونُن، آمین: میانہِ آقا بادشاہ سُند خدا، تہِ چُھ یہِ وَنان۔ \n37. یِتھٕ پٲٹھـ̡ خداوند چُھہ میٲنِس آقا بادشاہس سٍتـ̡ سٍتـ̡ سُہ تہٕ سُہ تہِ بَناوُن سُہ سُلیمانس سٍتـ̡ تہٕ تٔمۍ سُند تخت بَناوُن میانہِ آقا بادشاہ داؤد سٕندِس تختس سٍتـ̡ بٔنـ̡ ۔ \n38.\\tیێمہِ سٍتـ̡ زادوک پادٕر، تہٕ ناتھن پیغمبر، تہٕ یہویاداہُک نیچو بنایہ، تہٕ چیریتھیس تہٕ پیلِتھی، تہٕ سُلیمانس دٲیرٕ بادشاہ داؤد سٕندِس خچرس پیٹھ سوار تہٕ أنِن سُہ گیہونَس نِش۔ \n39.\\tتہٕ زادوک پادٕرۍ کوٚڈ خیمہ منزٕ تیلُک اکھ سینگ تہٕ کوٚرُن سُلیمانس مسح کرنہٕ۔ تہٕ تِمو دِژ بُرق۔ تہٕ سارِوٕے لوکو ووٚن، خدایہ رچھ بادشاہ سلیمان۔ \n40.\\tتہٕ سارِوٕے لُکھ آیہِ أمِس پَتہٕ تہٕ لُکھ لُکھ پایپَو سٍتـ̡ پایپ، تہٕ کٔرٕکھ سٮ۪ٹھاہ خوشی سٍتـ̡ خۅش گٔیہِ، یێلہِ زٔمیٖن گٔیہِ تِمن ہٕنزِ آوازٕ سٍتـ̡ پھٔٹِتھ ۔ {پایپ: یا، بانسر}\n41.\\tتہٕ ادونیاہ تہٕ أمِس سٍتـ̡ سارِنٕے پژھیو بوز یِمو کھٮ۪نہٕ چُھہ بند گومُت۔ تہٕ ییلہ یوآبن بُزرُک آواز بوز، تٔمۍ ووٚن، کیازِ چُھہ شہرُک شور؟ \n42. تہٕ ییلہ سُہ وُنہِ تہِ کتھ کران اوس، وُچھِو پادٕرۍ ابیاتھر سُند نیچو جوناتھن آو تہٕ ادونیاہ ہن ووٚن أمِس اژُن۔ تکیازِ تُہۍ چھُکھ بہادر انسان تہٕ خوشخبری دِوان۔ \n43.\\tتہٕ یوناتھنن دیُت جواب تہٕ وونُن ادونیاہ سٍتـ̡ یێلہِ سٍتـ̡ سٲنـ̡ آقا بادشاہ داؤد سُلیمانُک بادشاہ بنوومُت۔ \n44.\\tتہٕ بادشاہن سوٗزۍ پانس سٍتـ̡ پادٕرۍ زادوک، تہٕ ناتھن پیغمبر، تہٕ یہویادہٕ سُند نیچو بنایا، تہٕ چیریتھیس تہٕ پیلیتھی، تہٕ تِمو دِژ أمِس بادشاہ سٕندِس خچرس پیٹھ سوار کرنہٕ۔ \n45.\\tتہٕ زادوک پادٕرۍ تہٕ ناتھن پیغمبرن چُھ أمِس گِحونَس مَنٛز بادشاہ مسح کٔرِمُت، تہٕ تِم چھِ اَتہِ پٮ۪ٹھٕ خۄش گٔژھِتھ وٲتِتھ، یُتھ زن شہر دُبارٕ بَنُن۔ یہِ چُھ سُہ شور یُس تۅہہ بوزمُت چُھ۔ \n46. تہٕ سُلیمان تہِ چُھ بادشاہت کِس تختس پیٹھ بِہتھ۔ \n47. تہٕ امہِ علاوٕ آیہِ بادشاہ سٕندِ خادم سٲنِس آقا بادشاہ داوُد سٕندِس دُعا دِنہٕ خٲطرٕ، یہِ وَنُن زِ خدایہِ بناو سُلیمان سُند ناو پننہِ ناوٕ کھۅتہٕ بہتر تہٕ تٔمۍ سُند تخت بناوُن پننہِ تختہٕ کھۅتہٕ بوٚڈ ۔ تہٕ بادشاہن کٔر بسترس پیٹھ نمُن۔ \n48.\\tتہٕ یِتھٕ پٲٹھۍ ووٚن بادشاہ، بابرکت {بنہٕ} اسرٲیلُک خدا، یٔمۍ از دۅہہ میٲنِس تختس پیٹھ بِہنہٕ خٲطرٕ {اَکہ} دِژمُت، میٲنۍ أچھ تہِ وُچھان۔ \n49.\\tتہٕ یِم سٲری مہمان یِم عدونیاہ سٍتـ̡ ٲسۍ، کھوژِتھ گٔیہِ تہٕ ووٚتھ تہٕ گٔیہِ پرٮ۪تھ أکِس شخصس پننہِ وتہِ پٲٹھۍ۔ \n50.\\tتہٕ ادونیاہ ہیوٚت سُلیمان سٕندِ سٍتـ̡ کھوژُن، تہٕ ووت ووٚتھ، تہٕ لوٚگ قربان گاہٕکِس سینگس تھپھ کٔرِتھ۔ \n51.\\tتہٕ آو سُلیمانس وننہٕ زِ وُچھِو اڈونیاہ چُھ بادشاہ سُلیمانس کھوژان، تِکیازِ تٔمِس چُھ قربان گاہٕکۍ سینگ تھپھ کٔرِتھ وَنُن زِ سُہ کرِ نہٕ پَنُن خادم تلوار سٍتـ̡ مٲرِتھ۔ \n52. تہٕ سُلیمانن ووٚن زِ اگر سُہ پانس اکھ قٲبل انسان ہاوِ، تٔمِس سُند اکھ مس گژھہِ نہٕ زمینس پیٹھ، مگر اگر تس مَنٛز بدکاری میلہِ، سُہ گژھہِ مرُن۔ \n53. تہٕ بادشاہ سُلیمانن سوٗز، تہٕ تِمو أنۍ سُہ قربان گَرٕ پیٹھٕ بۄن۔ تہٕ سُہ آو تہٕ کٔرٕن بادشاہ سُلیمانس کُن نمُن، تہٕ سُلیمانن ووٚن أمِس گَژھ پَنٕنِس گَرَس کُن۔","1. وۅنۍ گۆو داؤد سُند دۅہ نزدیک زِ سُہ گژھہِ مرُن۔ تہٕ تٔمۍ ووٚن سُلیمانس پننِس نیچوِس پیٹھ حکم دِتھ، \n2.\\tبہٕ چُھس سارِنٕے زمینہٕ ہٕنزِ وتہِ پکان: تَمہِ مۄکھٕ گژھہٕ مضبوط، تہٕ پنُن پان ہٲوِو اکھ انسان۔ \n3. تہٕ خداوند پَنٕنِس خدایہ سُند ذمہٕ تھاوُن، تٔمۍ سٕنزِ وتہِ پٲٹھۍ، تٔمۍ سٕندِس حکمن، تہٕ تٔمۍ سٕندِس فٲصلن تہٕ تٔمۍ سٕنزِ گوٲہی ہٕنز پاسداری، یُتھ زن موسیٰ سٕندِس شریعتس مَنٛز لیکھنہٕ آمُت چُھ، یُتھ تہٕ کُنہِ تہِ پھیرِو، یُس تہٕ کُنہِ تہِ پھیرِو، تہٕ کُنہِ تہِ پھیُرِو: {خوشحالی: یا کُنہِ تہِ پھیرِو}\n4. یێلہِ خداوند کرِ پَنُن کلام جٲری یُس تٔمۍ میانہِ مُتلق کتھ کٔرِتھ، یێلہِ تُہٕندِس وتہِ پیٹھ توجہ دِن، سٲرۍسٕے دِلہٕ تہٕ پوٗرٕ روحہٕ سٍتـ̡ پٔکِتھ، تێلہِ گژھہِ نہٕ تۅہہِ سٍتـ̡ اِسرٲیلِس کِس تختس پیٹھ بٔہِتھ کانہہ نفر ناکام سپدُن۔ {ناکام...: حب۔ ژے نِش گژھ تختہ نِش ژٹنہٕ}\n5.\\tتۅہہ تہِ چھے پتاہ زِ زرویاہ سٕندِ نیچو یوآب کیاہ کوٚر میانہِ سٍتۍ، {تہٕ} یُس تٔمۍ اسرٲیلِکۍ لشکرن ہٕندِس دۅن کپتانن سٍتۍ، نیر سٕندِس نیچوِس ابنرس تہٕ یتھر سٕندِس نیچوِس اماسا سٍت، یُس تمٔۍ مارِتھ تہٕ امن سٍتـ̡ جنگُک خون ترووُن تہٕ جنگُک خون ترووُن پننِس کمرس پیٹھ یُس تٔمۍ سٕندِس کھورِ سٍتـ̡ اوس، تہٕ تٔمۍ سٕندِس کھورِ پیٹھ۔ {شیڈ: ہیب۔ پُٹ}\n6. تێمہِ کِنۍ کرو پننہِ حکمتہٕ مطٲبق، تہٕ تٔمۍ سُند کلہٕ گژھہِ نہٕ سُکون سان قبرس کُن۔ \n7.\\tمگر برزیلائی سٕندِس نیچوِس سٍتـ̡ کٔرِو رحمت، تہٕ تِم گژھن تُہٕندِس دسترس پیٹھ کھٮ۪وان تہٕ یِمن ہٕندِس دسترس پیٹھ کھٮ۪وان آسہٕ، تِکیازِ یِتھٕ پٲٹھۍ آیہ تِم میانہِ نِش ییلہ بہٕ تُہند بٲے ابسالوم سٕندِ وجہ سٍتـ̡ ژٔلِتھ ژٔلِتھ ۔ \n8.\\tتہٕ وُچھِو ژے سٍتـ̡ بہوریمُک بنیجمِی سُند نیچو شِمیعی، یٔمۍ دۅہہٕ بہوریمُک بنجامی دِنہٕ آمُت، یٔمۍ میہ سٍتـ̡ سٮ۪ٹھاہ لعنتُک لعنت، مگر سُہ آو میہ اردنس مَنٛز مِلنہٕ خٲطرٕ، تہٕ بہٕ چُھس أمِس سٍتـ̡ خدایہِ سٍتـ̡ قسم دِوان زِ بہٕ کٔرٕ نہٕ ژے تلوار سٍتـ̡ مارنہٕ۔ {مُشکِل: حب۔ مضبوط}\n9.\\tتێلہِ تھٔو نہٕ أمِس بے گناہ ، تکیازِ تہٕ ژٕ چُھکھ اکھ عقلمند انسان، تہٕ زانان چُھکھ زِ ژے کیا کرُن أمِس سٍتـ̡ کرُن۔ مگر تٔمۍ سُند کھورٕ کلہٕ چُھہ ژے خونس سٍتـ̡ قبرس تام واتناوُن۔ \n10.\\tیێلہِ گۆو داؤد پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ سُہ آو داؤد شہرس مَنٛز دفن کرنہٕ۔ \n11. تہٕ یێمہِ دۅہہٕ داؤد سٕندِس اِسرٲیلس پیٹھ راج کٔر، سَتھ ؤری کٔر تٔمِس حبرونس مَنٛز تہٕ ترٕہ وُہرۍ کٔر یروشلمس مَنٛز حکومت۔ \n12. پَتہٕ بیوٹھ سُلیمان پننِس مٲلِس داؤد سٕندِس تختس پیٹھ۔ تہٕ تٔمۍ سٕنز سلطنت گٔیہِ واریاہ قایم۔ \n13.\\tتہٕ ہگیث سُند نیچو عدونیاہ آو سُلیمان سٕنزِ موج بیت شیبا نِش۔ تہٕ تٔمۍ ووٚن، کیا ژٕ چُھکھ امن سان آمُت؟ تہٕ تٔمۍ ووٚن، امن سان۔ \n14.\\tتٔمۍ ووٚن بییہ تہِ، میہ چُھس ژے کینہہ ونُن۔ تہٕ تٔمۍ ووٚن، وَنُن۔ \n15. تہٕ ووٚن، ژے چھے پتاہ زِ سلطنت ٲس میٲنۍ تہٕ {یہ} سارِنٕے اسرٲیلَن کٔر میہ کُن بُتھ تہٕ بہٕ گژھہِ بادشاہت کرنہٕ، یێلہِ تہِ چھُ بادشاہت بدلاونہٕ آمٕژ، تہٕ بنیوو میانہِ بٲے سُند، کیازِ یہِ اوس خداوند سٕندِ طرفہٕ أمِس سٕندِس سٍتـ̡ ۔ \n16.\\tتہٕ وۅنۍ چھُس ژے اکھ عرضی منگان، میہ کٔر نہ انکار۔ تہٕ تٔمۍ ووٚن أمِس وَنُن۔ {انکار...: ہیب۔ میہ پھیُر نہٕ پھیُر}\n17.\\tتہٕ تٔمۍ ووٚن، کتھ کرٕن، بہٕ چُھس ژے سُلیمان بادشاہس نِش دُعا کران زِ سُہ دِیہٕ مے ابیشاگ شُنمیت زنانہٕ خٲطرٕ۔ \n18.\\tتہٕ باتھ شیبا ووٚن، خٲر۔ بہٕ کَرٕ چانہِ خٲطرٕ بادشاہس سٍتـ̡ کتھ کرنہٕ۔ \n19. تَمہِ کِنۍ گٔیہِ بَتشیبا بادشاہ سُلیمانس نِش، تٔمِس سٍتـ̡ کتھ کرنہٕ خٲطرٕ۔ تہٕ بادشاہ ووٚتھ أمِس سمکھنہٕ خٲطرٕ، تہٕ بیوٹھ أمِس کُن نم، تہٕ بیوٹھ پننِس تختس پیٹھ، تہٕ کوٚرُن بادشاہ سٕنزِ ماجہِ ہٕندِ خٲطرٕ اکھ نشست قٲیِم۔ تہٕ سۄ بیوٹھ تٔمِس دچھنہِ اتھس پیٹھ۔ \n20. اَمہِ پتہٕ ووٚن تٔمۍ ژےٚ اکھ لۄکٕٹ عرضی یژھان۔ {بہٕ چُھس دُعا کَران}، مے وَنُن نہٕ نہٕ۔ تہٕ بادشاہن ووٚن أمِس ، میانہِ موج پرژھ، کیازِ بہٕ وَنٕ نہٕ نہٕ نہٕ۔ \n21.\\tتہٕ ووٚن زِ اَبِشاگ شُنمیت گژھہِ تُہٕندِس بٲے ادونیاہ سٕندِس خانٛدارِنہِ خٲطرٕ دِنہٕ۔ \n22.\\tتہٕ بادشاہ سُلیمانن دیُت جواب تہٕ وونُن پننہِ ماجہِ، تہٕ ژے کیازِ چُھکھ ابیشاگس شُنمیتس ادونیاہ سٕندِ خٲطرٕ منگان۔ أمِس تہِ منگُن بادشٲہی تہِ۔ تکیازِ سُہ چُھ میٲنۍ بوٚڈ بوے ۔ تٔمِس خٲطرٕ تہٕ پادٕرۍ ابیاتھر سٕندِ خٲطرٕ تہٕ زرویاہ سُند نیچو یوآب سٕندِ خٲطرٕ۔ \n23. اَمہِ پَتہٕ چُھ بادشاہ سُلیمانن خداوند سٕندِ سٍتـ̡ قسم دِژمُت، یێلہِ خدایہِ کٔرِو میانہِ سٍتـ̡ تہٕ زیادٕ، یێلہِ نہٕ ادونیاہ ہن پننہِ زُوٕ سٍتـ̡ یہِ لفظ کتھ کٔرمٕژ۔ \n24.\\tتێلہِ چُھہ خداوند زندٕ، یُس میہ قایم کورمُت چُھ، تہٕ یێمہِ میہ پننِس مٲلس داؤد سٕندِس تختس پیٹھ بِہناوُن، تہٕ یُس میہ اکھ گرٕ بنوو، یُس وعدٕ کورمُت چُھ، ادونیاہ یِہ از دۅہہ مارنہٕ یُن۔ \n25. تہٕ بادشاہ سُلیمانن سوٗزُن یہویادا سُند نیچو بنیاہ سٕندِ اتھہٕ سٍتـ̡ ۔ تہٕ سُہ پیوٚو أمِس پیٹھ زِ سُہ موٗد۔ \n26.\\tتہٕ پادٕرۍ ابیاتھرس ووٚن بادشاہس زِ ژے گژھ انتھوتھس نِش، پننین کھاہن تام۔ تکیازِ ژے چُھہ مرنس لایق، مگر بہٕ کرٕ نہٕ اتھ وِزِ ژے مارُن، کیازِ ژے چُھکھ میٲنس مٲلس داؤد سٕندِ برونہہ کُن خداوند خدا سُند صندوق ہُند تُلنہٕ آمُت، تہٕ کیازِ ژے چُھہ تِمن سارِنٕے سارِنٕے مَنٛز مُتٲثِر گومُت یِمن مَنٛز میٲنِس مٲلِس مُتٲثِر گومُت۔ {لایق...: ہیب۔ مرُن وول انسان}\n27.\\tیێلہِ کٔر سُلیمانن ابیاتھر پادٕرۍ بننہٕ نشہِ خداوند سٕندِس نِش۔ یُس سُہ خداوند سُند کلام پورٕ کرُن، یُس تٔمۍ شیلوہس مَنٛز ایلی سٕندِس گرس مُتلق کتھ کٔرِ۔ \n28.\\tاَمہِ پَتہٕ وٲژ یوآبس خبر زِ یوآب اوس عدونیاہ سٕندِس پَتہٕ پھیرمُت، حالانکہ سُہ اوس نہٕ ابسالوم پتہٕ پھیرِمُت۔ تہٕ یوآب ژوٚل خداوند سٕندِس خیمہ خانس کُن، تہٕ رٔٹِتھ رٔٹِتھ قربان گاہٕکِس سینگس پیٹھ۔ \n29.\\tتہٕ آو بادشاہ سلیمانس وننہٕ زِ یوآب ژوٚل خداوند سٕندِس خیمہ خانس کُن۔ تہٕ وُچھِو سُہ قربان گاہس نِش۔ تێمہِ پَتہٕ سُلیمانن سوٗز یہویادہ سُند نیچو بنیاہ تہٕ وونُن زِ گژھ أمِس پیٹھ پٔسِو۔ \n30.\\tتہٕ بنیاہ آو رب سٕندِس خیمہ خانس منز، تہٕ وونُن أمِس یِتھٕ پٲٹھۍ چُھہ بادشاہ وَنان۔ تہٕ تٔمۍ ووٚن، نہ۔ مگر بہٕ مرٕ یتہِ۔ تہٕ بنیاہ ووٚن بادشاہ سُند کلام دُبارٕ، یِتھٕ پٲٹھۍ ووٚن یوآب، تہٕ یِتھٕ پٲٹھۍ دیُت تٔمۍ مےٚ جواب۔ \n31. تہٕ بادشاہن ووٚن أمِس یُتھ تٔمۍ ووٚنمُت چُھ، تہٕ أمِس پیٹھ پٔسِتھ تہٕ دفن کٔرِو۔ یُس یوآبن میانہِ نِش تہٕ میٲنِس مٲلہِ سٕندِس گرٕ نِش نِش بے گناہ خوُن نِش نِنہٕ۔ \n32.\\tتہٕ خداوند کرِ پنُن خون پننِس کلس پیٹھ واپس، یُس أمِس کھۅتہٕ زیادٕ نیک تہٕ بہتر نفرن پیٹھ پیوٚو، تہٕ تِم مارُن تلوار سٍتـ̡ مٲرِتھ، میون مول داؤد یُس نہٕ پتاہ اوس، نیر سُند نیچو، یُس اسرٲیلُک لشکرُک کپتان، تہٕ اماسا یُس یہوداہ کِس لشکرُک کپتان۔ \n33. تِہُند خوُن گژھہِ یوآب سٕندِس کلس پیٹھ، تہٕ تٔمۍ سٕندِس بُلِس پیٹھ تہٕ تٔمۍ سٕندِس کلہٕ سٕندِس کلس پیٹھ ہمیشہٕ خٲطرٕ واپس۔ \n34.\\tتہٕ یہویاداہُک نیچو بنیاہ ووت تہٕ لوٚگ أمِس پیٹھ تہٕ مارُن تہٕ سُہ آو بیابانس مَنٛز پننِس گرس مَنٛز دفن کرنہٕ۔ \n35. تہٕ بادشاہن تھوو یہویادہ سُند نیچو بنیاہ پننِس کمرس مَنٛز میزبانس پیٹھ۔ تہٕ پادٕرۍ زادوک ترووُن بادشاہن ابیاتھر کِس کمرس مَنٛز۔ \n36.\\tتہٕ بادشاہن سوٗز تہٕ شِمعیَس بُلاون، تہٕ وونُن زِ یروشلمس مَنٛز بناو پان اکھ مکانہٕ، تہٕ اتہِ روزُن تہٕ تتہِ گژھ نہٕ کُنہِ تہِ نیرُن۔ \n37.\\tیێلہِ چُھہ یێلہِ ژے نیرِ، تہٕ نالہٕ کِدرون اپارِ نیرِو، تێلہِ گژھہِ پَکہٕ پٲٹھـ̡ مَرُن: تُہُند خوُن آسہِ تُہٕندِس کلَس پیٹھ۔ \n38.\\tتہٕ شِمیعی ووٚن بادشاہس زِ یہِ قول چُھ اصل: یِتھٕ پٲٹھۍ میانہِ آقا بادشاہن ووٚنمُت، تِتھے پٲٹھۍ کرِ تُہند خادم تہِ۔ تہٕ شِمیعی روٗد یروشلمس مَنٛز واریاہن دۅہن روزان۔ \n39.\\tتہٕ تریہ ؤری سپدِتھ سپد یہ زِ شمعیہ سٕندِ زٕ خادم ژٔلِتھ گتھ کِس بادشاہ ماچہ سٕندِس نیچوِس آچیش نِش۔ تہٕ تِمو ووٚن شِمیعی یَس وَنُن زِ وُچھِو تُہٕندِس خادمَس گَتس مَنٛز۔ \n40.\\tتہٕ شِمیعی ووٚتھ تہٕ گٔیہِ گَتھ نِش پنٕنٮ۪ن نوکرَن ژھانڈنہٕ خٲطرٕ، تہٕ شِمیعی ووت تہٕ أنِن گاتھ پیٹھٕ پنٕنۍ خادم۔ \n41.\\tتہٕ سُلیمانس آو وننہٕ زِ شمعی اوس یروشلم پیٹھٕ گاتھ گومُت تہٕ آو دُبارٕ۔ \n42.\\tتہٕ بادشاہن سوٗز تہٕ شِمعیَس بُلاونہٕ تہٕ وونُن تٔمِس زِ مے اوسُکھ نہٕ ژے خداوند سُند قسم، تہٕ وونُن ژے نِش احتجاج کٔرِتھ زِ یێلہِ ژٕ نیرِو تہٕ کُنہِ تہِ نیرِتھ نیرِو، تہٕ ژٕ گژھہِ پٔزۍ پٲٹھۍمرُن؟ تہٕ ژے وۆن مے زِ سُہ لفظ {یُس} چُھہ بوزمُت {سُہ} اصل۔ \n43. تیلہِ کیازِ کٔر نہٕ ژے خداوند سُند حلف تہٕ یُس حُکُم میہ ژے دِژمُت چُھ؟ \n44.\\tبادشاہن ووٚن شمیعی یس بییہ تہِ وۆن، ژے چھے تۅہہ سٲرۍسٕے بدکار پتاہ یُس تۅہہِ دِلس سٍتـ̡ دِل چُھ، یُس ژے میٲنس مٲلس سٍتـ̡ کورمُت چُھ، تێمہِ مۅکھہ کرِ خداوند تُہند بدکاری پانس پیٹھ واپس۔ \n45.\\tتہٕ بادشاہ سُلیمان گژھہِ بابرکت تہٕ داؤد سُند تخت گژھہِ ہمیشہٕ خٲطرٕ خداوند سٕندِ برونہہ کُن قایم کرنہٕ۔ \n46. تہٕ بادشاہن دِژ یہویادا سٕندِس نیچوِس بنیاہ سُند حُکُم۔ یُس نیبر تہٕ أمِس پیٹھ پیوٚو تہٕ سُہ موٗد۔ تہٕ بادشاہت گٔیہِ سلیمان سٕندِس اتھس مَنٛز قایم کرنہٕ۔","1. تہٕ سُلیمانن کٔر مصر کِس بادشاہ فرعونس سٍتـ̡ رفاقت تہٕ فرعون سٕنز کورِ نِتھ أنِن داؤد شہرس مَنٛز، یوتام تٔمۍ پنُن گرٕ تہٕ خداوند سُند گرٕ تہٕ یورشلمُک دیوار بنوُن ختم کرُن۔ \n2. صرف لوکو کٔر تھدٮ۪ن جاین پیٹھ قربانی، تکیازِ تِمن دۅہن تام اوس نہٕ خداوند سٕندِ ناوٕ سٍتـ̡ کانہہ گرٕ بناونہٕ آمُت۔ \n3. تہٕ سُلیمانن اوس خداوند سٕندِس مٲلِس سٕندِس مجسمس مَنٛز پکان تہٕ صرف اوس تٔمۍ تھدٮ۪ن جاین پیٹھ بخور قربان تہٕ زالان۔ \n4.\\tتہٕ بادشاہ گوٚو گِبیونَس نِش اَتہِ قربانی دِنہِ۔ تَمہِ مۄکھٕ اوس سُلیمانن اَتھ قربان گاہس پیٹھ ساس ساس زٲلِتھ نذرانہ پیش کٔرِتھ۔ \n5. گِبیونَس مَنٛز آو خداوند سُلیمانس رٲژ خوابس مَنٛز ظٲہر تہٕ خداین ووٚن، پرژھہٕ بہٕ کیا دِیہٕ ژےٚ۔ \n6. تہٕ سُلیمانن ووٚن زِ ژے کٔر پننِس خادم داؤدس میٲنس مٲلس سٍتـ̡ سٮ۪ٹھاہ رحمت، یێلہِ سُہ چُھہ پٔزۍ پٲٹھـ̡ تہٕ نیکی سٍتـ̡ تہٕ دِلہٕ سٍتـ̡ پانس سٍتـ̡ پٲٹھـ̡ پى۪ٹھ\n7. تہٕ وُن، اے خداوند میانہِ خدا، ژے بنوو پنُن خادم داؤد سٕندِ بدلہٕ میون مول، تہٕ بہٕ چُھس اکھ لۄکُٹ شُر: بہٕ چُھس نہٕ پتاہ زِ کِتھ کٔنۍ چُھہ نیبر نیرُن یا اژُن۔ \n8. تہٕ تُہُند خادم چُھہ تُہٕندِس لُکن مَنٛز یُس ژٲرِمُت چُھ، اَکھ بٔڈ لُکھ یُس نہٕ گنزراونہٕ یِتھ تہٕ کٔرِتھ تہٕ گٔنزراوِتھ ہیکو نہٕ۔ \n9. تێمہِ کِنۍ دِیُن پننِس خادمس اکھ سمجھدار دِل یُس پنہٕ نِس لوکن ہُند فیصلہ کرُن، یُتھ بہٕ ہێکہٕ نیکی تہٕ بدس درمیان فرق کرُن، تکیازِ کُس ہیکہِ تُہندس ییتِس عظیم لوکن ہُند فیصلہ کٔرِتھ؟ {سمجُن: عبرانی۔ بوزن}\n10.\\tتہٕ یہ کلام آو خداوند خوش کرنہٕ زِ سُلیمانن اوس یہِ کتھ پرژھمُت۔ \n11. تہٕ خداین ووٚن أمِس زِ کیازِ ژے چُھکھ یہِ کتھ پرژھمٕژ، تہٕ چُھکھ نہٕ پنُن زیچھر وٲنسہٕ منگمُت۔ نَہ چُھہ پننہِ خٲطرٕ دولتُک منٛگمُت، تہٕ نہ چُھکھ پننین دُشمن ہٕنزِ زُوُن منگمُت۔ مگر چُھکھ پنُن پان سمجھنہٕ خٲطرٕ پرژھمُت۔ {زیچھر عمر: ہیب۔ واریاہ دۅہ} {سمجھو: ہیب۔ بوزو}\n12.\\tوُچھو میہ تہندِ کلامَس مُطٲبق کٔرِتھ تہٕ دِژمُت دِل دِژمُت۔ یُتھ زن ژے برونہہ کانہہ تہِ آسہِ نہٕ ژے ہیوٗ کانہہ تہِ تہٕ نہ تہِ ژے ہیوٗ کانہہ تہِ وُہُن۔ \n13. تہٕ مے چُھہ ژے سُہ تہِ دِژمُت یُس نہٕ ژے منگمُت چُھ، دولت تہٕ عزت، یُتھ زن نہٕ تۅہہِ سارِنٕے دۅہہٕ بادشاہن مَنٛز کانہہ تہِ آسہِ۔ {کرُن...: یا چُھہ نہٕ گومُت}\n14. تہٕ یێلہِ ژٕ میانین قونونن تہٕ حکمن ہٕنز پاسداری کرنہٕ خٲطرٕ، یِتھ کٔنۍ تُہند مول ڈیوڈ پکان اوس، تیلہِ کٔرٕ بہٕ چانہِ دۅہ زیٹھراوُن۔ \n15. تہٕ سُلیمان بیدار گوو۔ تہٕ وُچھِتھ اوس یہِ اکھ خواب۔ تہٕ سُہ آو یروشلم، تہٕ خداوند سٕندِ عہد کِس صندوقس برونہہ کُن کھڑا تہٕ دِژن زٲلِتھ نذرانہ پیش تہٕ کٔرٕن پننین سارنٕے خادمن خٲطرٕ دعوت۔ \n16.\\tاَمہ پتہٕ آیہِ زٕ زنانہٕ، یِم زن طوائفہٕ آسہٕ، بادشاہس نِش تہٕ گٔیہٕ أمِس برونہہ کُن کھڑا۔ \n17. تہٕ اَکہِ زنانہِ ووٚن، اے میانہِ مالک، بہٕ تہٕ یہِ زنانہٕ چھِ أکِس گرس مَنٛز روزان۔ تہٕ مےٚ زاے أمِس سٍتـ̡ اَکھ شُر گَرَس مَنٛز۔ \n18.\\tتہٕ یێمہِ دۅہہ گۆو میہ دِنہٕ پتہٕ تریمہِ دۅہہ زِ یہِ زنانہِ تہِ گٔیہِ: تہٕ أسۍ ٲسۍ اَکہٕ وٹہٕ۔ {اَمہِ سٍتـ̡ اوس نہٕ اَسہ سٍتـ̡ اَسہ سٍتـ̡ کانہہ اجنبی شخص، اَمہ سٍتـ̡ أسـ̡ دۅشوے سٍتـ̡ گٔیہِ۔ \n19. تہٕ أمِس زنانہِ ہُند شُر موٗد رٲژ سٍتـ̡ ۔ تکیازِ أمِس گٔیہِ أمِس سٍتـ̡ دِنہٕ آمُت۔ \n20.\\tتہٕ سۅ ووٚتھ نصف رٲژ تہٕ میون نیچو نِش نیُن، ییلہ تۅہہِ نِش شوٚنگِتھ ٲس، تہٕ تھووُن پنُن مردٕ شُر میٲنِس سینس منز۔ \n21.\\tتہٕ ییلہ بہٕ صبحس وۅتھان پننِس شُرس چُھس دِنہٕ خٲطرٕ، وچھ سُہ اوس موٗدمُت: مگر ییلہ میہ صبحس یہ سونچتھ اوس، وچھ یہ اوس نہٕ میون نیچو، یُس میہ زیو۔ \n22.\\tتہٕ بییِس زنانہِ ووٚن، نہ۔ مگر زندٕ چُھ میون نیچو، تہٕ مُردٕ چُھ تُہند نیچو۔ تہٕ یہِ ووٚن، نہ۔ مگر مُردٕ چُھ تُہند نیچو، تہٕ زندٕ چُھ میون نیچو۔ یِتھٕ پٲٹھۍ کٔر تِمو بادشاہس برونہہ کُن۔ \n23.\\tبادشاہن ووٚن زِ یہِ چُھ میون نیچو یُس زندٕ چُھ، تہٕ تُہند نیچو چُھ مُرد، تہٕ بیٛاکھ چُھ ونان نہٕ۔ مگر تُہند نیچو چُھ مُرد، تہٕ میون نیچو چُھ زندٕ۔ \n24.\\tتہٕ بادشاہن ووٚن، مے أنِو اکھ تلوار۔ تہٕ تِمو أنۍ بادشاہس برونہہ کُن تلوار۔ \n25.\\tتہٕ بادشاہن ووٚن زِ زندٕ شُر کٔرِو دۄن حصن منز تقسیٖم تہٕ أکِس دِیُن نٮ۪صف تہٕ بییِس نٮ۪صٕف دِیُن۔ \n26.\\tاَمہ پتہٕ ووٚن زنانہِ یٔمۍ سُند زندٕ شُر بادشاہس سٍتـ̡ اوس، تکیازِ تٔمۍ سٕندِس نیچوِس سٍتـ̡ اوس تٔمِس زِندٕ شُر، تہٕ تٔمۍ ووٚن، اے میانہِ آقا، أمِس دِیُن زِندٕ شُر، تہٕ کٔرِن نہٕ سُہ مٲرِتھ۔ مگر بییِس ووٚن، یہ گژھہِ نہ میون تہٕ نہ تُہُن، {مگر} تقسیم کرُن۔ {تُلُن: حب۔ ٲسٕے گرم}\n27.\\tپتہٕ دیُت بادشاہن جواب تہٕ وونُن، أمِس دِیُن زِندٕ شُر، تہٕ مٲرِن نہٕ أمِس سٕنز موج۔ \n28.\\tتہٕ سارِنٕے اِسرٲیلَن بوز اَمہِ فیصلہٕ سٍتـ̡ یُس بادشاہن دِیُتمُت اوس۔ تہٕ تِمو گٔیہِ بادشاہس سٍتـ̡ کھوژان، تِکیازِ تِمو وُچھ زِ خدایہِ سٕنز حکمت ٲس أمِس مَنٛز ، یُس فیصلہ کَرُن۔ {أمِس منز: عبرانی۔ أمِس منز}","1. یێلہِ اوس بادشاہ سُلیمان سارِنٕے اسرٲیلِس پؠٹھ بادشاہ۔ \n2. تہٕ یِم ٲسۍ تِم شہزادٕ یِم أمِس ٲسۍ۔ عزریاہ زادوک سُند نیچو، {پادٕر: یا، چیف افسر}\n3.\\tالیہورف تہٕ احیٰ، شیشہ سٕندِ نیچو، کاتب۔ یہوشافعت، احیلود سُند نیچو، ریکارڈر۔ {کاتب: یا، سیکرٹری} {ریکارڈر: یا، یادداشت}\n4. تہٕ یہوعیدہ سُند نیچو بنیاہ اوس میزبانس پیٹھ: تہٕ زادوک تہٕ ابیاتھر ٲسۍ پادٕرۍ: \n5.\\tتہٕ ناتھن سُند نیچو عزریاہ اوس افسرن پیٹھ: تہٕ زبد، ناتھن سُند نیچو، {تہٕ}بادشاہ سُند دوس۔ \n6.\\tتہٕ اَہِشار اوس گَرَس پیٹھ: تہٕ اَڈونیرام اوس عَدا سُنٛد نیٚچُو {اوس} خراج دِنہٕ پیٹھ۔ {خراج : یا، لیوی}\n7. تہٕ سُلیمانس ٲسۍ سارِنٕے اسرٲیلِس پیٹھ باہ افسر یِمو بادشاہس تہٕ تٔمۍ سٕندِس گرس خٲطرٕ خوراک فراہم کران ٲسۍ۔ \n8.\\tتہٕ یِمن ہُند ناو: حُر سُند نیچو، افرائیم کِس پہاڑس منز: {نیچو...: یا، بنہور}\n9.\\tدیکر سُند نیچو، مکازس منز، تہٕ شالبیمس مَنٛز، تہٕ بیت شیمش، تہٕ ایلونبیتھنان: {نیچو...: یا، بینڈیکر}\n10.\\tہیسد سُند نیچو، اروبوتس منز؛ أمِس {متعلق} سوچوہ، تہٕ ہیفر سٕنزِ سارِنٕے زمینہٕ: {نیچو...: یا، بینہیسید}\n11.\\tابیناداب سُند نیچو، ڈور کِس سارِنٕے علاقس مَنٛز۔ یٔمِس سُلیمان سٕنزِ کورِ تافتھ ٲس خانٛدارِنہِ: {نیچو...: یا، بینابیناداب}\n12.\\tبعنا احیلود سُند نیچو۔ {أمِس سٍتـ̡ متعلق} تَناخ تہٕ میگیدو، تہٕ سارِنٕے بیت شیان، یُس زرتانہ سٕندِ دٔسۍ یزریلِس بٔنِتھ، بیت شیان پؠٹھٕ ابیلمہولس تام، {حتیٰ کہ} یُس \n13.\\tجبر سُند نیچو، راموتگلاڈس منز؛ أمِس سٍتـ̡ {متعلق} یائر سٕندِس نیچوِس مَنسِس سٍتـ̡ قصبہٕ، یُس {چُھ} جلعادس مَنٛز۔ أمِس سٍتـ̡ {تہِ متعلق} ارگوبُک علاقہٕ، یُس {چُھ} باشانَس مَنٛز، تریہ بٔڈۍ شہر یِمن منز دیوار تہٕ بٔرِس سلاخہٕ چھِ: {نیچو...: یا، بینگیبر}\n14.\\tاِدو سُند نیچو احیناداب {ہَد} مہنایم: {مہنایم: یا، مہنایم}\n15.\\tاحیماذ اوس نفتالی مَنٛز۔ تمٔۍ بنوو سُلیمان سٕنزِ کورِ بسماتھ تہِ زنانہٕ: \n16.\\tحشایی سُند نیچو بعناہ اوس آشر تہٕ علوتس مَنٛز: \n17. پارواہ سُند نیچو یہوشافت، اِساکرس منز: \n18.\\tشیمی یُس ایلا سُند نیچو چھُ، بنیامین منز: \n19.\\tگیبر یُس اُوری سُند نیچو اوس گلعاد کِس ملکس منز، سِحون سُند ملک، یُس امورین ہُند بادشاہ تہٕ اوگ بادشاہ بشان سُند ملک۔ تہٕ {سُہ} اوس وٲحِد افسر یُس زمینس مَنٛز {اوس}۔ \n20.\\tیہوداہ تہٕ اسرٲیلِس سٍتـ̡ سٍتـ̡ یُس سمندرس بٔٹھِس سٍتـ̡ بٔڈِتھ بٔڈِتھ کھٮ۪وان چیوان تہٕ خۅش کران اوس۔ \n21. تہٕ سُلیمانن کٔر دریاو پیٹھٕ فلسطینن ہٕندِس سرزمینس تام تہٕ مصر کِس سرحدس تام سارنٕے سلطنتن پیٹھ حکومت۔ تِمو أنۍ تحفہٕ، تہٕ کٔرٕن سُلیمانس سٕنزِ زندگی ہٕندِس سارِنٕے دۅہن خدمت۔ \n22.\\tتہٕ سُلیمان سٕندِ أکِس دۅہس خٲطرٕ اوس ترٕہ مٔنزۍ نٔوۍ آٹ، تہٕ تریہ پیمانہٕ کھٮ۪ن، {فراہم: ہیب۔ روٹی} {پیمائش: ہیب۔ کورس}\n23.\\tدَہ موٚٹۍ بیل تہٕ وُہ دانٛد، تہٕ ہتھ کۅکرِ تہٕ کۅکرِ تہٕ موٹۍ کۅکر۔ \n24.\\tتکیازِ تس اوس اتھ اندۍ پکھۍ دریاوس پیٹھ، تیفسہ پیٹھہ عزاہ تام، دریاوس اندۍ پکھۍ سارنٕے بادشاہن پیٹھ غلبہ۔ \n25.\\tتہٕ یہوداہ تہٕ اسرٲیلِس روٗد پَنٕنِس بیلس تَل تہٕ انجیر کُلِس تَل روزان، دان پیٛٹھٕ بیرشبع تام، سُلیمان سٕندِس سارِنٕے دۅہہٕ سٍتـ̡ روزان۔ {محفوٗظ پٲٹھۍ: حب۔ یقین سان}\n26.\\tتہٕ سُلیمانس نِش ٲسۍ پننین رتھن خٲطرٕ ژتٲجی ساس گُرِ تہٕ باہ ساس گُرۍ سوار۔ \n27. تہٕ تِمو افسرو کٔر بادشاہ سلیمان سٕندِ خٲطرٕ تہٕ یُس بادشاہ سلیمان سٕندِس میزس پیٹھ یِوان اوس، تِمن ٲس نہٕ کُنہِ تہِ کٔمی۔ \n28.\\tگُرٮ۪ن تہٕ ڈرومیڈرین ہٕندِ خٲطرٕ تہٕ گاسہٕ تہٕ گاسہٕ أنِتھ تِم تتھ جایہِ ییتہِ {افسر} ٲسۍ، پرٮ۪تھ کانہہ نفر پننہ ذمہ دارس مطٲبق۔ {ڈرومیڈری: یا، خچر، یا، تیز درندٕ}\n29. تہٕ خداین دِژ سلیمانس سمندرس سٍتـ̡ سٮ۪ٹھاہ دانٲیی تہٕ فہم تہٕ دِل سٍتـ̡ س� \n30.\\tتہٕ سُلیمان سٕنز حکمت ٲس مشرق کِس سارِنٕے شُرین ہٕنزِ تہٕ مصرٕچ سارِنٕے حکمتَس سٍتـ̡ س� \n31.\\tتکیازِ سُہ اوس سارِنٕے انسانو کھۅتہٕ زیادٕ عقلمند۔ ایتھن عزراہیت تہٕ ہیمان، تہٕ چالکول تہٕ دردا سٕندِ نیچو، تہٕ تٔمۍ سٕنز شہرت ٲس اندۍ پٔکۍ سارنٕے قومن مَنٛز۔ \n32.\\tتہٕ تٔمۍ سٕندِ بٲتھ ٲسۍ ساس پانژھ۔ \n33.\\tتہٕ تٔمۍ کُلٮ۪ن ہٕنز کتھ کٔرِتھ، یُس لبنان مَنٛز {چُھ} چُھ، یُس دیوارٕ منزٕ نیرن وٲلِس کُلِس تام تہٕ کُلٮ۪ن ہٕنز کتھ کٔر۔ \n34.\\tتہٕ سارِنٕے لُکھ آو سُلیمان سٕنز حکمت بوزنہٕ خٲطرٕ، یِمو تٔمۍ سٕنزِ حکمتٕچ خبر بوزمٕژ ٲس۔","1. تہٕ صور کِس بادشاہ حیرام سوٗزۍ پنٕنۍ خادم۔ تِکیازِ تٔمۍ اوس بوزمُت زِ تِمو اوس أمِس مٲلہِ سٕندِس کمرس مَنٛز بادشاہ مسح کورمُت، تکیازِ ہیرم اوس داؤد سُند عاشق ۔ {حیرام: یتھ تہِ ونان چھِ}\n2.\\tتہٕ سُلیمانن سوز حیرامس نِش یہِ وَنُن، \n3. ژے چھے پتاہ زِ میون مول کِتھ کٔنۍ ہیوٚک نہٕ خداوند سٕندِس خدایہ سٕندِس ناوٕ سٍتـ̡ مکانہٕ بنٲوِتھ یُس پریتھ طرفہٕ أمِس اندۍ پکھۍ ٲس، یوتام نہٕ خداوند تِم پننین کھورَن تلہٕ تھٲوِتھ۔ \n4.\\tمگر وۅنۍ چُھہ خداوند میانہِ خدایہ میہ پریتھ طرفہٕ آرام دِژمُت، {یُتھ زن نہٕ کانہہ دُشمن تہٕ بد کار آسہِ}۔ \n5. تہٕ وُچھِتھ چُھس بہٕ خداوند پننِس خدایہ سٕندِس ناوٕ سٍتـ̡ اکھ مکانہٕ بناوُن، یِتھٕ کٔنۍ خداوند پننِس مٲلِس سٍتـ̡ وونُن زِ تُہند نیچو، یُس بہٕ چانہِ تختس پیٹھ تہندِس کمرس مَنٛز بِہناوُن، سُہ بناوِ میانہِ ناوٕ خٲطرٕ اکھ مکانہٕ۔ {مقصد: ہیب۔ وَن}\n6. تێمہِ کِنۍ دِیُن حُکُم زِ تِم کٔرِن لبنان منزٕ دِودار کُلۍ۔ تہٕ میٲنۍ خادم آسن تہندٮ۪ن خادمَن سٍتـ̡ تہٕ بہٕ دِیہٕ تۅہہِ سٍتـ̡ تہندٮ۪ن خدمتگارن ہٕندِ خٲطرٕ یُس تہٕ ژے مقرر کرُن، تِکیازِ ژے چُھہ پتاہ زِ اسہِ مَنٛز چُھنہٕ کانہہ تہِ یُس سِدونین ہٕندۍ پٲٹھـ̡ لٔکر ژٹنہٕ خٲطرٕ ہٲوِتھ۔ {مُقرر کٔرِو: حب۔ وَن}\n7. تہٕ ییلہ حیرام سُلیمان سٕنز کتھ بوٗز، تٔمِس گوٚو سٮ۪ٹھاہ خۅش تہٕ وونُن، خداوند سُند بابرکت آسُن، یٔمۍ داؤدس یِمن عظیم لُکن ہُند اکھ عقلمند نیچو دِیُت۔ \n8.\\tتہٕ ہیرامن سوز سُلیمانس نِش وونُن زِ مے چُھس تِمن چیزن پیٹھ غور کورمُت یِمن خٲطرٕ ژے مے سوزمُت چھُ: {تہٕ} بہٕ کَرٕ تُہٕنز سارِنٕے خواہش۔ {غور کٔرِتھ: ہیب۔ بوزمُت}\n9.\\tمیانہِ خادم اَنِن لبنان پیٹھٕ سمندرس تام، تہٕ بہٕ واتناوٕ تِم سمندرٕ کہِ ذریعہٕ تتھ جایہِ تام واتناوُن یُس ژے مُقرر کرِ، تہٕ تِم کٔرِکھ تتہِ رٔٹِتھ تہٕ تہٕ ژے کٔرِکھ میانہِ گرٕ کھٮ۪ن دِنہٕ سٍتـ̡ میٲنۍ خٲہش پورٕ۔ {مُقرر: ہیب۔ سوزُن}\n10.\\tیِتھ دِژ حِرامَن سُلیمان دیودار کُلۍ تہٕ فر کُلۍ پننہِ مرضی مُطٲبق۔ \n11. تہٕ سُلیمانن دِژ حیرامس پننِس گرس کھیٛنہٕ خٲطرٕ وُہ ساس کٕنُک تہٕ خالص تیٖل وُہ پیمانہٕ، یِتھٕ پٲٹھۍ دِژ سُلیمانس ؤری پتہٕ ؤری۔ {پیمائش: ہیب۔ کورس}\n12. تہٕ خداوند دِژ سلیمانس حکمت، یُتھ زن تٔمۍ أمس وعدٕ کوٚر، تہٕ ہیرمس تہٕ سُلیمانس درمِیان اوس امن ۔ تہٕ یِمو دۅنویو بنوو اِکہٕ وٹہٕ اکھ لیگ۔ \n13.\\tتہٕ بادشاہ سُلیمانن کٔر سارِنٕے اِسرٲیلِس مَنٛز اکھ لیوی۔ تہٕ سُہ اوس ترہ ساس نفر۔ {لیوی: عبرانی۔ انسانَن ہُند خراج }\n14.\\tتہٕ سوٗزۍ تِم لبنان کُن، دَہ ساس فی ریتہٕ کورس: اکھ ریتہٕ ٲسۍ لبنانس منز، تہٕ زٕ ریتن گَرِ منز: تہٕ اڈونیرام اوس لیوی پیٹھ۔ \n15.\\tتہٕ سُلیمانس نِش ٲسۍ تریہ تہٕ داہ ساس یِم بور تہٕ ژور ساس پہاڑن مَنٛز ٲسۍ۔ \n16.\\tسُلیمان سٕندِس افسرس سٍتـ̡ یُس اتھ کامہِ پیٹھ کٲم کران اوس، تریہ ساس تریہ ہتھ، یُس کامہِ منز کٲم کرن والین لوکن پیٹھ راج کران اوس۔ \n17.\\tتہٕ بادشاہن دیُت حُکُم، تہٕ تِمو أنۍ بٔڈۍ کٔنہِ، قۭمتی کٔنہِ، تہٕ کٔرِکھ کٔنہِ کٔرِتھ گرٕچ بُنیاد تراونہٕ خٲطرٕ۔ \n18.\\tتہٕ سُلیمان سٕندٮ۪و معمارو تہٕ ہیرم سٕندیو معمارو کٔر تِمن تہٕ کٔنہِ ہٕندِس بٔنِس سٍتـ̡ تہٕ کٔنہِ کٔرِتھ کٔرِتھ مکانہٕ بناونہٕ خٲطرٕ۔ {کٔنِس مربعہٕ: یا، گبلٹس}","1.\\tتہٕ سپُد ژۅن ہتھ ٲٹھِس ؤریس مَنٛز یُس بنی اسرائیل سٕندِ سرزمینہٕ منزٕ نیرنہٕ پتہٕ، سُلیمان سٕندِ حکومتہٕ کِس ژوٗرِمِس ؤریس مَنٛز، یُس دوٚیِم ریتھ چُھ، یُس تٔمۍ خداوند سُند گرٕ تعمیر کرُن شروع کوٚر۔ {شروع...: عبرانی۔ تعمیر کرنہٕ}\n2. تہٕ سُہ مکانہٕ یُس بادشاہ سُلیمانن خداوند سٕندِ خٲطرٕ بنوومُت اوس، اَمیُک زیچھر اوس ترے ہور کیوبِٹ، تہٕ اَمیُک کھجر اوس وُہ کیوبِٹ، تہٕ اَمیُک تھزر اوس ترہ کیوبِٹ۔ \n3.\\tتہٕ مکانہ کس مندرس برونہہ کُن برآمد، مکانہ کس کھجرس مطٲبق اوس وُہ کیوبٹ زیچھر۔ {تہ} مکانہ برونہہ کنہِ اوس داہ کیوبِٹ۔ \n4.\\tتہ مکانہ خاطرہ بنوو تنگ گاشہ دارۍ۔ {منز...: یا، اندرم کھٔرۍ، تہ نیبر تنگ: یا، کٔرِتھ تہ بند}\n5.\\tتہٕ مکانہٕ کِس دیوارس سٍتـ̡ بنوو تٔمۍ اندۍ خانہٕ، {خلاف} مکانٕچ دیوار، {مندرٕچ تہٕ اوریکلٕچ دۄشوٕنی} تہٕ تٔمۍ بنوو اندۍ کمرہٕ: {دیوارس خلاف: یا، پیٹھ، یا، دیوارس سٍتـ̡ رٔلِتھ}{بٔنِتھ خانہٕ: ہیب۔ بٔنِتھ فرش} {بٔنِتھ خانہٕ: ہیب۔ بٔنِتھ رِب}\n6.\\tزیرِ کُنہِ خانہٕ اوس پانژھ کیوبٹ کھُلہٕ تہٕ منزم اوس شیہ کیوبٹ کھُلہٕ تہٕ تریم اوس ستھ کیوبٹ کھُلہٕ: تکیازِ مکانہ کس دیوارس منز اوس تٔمۍ اندۍ اندۍ اندۍ تنگ کٔرِتھ، زِ {بیم} گژھن نہٕ مکانہ کس دیوارس منز بند کرنہٕ۔ {تنگ...: ہیب۔ تنگ کرُن، یا، رعایت}\n7.\\tتہٕ مکانہٕ ییلہ یہ عمارتس منز اوس، سہ اوس کنیو سٍتۍ بناونہٕ آمُت یُس تتہِ اننہٕ برونہہ، یُتھ مکانس منز اوس نہٕ ہتھوڑا تہٕ نہ کلہٕ تہٕ نہ ششتٕرُک کانہہ اوزار بوزنہٕ آمُت۔ \n8.\\tمنزمہِ کمرک دروازہ اوس مکانہ کس دچھنہِ طرفہ تہ تم گٔیہ منزمس کمرس منز ہیرن سیتۍ تہ منزمہِ منزمہِ منزۍ تریمس حصس منز۔ {طرف: ہیب۔ پھیپھ}\n9. تہٕ تٔمۍ بنوو مکانہٕ، تہٕ مکمل۔ تہٕ گرٕ کورُن دیودار سٕندیو بیمو تہٕ تختو سٍتۍ۔ {سٍت...: یا، والٹ بیمز تہٕ پینلنگ دیودار سٍتۍ}\n10.\\tتہٕ {پتہٕ} بنوو تٔمۍ سارنٕے گرس خلاف پانژھ کیوبٹ تھوٚد: تہٕ تِم کٔر گرس پیٹھ دِودار کِس لٔکرِ سٍتـ̡ آرام دِنہٕ۔ \n11. تہٕ خداوند سُند کلام آو سُلیمانس نِش وَنُن، \n12. یێمہِ گرس مُتلِق یُس ژے بناوان چُھ، تێلہِ چُھکھ میانین قونونن مُطٲبق، تہٕ میانین فیصلن پیٹھ عمل کٔرِو، تہٕ میانین سارِنٕے حُکمن ہُند عمل کرُن یێلہِ تێلہِ پَکُن پَکُن۔ تێلہِ کٔرٕ بہٕ ژے سٍتـ̡ پنُن کلام پورٕ، یُس میہ پننِس مٲلِس داؤدس سٍتـ̡ کتھ کٔرمٕژ چُھ: \n13.\\tتہٕ بہٕ روزٕ بنی اسرٲیلِس مَنٛز روزُن، تہٕ بہٕ روزٕ نہٕ پنٕنـ̡ لُکہٕ اِسرٲیلـ̡ تراوُن۔ \n14.\\tیێلہِ بنوو سُلیمانن مکانہٕ تہٕ مُکمل کٔرِتھ۔ \n15.\\tتہٕ تٔمۍ بنٲو مکانٕچ دیوارٕ دِودار سٍتۍ، مکانُک فرش تہٕ چھتٕچ دیوارٕ دۅشوے سٍتۍ: {تہٕ} تٔمۍ بنوُن أنٛدرِمِس طرفہٕ لٔکرِ سٍتۍ، تہٕ مکانُک فرش کورُن فر کِس تختو سٍتـ̡ ؤلِتھ۔ {دۅنوے...: یا، مکانہٕ کِس فرشہٕ پیٹھٕ دیوارن تام، بیترِ}\n16.\\tتہٕ تٔمۍ بنٲو مکانہٕ کِس اندۍ پکھۍ، فرش تہٕ دیوارٕ دِودار سٍتـ̡ وُہ کیوبِٹ، یێلہِ تہِ بنوُن اَتھ مۅکھہٕ {تِم} خٲطرٕ، {حتیٰ کہ} حتیٰ کہ مُقدس {جاے} خٲطرٕ۔ \n17. تہٕ مکانہٕ، یعنی {is}، اتھ برونہہ کُن مندر، اوس ژتٲجی کیوبِٹ {زیوٹھ}۔ \n18.\\tتہٕ مکانُک دیودار {اوس} کُنہِ کُنہِ تہٕ یلہٕ پوشو سٍتۍ تراشنہٕ آمُت: سارِنٕے {اوس} دیودار۔ اَتہِ اوس نہٕ کانہہ کَنہِ وُچھنہٕ آمُت۔ {کُنہِ\n19. تہٕ یُس اوریکل تٔمۍ اَتھ گرس مَنٛز تیار کٔر، یُس خداوند سٕندِ عہدُک صندوق قٲیم کرنہٕ مۅکھہٕ۔ \n20.\\tتہٕ برٛونٛہمِس حصس مَنٛز اوس وُہ کیوبِٹ زیچھر، تہٕ وُہ کیوبِٹ تہٕ تھزرس مَنٛز وُہ کیوبِٹ: تہٕ تٔمۍ کٔر اتھ خٲلص سۄنہٕ سٍتـ̡ ؤلِتھ۔ تہٕ {یێلہِ} کورُن قربان گاہ {یُس} دیودارُک اوس۔ {خالص: عبری۔ ژھۄپہٕ کٔرِو}\n21.\\tیِتھ کٔر سُلیمانن اَتھ مکانس خٲلص سۄنہٕ سٍتـ̡ ؤلِتھ تہٕ تٔمۍ بنوو سۅنہٕ سٍتـ̡ \n22.\\tتہٕ سورُے گرٕ سُہ سُہ سۄنہٕ سٍتـ̡ ؤلِتھ، یوتام تٔمۍ سٲرۍسٕے گرٕ مُکمل کٔرِتھ، تہٕ سُہ سورُے قربان گاہ یُس سُہ سۄنہٕ سٍتـ̡ بٔنِتھ اوس۔ \n23.\\tتہٕ اوریکلس اندر بنوو تٔمۍ زٕ کرُبِم {of} زیتون کُلِ، {پرٮ۪تھ کُل} دَہ کیوبِٹ تھوٚد۔ {زیتون: یا، تیل: ہیب۔ تیلٕکۍ کُل}\n24. تہٕ پانژھ کیوبِٹ اوس کروبُک اکھ پکھہ، تہٕ پانٛژھ کیوبِٹ کروبُک بیٛاکھ پکھہٕ: اَکہِ پکھہٕ پیٹھٕ دوٚیمہِ پکھہٕ کِس اندِس حصس تام ٲس داہ کیوبِٹ۔ \n25.\\tتہٕ دوٚیِم کرُب {اوس} داہ کیوبِٹ: دۅشوے کرُب {ٲس} اَکہِ پیمانہٕ تہٕ اَکہِ سائزٕک۔ \n26.\\tأکِس کروبس ہُند تھزر اوس داہ کیوبِٹ، تہٕ یِتھے پٲٹھۍ اوس بییِس کروبس ہُند تھزر۔ \n27.\\tتہٕ تِمو کٔر کرُبن ہٕندِس پکھہٕ پکھہٕ یُس أکِس دیوارس سٍتـ̡ لٔگِتھ تہٕ بییِس کرُبِم سٕندِ پکھہٕ لٔگِتھ لٔگِتھ تہٕ بییِس پکھہٕ لٔگِتھ لٔگِتھ گٔیہِ۔ تہٕ تِمن ہٕندِس پکھہٕ گٔیہِ گرس منز اکھ أکِس سٍتـ̡ اَکھ أکِس سٍتـ̡ رٔلِتھ۔ {تِم...: یا، کروبِمو پھٔہلٲوِتھ پَکھہٕ}\n28.\\tتہٕ تٔمۍ کٔر کروبِمن سٍتـ̡ سۄنہٕ سٍتـ̡ سٍتـ̡ سٍتـ \n29.\\tتہٕ تٔمۍ بنٲوۍ مکانٕچ تمام دیوارٕ اندۍ اندۍ پٔکھۍ کروبِم تہٕ کھجور کُلٮ۪ن تہٕ کھجورن ہٕنزِ شکلہٕ سٍتۍ تراشنہٕ۔ {یلہٕ پوش: ہیب۔ پوشن ہٕندِ کھلنہٕ}\n30. تہٕ مکانُک فرش اوس سۄنہٕ سٍتـ̡ س \n31.\\tتہٕ اوریکل کس اژنہٕ خٲطرٕ بنوو تٔمۍ دروازٕ {of} زیتون کُلۍ: لِنٹل {تہٕ} سائیڈ پوسٹ {ٲس} دیوارُک پونژم حصہٕ}۔ {اکھ پونژم...: یا، پانژھ مربعہٕ}\n32.\\tدۅشوے دروازٕ تہِ ٲسۍ زیتون کُلِس پیٹھ۔ تہٕ تِمن پیٹھ کٔرٕن کروبِم تہٕ کھجور کُلٮ۪ن تہٕ یلہٕ پوشن ہٕنز نقش و نگار، تہٕ تِمن پیٹھ سۄنہٕ سٍتـ̡ تہٕ کھجورن ہٕندِس کُلِس پیٹھ پھٔہلٲوِن سۄنہٕ۔ {زٕ...: یا، دروازن ہٕندِس پنہٕ ؤتھٕر} {یلہٕ پوشہٕ: ہیب۔ پوشن ہٕندِ کھلہٕ}\n33.\\tیِتھے پٲٹھـ̡ بنوو تٔمۍ مندر کِس دروازٕ خٲطرٕ {of} زیتون کُلِ، یُس ژوٗرِم حصہٕ {دیوارُک} چُھ۔ {ژوٗرِم...: یا، ژور مربع}\n34.\\tتہ دۅشوے دروازہ ٲسۍ فر کُلِس منز: اکہ دروازہ ہندۍ زہ پنہٕ ؤتھر تہ بییِس دروازہ ہندۍ زہ پنہٕ ؤتھر ٲسۍ فولڈ گژھان۔ \n35.\\tتہٕ تٔمۍ کٔرِن کرُبِم تہٕ کھجور کُلۍ تہٕ یلہٕ پوش تہٕ کھٔنِتھ کٔرِن سۄنہٕ سٍتۍ ؤلِتھ۔ \n36.\\tتہٕ تٔمۍ بنوو اندرونی صحن تریہ لٲنہٕ تہٕ دیودار بیمن ہٕنز اکھ قطار۔ \n37.\\tژوٗرمہِ ؤریس مَنٛز آو رب سٕندِ گرٕچ بُنیاد تراونہٕ، یُس زِف کِس رٮ۪تس مَنٛز آو تراونہٕ: \n38.\\tتہٕ کٔہمہِ ؤریس مَنٛز، بُل رٮ۪تس مَنٛز، یُس ٲٹھِم رٮ۪تھ چُھ، اَمہ کِس سارِنٕے حِصس مُطٲبِق اوس مکانہٕ مُکمل گومُت۔ یِتھے پٲٹھۍ اوس سَتھ ؤری یہِ تعمیر کرنہٕ آمُت۔ {اَمہ کِس سارِنٕے حِصہٕ سٍتـ̡ تہٕ سارِنٕے احکام سٍتـ̡ ﴿","1.\\tمگر سلیمان اوس ترہ وُہرۍ پنُن مکانہ بناوان، تہٕ تٔمۍ کٔر پنُن سورے مکانہ مکمل۔\n2. تٔمۍ بنوو لبنان کِس جنگلُک مکانہٕ تہِ۔ امیک زیچھر اوس اکھ ہتھ کیوبٹ، تہٕ امیک کھجر اوس پنژاہ کیوبٹ، تہٕ امیک تھزر اوس ترہ کیوبٹ، دیودار ستونن ہندس ژورن قطارن پیٹھ، ستونن پیٹھ دیودار بیم۔\n3. تہٕ {یہ} اوس ہیرِ کُن دیودار سٍتۍ ؤلِتھ، یُس {پنٛژتٲجی تھمبَن پیٹھ} پنٛداہ {منز} أکِس قطارس پیٹھ۔ {بیمز: ہیب۔ رِب}\n4.\\tتہ {اتہِ} دٲر {منز} تریہ لٲنہِ، تہٕ گاش {اوس} گاشس خلاف {منز} تریہ صف۔ {گاش اوس...: ہیب۔ گاشس خلاف وژن}\n5.\\tتہٕ سارِنٕے دروازٕ تہٕ دٲرِ سٍتۍ {ٲس} مربعہٕ: تہٕ گاش {اوس} گاشس خلاف {منز} تریہ درجہٕ۔ {دروازٕ...: یا، جاے تہٕ ستون ٲسۍ امکانس منٛز مربعہٕ}\n6. تہٕ تٔمۍ بنوو ستونن ہُند پورچ۔ امیک زیچھر اوس پنژاہ کیوبٹ، تہ امیک کھجر اوس ترہ کیوبٹ: تہ یمن برونہہ کنہِ اوس پورچ {باقی} ستون تہ موٚٹ شہتیر {یِمن برونہہ کنہِ}۔ {تمن برٛونٛہہ: یا، تمن مطٲبق}\n7.\\tتمہ پتہ بنوو تمۍ تختہ خاطرہ اکھ پورچ ییتہِ سُہ فیصلہ کرِ، {حتیٰ کہ} فیصلہٕ کِس پورچس تہِ: تہٕ {یہ} اوس فرشہٕ کہِ اکہِ طرفہٕ دوٚیمس اندس تام دیودار سٍتۍ ؤلِتھ۔ {پیٹھ...: ہیب۔ فرش پیٹھ فرشس تام}\n8.\\tتہٕ تٔمۍ سُند مکانہٕ یَتھ منز سُہ روزان اوس، یُس دٲرس اندر بیاکھ صحن اوس، {یُس} اوس یِتھی کامہِ ہُند آسان۔ سُلیمانن بنوو فرعون سٕنزِ کورِ خٲطرٕ تہِ اکھ مکانہٕ، یۅسہٕ أمِس اَتھ آوارِ ہٕندۍ پٲٹھۍ{خانٛدارِنہِ} نِیومٕژ ٲس۔\n9.\\tیم سٲری ٲسۍ قۭمتی کنۍ، ژٹنہٕ آمٕتۍ کنن ہٕندِ پیمانہٕ مطٲبق، لٔٹِتھ لٔٹِتھ ژٔٹِتھ تہٕ نیبَر، بنیادٕ پیٹھٕ کوپِنگس تام، تہٕ نیٚبرِم کُن عظیم دربارس کُن۔\n10.\\tتہٕ بُنیاد ٲس قۭمتی کنن، بٔڈۍ کٔنۍ، دہن کیوبٹن ہٕندِ کنہِ تہٕ ٲٹھن کیوبٹن ہٕنز۔\n11.\\tتہٕ ہیرِ کُنہِ کٔنہِ تہٕ دیودار ہٕندِس پیمانس پیٹھ ٲسٕکھ قۭمتی کٔنہِ۔\n12.\\tتہٕ بٔڈ صحن اندۍ پکھۍ ٲس تریہ لٲنہٕ ژٔٹِتھ کنن تہٕ دیودار بیمن ہٕنز اکھ قطار، دۄشوے رب سٕندِ گرٕ کِس اندرمِس صحنس خٲطرٕ، تہٕ گرٕ کِس دٲرٕ خٲطرٕ۔\n13. تہٕ بادشاہ سُلیمانن سوٗز تہٕ أنِن حیرام صور منٛز۔ {ہیرم: یتھ تہِ ونان چھہِ}\n14.\\tسُہ اوس نفتالی قبیلُک بیواہ سُند نیچو، تہٕ تٔمۍ سُند مول اوس صورُک انسان، پیتلُک کٲم کَران۔ تہٕ سُہ اوس دانٲیی تہٕ سمجھ تہٕ چالاکی سٍتـ̡ سارِنٕے کامہِ سٍتـ̡ کٲم کٔرِتھ۔ تہٕ سُہ آو بادشاہ سلیمانس نِش، تہٕ کٔرٕن پنٕنۍ سورے کٲم۔ {اکھ بیواہ ہُند...: ہیب۔ بیواہ زنانہِ ہند نیچو}\n15.\\tتکیازِ تٔمۍ ترٲوۍ پیتلٕکۍ زٕ تھم، ارداہ کیوبِٹ تھدِ تھوٚد: تہٕ بہن کیوبٹن ہٕنز اکھ لٲن ٲس یمن منز کُنہِ أکِس اندۍ گٔمٕتۍ۔ {کاسٹ: ہیب۔ فیشن}\n16.\\tتہ بنوو تمٔۍ زٕ پگلہٕ پیتل، یُس تھمَن ہٕندِس تینتٲلس پیٹھ تھاونہٕ خٲطرٕ: أکِس کپتانہٕ سُند تھزر اوس پانژھ کیوبِٹ، تہٕ بیٚیِس کُپِرِ سُند تھزر اوس پانژھ کیوبِٹ:\n17.\\tچیکر کامہِ ہٕندِ جال، تہٕ زنجیرن ہٕندِ کامہِ ہٕندِ گُلہٕ ، یِم تھمن ہٕندِس تھزرس پیٹھ ٲسۍ۔ أکِس چیپِٹر سٕندِ خٲطرٕ ستھ تہٕ بیٚیِس چیپِٹر سٕندِ خٲطرٕ ستھ ۔\n18.\\tتہٕ تٔمۍ بنوو أکس جالس پیٹھ تھم تہٕ زٕ قطارٕ اندۍ دِنہٕ خٲطرٕ، تہٕ تٔمۍ کٔر بییِس کپترس سٍتـ̡ تہٕ تٔمۍ تہِ کٔر بییِس کپترس سٍتـ̡\n19.\\tتہٕ یم چپٹر یم تھمن پیٹھ {ٲس} لِلہِ ہٕندِس تھزرس پیٹھ ٲسۍ، ژور کیوبٹ۔\n20.\\tتہٕ دۅن ستونن پیٹھ دٲن تہِ ٲسِس دٲر تہِ، یُس جالس سٍتۍ {اوس} تہٕ دٲن {ٲس} دوٚیمس چیپِٹرس اندۍ زٕ ہتھ لٲنہِ منز۔\n21.\\tتہٕ تٔمۍ تھووُن دٔچھُن تھَم تہٕ دٔچھُن تھَم قٲیِم، تہٕ وَنُن اَتھ کُن یَچن ناو، تہٕ تٔمۍ تھووُن کھوورِ تھَم تہٕ وَنُن بوعزُک ناو۔ {جاچین: یعنی سُہ کرِ قٲیم} {بوز: یعنی اتھ منز چھہ طاقت}\n22.\\tتہٕ ستونن پیٹھ ٲس لِلہِ ہٕنز کٲم: یِتھے پٲٹھۍ سپٕز ستونن ہٕنز کٲم مکمل۔\n23.\\tتہٕ تٔمۍ بنوو اَکہِ اندۍ پکھۍ دَہ کیوبِٹ سمندر، اَکہِ اندۍ پکھۍ دَہ کیوبِٹ: {یہ} اوس اندۍ تہٕ تٔمۍ سُند تھزر اوس پانژھ کیوبِٹ: تہٕ ترہن کیوبٹن ہُند اکھ لٲنہٕ اوس اَتھ اندۍ {پیٹھ...: ہیب۔ تٔمۍ سٕندِ دٔرِ پیٹھٕ تٔمۍ سٕندِس دٔرِس تام}\n24.\\tتہ اتھ اندۍ\n25.\\tیہ اوس باہ بیلن پیٹھ کھڑا، تریہ شمالس کُن تہ تریہ مغرب کُن تہ تریہ جنوبس کُن تہ تریہ مشرقس کُن نظر۔\n26.\\tتہ یہ اوس اتھہ موٚٹ تہ امیک اند اوس پیالہِ ہندۍ پاٹھۍ بناونہ آمت، یتھ منز لِلہِ ہندۍ پوش ٲسۍ، اتھ منز ٲسۍ زٕ ساس باتھ آسان۔\n27. تہٕ تٔمۍ بنٲو داہ پیتلٕچ بنیاد۔ ژور کیوبٹ اوس اکس اڈس زیچھر، تہٕ ژور کیوبٹ زیچھر تہٕ تریہ کیوبٹ امیک تھزر۔\n28.\\tتہٕ اڈن ہنز کٲم ٲس اتھ {طریقس} پیٹھ: تمن ٲس سرحد، تہٕ سرحد ٲس لیجن درمیان:\n29.\\tتہ یمن سرحدن پیٹھ یم {ٲس} شیر، بیل تہ کروبیم: تہ لجن پیٹھ اوس ہیرِ کُن اکھ اڈہ: تہ شیرن تہ بیلن تلہ کنہِ ٲس کینہہ اضافہ۔\n30.\\tتہٕ پرٮ۪تھ اڈس ٲس ژور بریسن چکر، تہٕ پیتلٕچ پلیٹہٕ: تہٕ اَمہ کِس ژۅشونی کونس منز ٲس انڈر سیٹر: لاورَس تلہ کنہِ ٲس انڈر سیٹرس پگلۍمٕتۍ، پرٮ۪تھ أکِس اضافس سٍتۍ۔\n31.\\tتہ امچ ٲسس کپترس اندر تہ ہیرِ کُن اکھ کیوبِٹ: مگر امیک ٲسس {پَتہٕ} گول {پتہ} اڈٕ کُن، اکھ کیوبِٹ تہٕ: تہٕ امہِ کِس ٲسس پیٹھ تہٕ ٲسٕکھ کھورِ سٍتۍ، ژور مربعہٕ، گول نہٕ۔\n32. تہٕ سرحدن تل ٲسۍ ژور پٔکرۍ۔ تہٕ چکرٕکۍ ایکسل ٹری {ٲسۍ جُڑِتھ} دامنس سٍتۍ: تہٕ چکرُک تھزر اوس اکھ کیوبِٹ تہٕ نصف کیوبِٹ۔ {شٲمِل...: ہیب۔ بنیادس منز}\n33.\\tتہٕ چکرِ ہٕنز کٲم ٲس رتھن ہٕندِ چکرِ ہٕنز کٲم ہٕندۍ پٲٹھۍ: تِہٕندِس ایکسلٹری، تہٕ تِہٕنزِ ناف، تہٕ تِہٕندِس فیلو، تہٕ تِہٕندِس سپوکس، سارِنٕے گٔیہِ۔\n34.\\tتہ {اکۍ سے اڈس ہندین ژۅشونی کونن منز ٲسۍ ژور انڈر سیٹر:{تہِ} انڈر سیٹرس {ٲس} اڈہ پیٹھ۔\n35.\\tتہ اڈہ کس پیٹھمس حصس منز اوس نصف کیوبٹ تھوٚد اکھ گول کمپاس: تہ اڈہ کس پیٹھمس حصس پیٹھ ٲس امکۍ لیج تہ امکۍ کنارہ {ٲس}۔\n36.\\tتِکیازِ تِمن ہٕندِس پتھرن پیٹھ تہٕ اَمہ کِس اندس پیٹھ کٔرِن تٔمۍ کرُبِم، شیر تہٕ کھجور کُلۍ، پرٮ۪تھ أکِس سٕندِ تناسب مُطٲبق، تہٕ اندۍ پٔکھۍ اضافہٕ۔ {تناسب: ہیب۔ ننگہٕ}\n37.\\tامہ {طریقہ} پتہ بنوو تمۍ داہ بنیاد: یمن سارنی ٲس اکھ کاسٹنگ، اکھ پیمانہ، {تہ} اکھ سائز۔\n38.\\tامہ پتہ بنوو تمۍ داہ لۅتہِ پیتل: اکس لاوس منز ژتٲجی غسل خانہ: {تہ} پریتھ لاور اوس ژور کیوبٹ: {تہ} دہن اڈن منز پریتھ اکس پیٹھ اکھ لاور۔\n39.\\tتہٕ تٔمۍ تھووُن مکانہٕ کِس دٔچھنِس طرفہٕ پانژھ اڈٕ، تہٕ پانژھ بُنیاد مکانہٕ کِس دٔچھنِس طرفس کُن، تہٕ تٔمۍ تھوو مکانہٕ کِس دٔچھنِس طرفہٕ جنوبس کُن مشرقس کُن۔ {سائیڈ: ہیب۔ کندھ}\n40.\\tتہٕ ہیرامن بنوو لۅتہٕ تہٕ بیلچہ تہٕ بیسن۔ چنانچہ ہیرمن کٔر سٲرۍے کٲم بند یُس تٔمۍ بادشاہ سلیمان رب سٕندِ گرٕ خٲطرٕ بنوو: {تہٕ ہیرام: ہیب۔ تہٕ ہیروم}\n41.\\tدۅشوے تھم، تہ چیپٹرن ہندۍ {زٕ} پیالہ یم دۅن تھمن پیٹھ ٲسۍ۔ تہٕ زٕ نیٹ ورک، چیپٹرن ہٕندۍ زٕ پیالہٕ ؤلنہٕ خٲطرٕ یم تھمن پیٹھ ٲسۍ۔\n42. تہٕ ژور ہتھ انار دۅن جالن خٲطرٕ، {حتیٰ کہ} أکِس جالس خٲطرٕ زٕ قطارٕ دٲن، یِم تھمن پیٹھ {ٲس} چیپٹرن ہٕندِس زٕ پیالہ ؤلِتھ۔ {on...: Heb. ستونن ہندس بُتھس پیٹھ}\n43. تہٕ داہ بیس، تہٕ داہ لاور؛\n44. تہٕ اکھ سمندر، تہٕ سمندرس تل باہ بیل۔\n45.\\tتہٕ بانہٕ، بیلچہٕ تہٕ بیسن: تہٕ یِم سٲری بانہٕ، یِم ہیرمن بادشاہ سلیمانس رب سٕندِ گرٕ خٲطرٕ بنوومٕتۍ، ٲسۍ چمکدار پیتلٕکۍ آسان۔ {روشن: ہیب۔ چمکدار یا، ژھانڈنہٕ آمُت}\n46.\\tاردن کِس مٲدانس مَنٛز ترٛٲو بادشاہن یِم سوکوتھ تہٕ زرتھنس درمِیان میژِ مٲدانس منز۔ {منز...: ہیب۔ زمینہِ ہندس موٹس منز}\n47.\\tتہٕ سُلیمانن ترٲو سارِنٕے بانہٕ {بے وزن}، تکیازِ تِم ٲسۍ واریاہ زیادٕ، تہٕ نہ اوس پیتلُک وزن لوٚگمُت۔ {کیازِ...: ہیب۔ زیادٕ کثیرٕ خٲطرٕ} {لٔبِتھ: ہیب۔ تلاش}\n48.\\tتہٕ سُلیمانن بنوو تِم سٲری بانہٕ یِم خداوند سٕندِس گرس سٍتـ̡ ٲسۍ: سۄنہٕ سُند قربان گاہ تہٕ سۄنہٕ سُند میز، یتھ پیٹھ شیو بریڈ {اوس}،\n49.\\tخالص سۄنہٕ سٕندِ شمعہٕ، دٔچھنِس طرفہٕ پانژھ تہٕ کھوورِ طرفہٕ پانژھ، اوریکلس برونہہ کُن، پوشہٕ تہٕ شمعہٕ تہٕ سۄنہٕ سٕندِس ٹانگس سٍتۍ،\n50.\\tپیالہٕ، تہٕ نِنہٕ والۍ، تہٕ بیسن، تہٕ چمچ، تہٕ خالص سۄنہٕ سٍتـ̡ تہٕ سۄنہٕ سٕندِس دروازٕ خٲطرٕ، سارِوٕے کھۄتہٕ مقدس {جاے}، تہٕ مکانہٕ کِس دروازٕ خٲطرٕ، {وُچھُن}، مندرٕکِس دروازٕ خٲطرٕ۔ {سنسر: ہیب۔ ایش پینس}\n51. یِتھٕ پٲٹھۍ گٔیہٕ سُہ سورُے کٲم یُس بادشاہ سلیمانن خداوند سٕندِ گرٕ خٲطرٕ کورمُت اوس۔ تہٕ سُلیمانن أنۍ تِم چیٖز یِم أمۍ سٕندِس مٲلہِ داؤدس وقف کٔرۍمٕتۍ۔ {حتیٰ کہ} رۄپہٕ، سۄنہٕ تہٕ بانہٕ، تٔمۍ تھوو خداوند سٕندِس گرٕ کِس خزانس منز۔ {چیز...: ہیب۔ ڈیوڈ سٕنز مقدس چیز}","1. اَمہِ پَتہٕ کٔر سُلیمانن اِسرٲیلِکۍ بزرگ، تہٕ قبیلن ہٕندِس سارِنٕے سردار، یُس بنی اسرٲیلِین ہٕندِس باپَن ہُند سردار، یُس یروشلمَس مَنٛز بادشاہ سلیمانس نِش جمع کٔرِتھ، یُس داؤد سٕندِ شہرٕ منزٕ یُس صیہون چُھ۔ {چیف: ہیب۔ شہزادٕ}\n2. تہٕ سارِوٕے اِسرٲیلٕکۍ مرد گٔیہِ سٔتِم رٮ۪تہٕ کِس عیدس مَنٛز بادشاہ سلیمانس نِش جمع یُس سٔتِم رٮ۪تھ چُھ۔\n3. تہٕ اسرائیلٕکۍ سٲری بزرگ آیہ، تہٕ پادٕرۍ تُل صندوق۔\n4. تہٕ تِمو تُل خداوند سُند صندوق، تہٕ جمٲژ ہُند خیمہ تہٕ تِم سارِنٕے مقدس بانہٕ یِم خیمہ خانس مَنٛز ٲسۍ، تِم تہِ کٔرِکھ پادٕرۍ تہٕ لاوی تہِ۔\n5. تہٕ بادشاہ سُلیمان، تہٕ اسرٲیلٕچ سٲری جماعت یِم أمِس سٍتـ̡ جمع گٔیہِ، تٔمِس سٍتـ̡ صندوقس برونہہ کُن، کۅکرِ تہٕ بیل قربان کٔرِتھ، یِمن ہُند ونُن تہٕ بٔڈِس سٍتـ̡ گٔیہِ۔\n6. تہٕ پادٕرۍ اوٚن خداوند سٕندِ عہد کِس صندوقس منز تٔمۍ سٕنزِ جایہ، گرٕ کِس اوریکلس منز، مقدس ترین مقامس تام، یوتام زِ کروبن ہٕندِس پکھس تل تہِ۔\n7. تکیازِ کروبِمو پھٔہلٲوۍ صندوق کِس جایہِ زٕ پکھہٕ، تہٕ کروبِمو کٔر صندوق تہٕ اَمہ کِس ہیرِ کِس ڈنجہ ؤلِتھ۔\n8.\\tتہٕ تِمو کٔڈِتھ ڈنجہ کٔڈِتھ زِ ڈنجہِ ہٕندِس اندس آیہ مُقدس مقامس مَنٛز وُچھنہٕ، تہٕ تِم آیہ نہٕ نیبر وُچھنہٕ: تہٕ تِم چھِ از تام تتہِ موجود۔ {اختتام: ہیب۔ ہیڈز} {مقدس...: یا، آرک}\n9.\\tصندوقس منز اوس نہٕ کنن ہٕندِس دۅن میزن ورٲے کینہہ تہِ، یُس موسیٰ ہن حوربس مَنٛز تھوومُت اوس، ییلہِ خداوند بنی اسرائیل سٍتـ̡ {اکھ معاہد} کورمُت، ییلہ تِم مصر کہِ سرزمینہٕ منزٕ نیبر آو۔ {ییلہ: یا، کتہِ}\n10. تہٕ سپُد یێلہِ پادٕرۍ مُقدسہٕ منزٕ نٮ۪بر دِنہٕ آمٕتۍ، زِ اوٚبرن بٔرِتھ خداوند سٕندِس گرس بٔرِتھ،\n11.\\tیُتھ زِ پادٕرۍ ہیوٚک نہٕ اوٚبرٕ سٍتـ̡ خدمت کرنہٕ خٲطرٕ کھڑا گژھِتھ: کیازِ خداوند سٕندِ جلال سٍتـ̡ اوس خداوند سٕندِس گرس بٔرِتھ۔\n12.\\tاَمہِ پَتہٕ وۆن سُلیمان، خداوند ووٚن زِ سُہ روزِ گٔنِس انہِ گٹہِ مَنٛز۔\n13. مے چُھس یٔقیٖنی طور ژے روزنہٕ خٲطرٕ اکھ مکانہٕ بنوومُت، یُس ژےٚ ہمیشہٕ روزنہٕ خٲطرٕ اکھ آباد جاے چھُ۔\n14.\\tتہٕ بادشاہن پھیُر پھیُر تہٕ کٔرٕن سارِنٕے اسرٲیلٕچ جماعت برکت: (تہٕ سارِنٕے اسرٲیلٕچ جماعت گٔیہِ کھڑا۔)\n15.\\tتہٕ وۆنُن بابرکت {ہو} خداوند اسرٲیلُک خدا، یُس میٲنِس مٲلِس داؤدس سٍتـ̡ کتھ کٔرِتھ تہٕ پنہٕ نِس اتھہٕ سٍتـ̡ پورٕ کورمُت،\n16.\\tییمہِ دۅہہ میہ پنُن قوم اسرائیل مصرہٕ منزٕ نیبر کڈنہٕ آمُت، میہ چُھہ نہٕ اسرٲیلٕکۍ سارِوٕے قبیلو منزٕ کانہہ تہِ شہر ژارنہٕ یُتھ مکانہٕ بناونہٕ خٲطرٕ، یُتھ میون ناو آسہِ۔ مگر میہ چُھ داؤد پننین لوکن پیٹھ اسرائیلس پیٹھ منتخب کرنہٕ۔\n17. تہٕ یہِ اوس میٲنِس مٲلِس دٲیود سٕندِس دِلس مَنٛز یُس اسرٲیلِکِس خدایہِ سٕندِ ناوٕ خٲطرٕ اکھ مکانہٕ بناوُن۔\n18.\\tتہٕ خداوند ووٚن میٲنس مٲلِس دٲیر، یۆدوَے تۅہہِ دِلس مَنٛز میانہِ ناوٕ خٲطرٕ اکھ مکانہ بناوُن، تہٕ ژے کٔر یہِ تُہندِس دِلس مَنٛز۔\n19.\\tتوتہِ گژھ نہ یہ مکانہ تعمیر کرُن۔ مگر تُہند نیچو یُس تۅہہِ کۅکرِ منزٕ نیرِ، سُہ کرِ میانہِ ناوٕ سٍتـ̡ مکانہٕ بَناوُن۔\n20. تہٕ خداوند چُھس پَنُن کلام پورٕ کوٚرمُت، تہٕ بہٕ چُھس پننِس مٲلِس داؤد سٕندِس کمرس مَنٛز زِندٕ گومُت، تہٕ بِہتھ یِتھ کٔنۍ خداوند سُند وعدٕ کورمُت، تہٕ چُھس اِسرٲیلِکِس خداوند سٕندِ ناوٕ خٲطرٕ اکھ گرٕ بنوومُت۔\n21. تہٕ مے چُھس اَتھ صندوقہٕ خٲطرٕ اکھ جاے مقرر کٔرمٕژ، یُس تٔمۍ سانین آباؤ اجدادن سٍتـ̡ کورمُت اوس، یێلہِ تِم مصر کہِ سرزمینہٕ منزٕ نٮ۪بر کٔرِتھ۔\n22. تہٕ سُلیمان ووت خداوند سٕندِس قربان گاہَس برونہہ کُن اِسرٲیلٕچ سارِنٕے جمٲژ ہٕندِس حٲضِرِس مَنٛز، تہٕ پَنُن اَتھٕ پھٔہلٲوِن اسمانس کُن:\n23. تہٕ ووٚن اے خدا، اے خدا، اسرٲیلُک خدا، {چُھہ} چُھہ نہٕ ژے ہیوٗ کانہہ خدا، یُس تۅہہِ ہٕندِس سارِوٕے دِلہٕ سٍتـ̡ پَکان چُھہ تُہٕندِس بندس سٍتـ̡ عہد تہٕ رحمتہٕ تھاوان چُھ:\n24. یُس پننِس خادمس ڈیوڈس سٍتـ̡ پننِس مٲلس سٍتـ̡ یُس ژے أمس وعدٕ کورمُت چُھ، تہٕ ژے کٔر پننہِ اتھہٕ سٍتـ̡ پورٕ، یِتھ کٔنۍ از تہِ چُھ۔\n25. تێمہِ کِنـ̡ وۆنـ̡ اے خدایہِ اِسرٲیلِیُک خدا، پَنٕنـ̡ خادم داؤد سٍتـ̡ تھاوُن یُس ژے أمِس وعدٕ کورمُت چُھ، یہِ ونُن زِ تێہہ گژھِ نہٕ میانہِ نظرِ منز کانہہ تہِ نفر اسرٲیلِس کِس تختس پیٹھ بِہنہٕ خٲطرٕ۔ یێلہِ تُہٕندِ شُرِ ہُند خیال تھاوُن، یێلہِ تِم پَکَن میانہِ برونہہ کُن یِتھٕ پٲٹھۍ ژے میانہِ برونہہ پکان چھِ۔ {ناکام...: ہیب۔ میانہِ نظرِ نِش ژٔٹِتھ کٔرِتھ یُس انسان۔ صرف تیلہِ}\n26. تہٕ وۅنۍ اے اسرٲیلِکِس خدایہ، تێہُند کلام گژھہِ تصدیق سپدُن، یُس ژے پننِس خادم داؤد میٲنِس مٲلِس سٍتـ̡ کتھ کٔرمٕژ چھُ۔\n27. مگر کیا خدا پزۍ پاٹھۍ زمینس پیٹھ روزِ؟ وچھو، آسمانُک تہٕ آسمانُک آسمانہٕ ہیکہِ نہٕ ژےٚ رٔٹِتھ۔ یہ مکانہ کوتاہ کم یُس میہ بنوومت چھہ؟\n28. توتہِ چُھہ ژے پننِس بندہ سٕنزِ دُعا تہٕ تٔمۍ سٕنزِ دُعا سٍتـ̡ احترام کٔرِتھ، اے خدایہ میانہِ خدا، یُس تُہند خادم از تہِ تۅہہِ برونہہ کُن دُعا کران چُھ، سُہ چُھہ دُعا تہٕ دُعا بوزُن:\n29.\\tیُتھ زن تۅہہِ رٲژ تہٕ دۅہہٕ یَتھ گرس کُن یَتھ جایہِ یُس ژے وَنُن چُھ، میون ناو آسہِ تتہِ یُس تُہند خادم یَتھ جایہِ کُن کرِ۔ {یَتھ جایہِ کُن: یا، یَتھ جایہِ کُن}\n30. تہٕ پَنٕنِس خادمَس تہٕ پَنٕنِس قوم اِسرٲیلٕچ دُعا بوزو، یێلہِ تِم یَتھ جایہِ کُن دُعا کَرٕن، تہٕ بوٗزِو پَنٕنـ̡ روزنٕچ جاے تہٕ یێلہِ تہٕ یێلہِ تہٕ بوٗزِو، تہٕ یێلہِ تہٕ یێلہِ تہٕ بوٗزِو، تہٕ یێلہِ تہٕ یێلہِ تہٕ بوزن، کٔرِو معاف۔ {یَتھ جایہِ کُن: یا، یَتھ جایہِ کُن}\n31.\\tاگر کانہہ شخص پننِس ہمساین خلاف ورزی کرِ، تہٕ أمِس پیٹھ گژھہِ حلف کھاونہٕ یُن، تہٕ یہ حلف گژھہِ تُہندِس قربان گاہَس برونہہ کُن یِنہٕ: {تہٕ اکھ قسم...: ہیب۔ تہٕ أمِس چھُ أمِس سُند حلف ضروُر}\n32. تیلہِ کرو اسمانس منز بوزُن، تہٕ کرو پننین خدمتگارن ہُند فیصلہ تہٕ بدکارن ہٕنز سزا دِنہٕ خٲطرٕ، تٔمۍ سٕندِس کلس پیٹھ تٔمۍ سٕنز وتھ اننہٕ۔ تہٕ صالحن ہُند جواز پیش کرُن، یُس تٔمۍ سٕنزِ نیکی مُطٲبق دِنہٕ خٲطرٕ۔\n33. ییلہِ تُہٕندِس قومس دُشمن سٍتـ̡ دُشمن سٍتـ̡ مارنہٕ ییہِ، تِکیازِ تِمو چُھہ تۅہہِ سٍتـ̡ گۅناہ کورمُت، تہٕ یێلہِ دُبارٕ توے کُن پھیرِن، تہٕ تُہُند ناو ہُند اقرار کرُن، تہٕ دُعا کٔرِن تہٕ یێمہِ گرس مَنٛز دُعا کرنہٕ۔\n34. تێمہِ پٲٹھـ̡ کٔرِو اسمانس مَنٛز بوزو، تہٕ پَنٕنـ̡ قوم اسرٲیلـ̡ ہُند گۅناہ معاف، تہٕ تِمن أنِو تِمن زمینس مَنٛز یُس تِمن ہٕندِس مٲلِس سٍتـ̡ دِژمُت چُھ۔\n35. ییلہِ اسمانس بند آسہِ، تہٕ روٗد آسہِ نہٕ، کیازِ تِمو چُھ تۅہہِ سٍتـ̡ گۅناہ کورمُت۔ یێلہِ تِم یَتھ جایہِ کُن دُعا کَرن، تہٕ تُہُند ناو اقرار کَرن، تہٕ پنہٕ نِس گۅنہٕ نِش پھیرِن، ییلہ تہٕ تِمن مُتٲثِر کٔرِو:\n36. تێمہِ پٲٹھـ̡ کٔرِو اسمانس مَنٛز بوزو، تہٕ پننین خادمَن تہٕ پننین قومہٕ اسرٲیلـ̡ ہٕندِس گۅناہ سٍتـ̡ معاف، یێلہِ تێلہِ تێلہِ پَکُن، تہٕ پَنٕنـ̡ پَنٕنـ̡ پۯاوٕنـ̡ ۔\n37.\\tاگر زمینس منز قحط آسہِ، اگر وبا، دھماکہ، پھپھ، ٹِڈی، {یا} اگر کیٹرپلر آسہِ۔ اگر تِہُند دُشمن تِمن ہٕندِس شہرن ہٕندِس سرزمینس منز محاصرٕ کرِ۔ یُس تہِ طاعون آسہِ، کُنہِ تہِ بیمارِ آسہِ؛ {شہر: یا، دائرہ اختیار}\n38.\\tکُنہِ تہِ انسانس سٍتـ̡ کُنہِ تہِ انسانس سٍتـ̡ دُعا تہٕ دُعا کرُن، یُس پرٮ۪تھ أکِس انسانس پنہٕ نِس دِلُک عذاب زانہِ تہٕ یێمہِ گرس کُن پَنُن اتھہٕ پھٔہلاونہٕ ییہِ:\n39. تیلہِ بوزو اسمانس منز پنُن روزن جاے تہٕ معٲفی کرُن، تہٕ کرُن تہٕ دِیُن پرٮ۪تھ أکِس انسانس تٔمۍ سٕندِ طٔریٖقہٕ مُطٲبق، یٔمۍ سُند دِل توے زانان چھُ۔ (تکیازِ توہ، {حتیٰ کہ} تہِ چُھہ صرف انسان سٕندِس سارِنٕے اولادَن ہٕندِس دِلس زانان؛)\n40.\\tیُتھ تِم ژےٚ سارِنٕے دۅہہٕ تِمن ہٕندِس زمینس مَنٛز روزان یُس ژے سانٮ۪ن مٲلن دِژمُت چھُ۔\n41.\\tیُس أکِس اجنبی شخصس متعلق، یُس نہٕ تُہنزِ قومہٕ سٍتـ̡ اسرٲیلـ̡ سٍتـ̡ چُھہ بێیہِ سٍتـ̡ دوٗر دوٗر مُلکہٕ سٍتـ̡ دِنہٕ آمُت۔\n42.\\t(تِم بوزِ تُہُند بٔڈ ناو، تہٕ تُہٕندِس مضبوٗط اتھس تہٕ تُہٕندِس پھٔہلِتھ نٔرِس مُتلِق بوزن؛) یێلہِ سُہ یِتھ گرس کُن دُعا کرِ۔\n43. اسمانس مَنٛز بوزو پنٕنـ̡ روزنٕچ جاے تہٕ یێلہِ سٍتـ̡ پرٲنِس سٍتـ̡ چُھہ تُہُند ناو زانن، یێلہِ پٲٹھـ̡ تُہٕندِس قوم اسرٲیلس سٍتـ̡ تہٕ تُہٕندِس سٍتـ̡ کرٕنـ̡ ۔ تہٕ یُتھ زن تِم زانن زِ یہِ مکانہٕ، یُس میہ بنوومُت چھُ، چھُ تُہند ناو وننہٕ یوان۔ {یہ...: ہیب۔ تُہند ناو چُھ یتھ گرس پیٹھ وننہٕ یوان}\n44.\\tیێلہِ تُہٕندِس دُشمن سٍتـ̡ جنگہٕ کرنہٕ خٲطرٕ نیرِ، یێلہِ تہٕ یێلہِ تہٕ یێلہِ تہِ ژے ژٲرِمُت چُھ، تہٕ تُہٕندِس ناوٕ خٲطرٕ بنوومُت مکانہٕ کُن دُعا کٔرِو۔ شہرٕچ وَتھ}\n45. تیلہِ کرو اسمانس منز تہنز دعا تہٕ دُعا تہٕ تِہٕنزِ دُعا تہٕ تِہٕندِس مقصدس برقرار تھاوُن۔ {وجہ: یا، صحیح}\n46. اگر تِم تۅہہِ سٍتـ̡ گۅناہ کٔرِتھ، تہٕ تِمن سٍتـ̡ ناراض گژھِو، تہٕ تِم دُشمن نِش واتناوُن، یێلہِ تِم دُشمن سٕندِس سرزمینس کُن نِن، دوٗر یا نزدیک۔\n47.\\t{توتہِ} اگر تِم یِمن زمینس مَنٛز یێلہِ یِم قٲد کٔرۍمٕتۍ، تہٕ توبہ کٔرِن تہٕ تِمن ہٕندِس سرزمینس مَنٛز دُعا کٔرِن یِم تِم قٲد کٔرۍمٕتۍ، تہٕ وَنُن زِ أسـ̡ چُھ گۅناہ کورمُت تہٕ غلط کٔرِمٕتـ̡ أسـ̡ بدکار کورمُت۔ {be-think...: Heb. تِہنٛدِس دِلس منٛز واپس انِو}\n48.\\tتہٕ یِمن ہٕندِس دِلہٕ سٍتـ̡ تہٕ سٲرۍسٕے روحہٕ سٍتـ̡ یُس تِمن ہٕندِس دُشمنن ہٕندِس سرزمینس مَنٛز واپس، یُس تِمن ہٕندِس مٲلِس سٍتـ̡ دِژمُت چُھ، سُہ شہر یُس ژے ژٲرمُت چُھ، تہٕ سُہ مکانہٕ یُس مے تُہندِ ناوٕ خٲطرٕ بنوومُت چُھ، تہٕ تِمن ہٕندِس سرزمینس کُن دُعا کٔرِتھ دُعا کٔرِتھ، یُس ژے تِہندِ ناوٕ خٲطرٕ بنوومُت چُھ:\n49. تیلہِ کرو تِہٕنزِ دُعا تہٕ تِہٕنزِ دُعا تہٕ تِہٕنزِ دُعا بوزِو، تہٕ تِہٕندِس مقصدس کٔرِو، {وجہ: یا، صحیح}\n50. تہٕ پَنٕنـ̡ لُکھ یِمو تۅہہِ سٍتـ̡ گناہ کٔرِمٕژ چِھ، تہٕ تِمن ہٕندِس سٍتـ̡ رحم کٔرِو یِمن سٍتـ̡ یِمن سٍتـ̡ تِمن سٍتـ̡ رحم کٔرِ۔\n51. تِم چِھہ تُہٕندِس لُکہٕ سٍتـ̡ تہٕ تُہُند وَراثت، یُس ژے مصرہٕ منزٕ شِشتٕرِ ہٕندِس بھٹہٕ منزٕ نِنہٕ آمُت چُھ:\n52.\\tیُتھ تُہٕنزِ أچھ گژھہِ پننِس خادمس سٕنزِ دُعا تہٕ پننہِ قوم اسرٲیلٕچ دُعا خٲطرٕ یلہٕ روزٕن، تہٕ تِمن ہٕندِس سارِنٕے سٍتـ̡ بوزنہٕ یِنہٕ خٲطرٕ۔\n53.\\tکیازِ ژے کٔر تِم زمینہٕ کین سارِنٕے لُکن منزٕ الگ کرنہٕ، یِتھ کٔنۍ ژے پنُن خادم موسیٰ سٕندِ اتھہٕ سٍتـ̡ کتھ کٔرِتھ، یێلہِ ژے سانین آباؤ اجداد مصرہٕ منزٕ نِش أنِتھ ، اے خداوند خدا۔\n54. تہٕ یہِ اوس {یێلہِ} یێلہِ سُلیمانن خداوند سٕندِ خٲطرٕ یِہ سورے دُعا تہٕ دُعا دُعا ختم کٔرِتھ، سُہ ووت خداوند سٕندِس قربان گاہٕ برونہہ کُنـ̡ کۅٹھن پیٹھ بٔنِتھ اسمانس کُن اتھہٕ پھٔہلٲوِتھ کُٹھـ̡ بٔنِتھ ۔\n55. تہٕ سُہ ووٚتھ تہٕ سارِنٕے اِسرٲیلِچ جماعت بَڑِ آوازٕ سٍتـ̡ برکت دِتھ وونُن،\n56.\\tخداوند مبارک ہو، یمۍ پننین لوکن اسرٲیلِس آرام دِژ، یُس تٔمۍ سٕندِس خادم موسیٰ سٕندِ اتھہٕ سٍتـ̡ وعدٕ کورمُت اوس۔ {ناکام: ہیب۔ فالن}\n57. خداوند سُند خدا گژھہِ اسہِ سٍتـ̡ یِتھٕ پٲٹھـ̡ سُہ سانین مٲلن سٍتـ̡ اوس، سُہ گژھہِ نہٕ اسہِ سٍتـ̡ تراوُن، تہٕ اسہِ تراوُن نہٕ:\n58.\\tیُتھ سُہ کرِ سانہِ دِل پانس کُن رُکاونہٕ، پَنٕنـ̡ سارِنٕے وَتہٕ پَنٕنـ̡ پَنٕنـ̡ حُکُم، تہٕ پَنٕنـ̡ حکمن تہٕ پَنٕنـ̡ فٲصلن ہُند عمل کرُن، یِمن سٍتـ̡ تٔمۍ سٍتـ̡ سٍتـ�\n59. تہٕ یِم میٲنۍ کلام، یێمہِ سٍتـ̡ میہ خداوند سٕندِ برونہہ کُن دُعا کٔرمٕژ چِھ، یێلہِ سُہ پنہٕ نِس بندس تہٕ تٔمۍ سٕندِس قوم اسرٲیلـ̡ سٕندِس کامہِ سٍتـ̡ پرٮ۪تھ ساتہٕ رٲچھ کٔرِتھ، یێلہِ سٍتـ̡ پى۪ٹھ تمۍ سندِ دۅہک چیز}\n60.\\tیُتھ زِ زمینہِ ہٕندِس سارِنٕے لُکن گژھہِ پتاہ زِ خداوند چُھ خدا، {تہٕ یہِ زِ بییہِ چُھہ نہٕ کانہہ تہِ﴾۔\n61. تێمہِ کِنۍ گژھہِ پنُن دِل سٲنِس خداہس سٍتـ̡ کامل روزُن، تہٕ تٔمۍ سٕندِس حکمس مُطٲبِق روزُن تہٕ یێلہِ دۅہہ پٲٹھـ̡ تٔمۍ سٕندِس حکمس پیٹھ عمل کرُن۔\n62. تہٕ بادشاہ تہٕ أمِس سٍتـ̡ سارِنٕے اسرٲیلَن کٔر خداوند سٕندِ برونہہ کُن قربانی۔\n63.\\tتہٕ سُلیمانن کٔر امن ہٕنز قربانی پیش یُس تٔمۍ خداوند سٕندِ خٲطرٕ پیش کٔر، زٕ وُہ ساس بیل تہٕ اکھ لچھ کۅکر۔ چنانچہ بادشاہ تہٕ بنی اسرائیل کٔر خداوند سُند گرٕ وقف۔\n64.\\tامی دۅہہ کٔر بادشاہن دربارس منز یُس خداوند سٕندِس گرس برونہہ کُن اوس، تکیازِ تتہِ کٔر تٔمۍ دزنہٕ نذرانہٕ تہٕ مازٕچ نذرانہ تہٕ امن ہٕنز چربی پیش کرنہٕ: کیازِ یُس زٲلِتھ قربان گاہ یُس خداوند سٕندِ برونہہ کُن اوس، سُہ اوس سٮ۪ٹھاہ کم زٲلِتھ تہٕ مازٕچ نذرانہ رٔٹِتھ ،  تہٕ امنٕچ پیشکشَن ہُند چربی۔\n65.\\tتہٕ اَمہِ وِزِ کٔر سُلیمانن اَکھ دعوت تہٕ سارِنٕے اسرٲیلِس سٍتـ̡ ہمت کِس دٔریاوَس تام، خداوند سانہِ خدایہ سٕندِس برونہہ کُن سَتھ دۅہہ، سَتھ دۅہہ، ژۄداہ دۅہ۔\n66.\\tٲٹھمہِ دۅہہ سوٗزۍ تٔمۍ لُکھ تہٕ تِمو کٔر بادشاہس دُعا دُعا تہٕ گٔیہِ پننین خیمن منز خۅش تہٕ خۄش گٔژھِتھ یُس خداوند پننِس خادم داؤد سٕندِ خٲطرٕ تہٕ اسرٲیلِس خٲطرٕ کٔرمٕژ ٲس۔ {بابرکت : یا، شکریہ}","1. تہٕ سپُد سُلیمانن خداوند سٕندِس گرٕچ تعمیر تہٕ بادشاہ سٕندِس گرٕچ تعمیر مُکمل کٔرِتھ، تہٕ سُلیمان سٕنز سورُے خٲہش یُس سُہ خۅش گٔیہِ،\n2. زِ خداوند آو دوٚیمہِ لٹہِ سلیمانس نِش ظٲہر، یِتھہٕ پٲٹھۍ سُہ گبیونس مَنٛز أمِس نِش ظٲہر اوس گومُت۔\n3. تہٕ خداوند ووٚن أمِس زِ مے چُھہ تُہٕنز دُعا تہٕ تُہٕنز دُعا بوزمٕژ، یُس ژے میانہِ برونہہ کُن کورمُت چُھ، مے چُھس یہِ مکانہٕ مقدس کورمُت، یُس ژے بنوومُت چُھ، یُس پنُن ناو ہمیشہٕ خٲطرٕ تھاوُن۔ تہٕ میٲنۍ أچھ تہٕ میون دِل روزِ ہمیشہٕ خٲطرٕ۔\n4. تہٕ یێلہِ ژٕ میانہِ برونہہ کُن، یِتھٕ پٲٹھـ̡ تُہند مٲل دِلہٕ سٍتـ̡ پٔکِتھ، دِلہٕ سٍتـ̡ تہٕ سیدِ سٍتـ̡ یُس میہ چُھہ حُکُم دِژمُت چُھ، تِمن سٍتـ̡ کٔرِو میٲنۍ قونونن تہٕ فیصلن ہٕنز پاسداری:\n5. تیلہِ کٔرٕ بہٕ چانہِ سلطنتُک تخت اسرٲیلِس پیٹھ ہمیشہٕ خٲطرٕ قٲیم، یِتھ کٔنۍ مے پننِس مٲلِس داؤدس وعدٕ کوٚرمُت اوس، تہٕ وونُن زِ اسرٲیلِس کِس تختس پیٹھ گژھِ نہٕ کانہہ نفر تہِ ناکام۔\n6. {مگر} یێلہِ تہٕ تُہۍ یا تُہٕندِس شُرِس میانہِ پٲروی نِش پھیرِو، تہٕ میٲنۍ حُکمن تہٕ میٲنۍ قونونن یُس مے ژے برونہہ کُن مقرر کرمُت چُھ، بلکہ گژھِو تہٕ باقین دیوتاہن ہٕنز عبادت کٔرِو، تہٕ تِمن ہٕنز عبادت کٔرِو:\n7. تیلہِ کٔرٕ بہٕ اسرٲیلِس سٍتـ̡ یُس میہ تِمن دِژمُت چُھ، سُہ ژٔٹِتھ ژٔٹِتھ ۔ تہٕ یہ گرٕ یُس میہ پننہ ناوٕ خٲطرٕ مقدس کورمُت چھُ، بہٕ کٔرٕ پننہ نظرِ نِش کڈنہٕ۔ تہٕ اسرٲیل آسہِ سارِنٕے لُکن مَنٛز اکھ محاورہ تہٕ ضمنی لفظ:\n8. تہٕ یَتھ گرس منز، یُس تھوٚد چُھ، یُس اَتھ کُن نیران چُھ، سُہ گژھہِ حٲران تہٕ ہُرٕ دِنہٕ۔ تہٕ تِم ونن زِ خداوند کیازِ چُھ یتھ زمینس تہٕ یتھ گرس سٍتـ̡ یِتھٕ پٲٹھۍ کورمُت؟\n9. تہٕ تِم دِن جواب، کیازِ تِمو ترووُن خداوند پنُن خدا، یُس پننین آباؤ اجداد مصر کہِ سرزمینہٕ منزٕ نیبر کڈِ، تہٕ باقین دیوتاہن رٔٹمُت تہٕ تِمن ہٕنز عبادت کٔرمٕژ تہٕ تِہنز خدمت کٔرمٕژ۔\n10.\\tتہٕ سپُد وُہن ؤرین ہٕندِس ٲخرس پیٹھ، ییلہ سُلیمانن زٕ گرٕ تعمیر کٔرۍ، خداوند سُند گرٕ تہٕ بادشاہ سُند گر،\n11.\\t({ونہِ} صور کِس بادشاہ ہیرمن اوس سُلیمانس دیودار کُلۍ تہٕ فر کُلۍ تہٕ سۄنہٕ سٍتـ̡ دِژمٕتۍ، یێمہِ وِزِ بادشاہ سلیمانن دِژ حیرامس گلیل کِس سرزمینس مَنٛز وُہ شہر۔\n12.\\tتہٕ ہیرم دراو صور پیٹھٕ تِم شہر وچھنہٕ خٲطرٕ یِم سُلیمانن أمِس دِژمٕتۍ ٲسۍ۔ تہٕ تِمو کٔر نہٕ أمِس خۄش۔ {خۄش...: حب۔ امۍ سنزن نظرن منز ٲسۍ نہ صحیح}\n13.\\tتہٕ ووٚن یِم کُس شہر چھِ یِم ژے مے دِژمٕتۍ چھِ، میانہِ بٲے؟ تہٕ تٔمۍ وَنُن تِمن از تام کابُلُک سرزمین۔ {کابل: یعنی ناپسندیدہ، یا گند}\n14.\\tتہٕ ہیرامَن سوٗزۍ بادشاہس سۄنہٕ سٕندِ شےٚ ٹیلنٹ۔\n15.\\tتہٕ یہِ چُھ سُہ وجہ یُس بادشاہ سلیمانن تُلمت اوس۔ خداوند سُند گر، تہٕ تٔمۍ سُند گر، تہٕ میلو، تہٕ یروشلمچ دیوار، تہٕ حزور، تہٕ میگیڈو تہٕ گیزر تعمیر کرنہٕ خٲطرٕ۔\n16.\\tمصرُک بادشاہ فرعون اوس ہیوٚر تہٕ گیزر نِتھ نارٕ سٍتـ̡ زٲلِتھ تہٕ شہرس مَنٛز روزن وٲلِس کنعانی مٲرِتھ تہٕ دِتُن پننہِ کورِ سُلیمان سٕنزِ زنانہِ خٲطرٕ اکھ تحفہٕ۔\n17. تہٕ سلیمانن بنوو گیزر تہٕ بیتھورون بنوُن،\n18. تہٕ بعلت، تہٕ تدمور بیابانس منز، زمینس منز،\n19. تہٕ سُلیمانن نِش سارِنٕے شہر یِم سُلیمانن نِش ٲسۍ، تہٕ سُہ شہر یُس سُلیمانن یُس یروشلمَس مَنٛز تہٕ لبنانس مَنٛز تہٕ پَنٕنِس سارِنٕے سرزمینس مَنٛز تعمیر کرُن یژھان۔ {یہٕ کُس...: ہیب۔ سلیمان سٕنز خواہش یۄس سُہ یژھان اوس}\n20. {تہٕ} سٲری لُکھ {یِم امورِن، حِتی، پریزِی، حِوی تہٕ یبوسی نِش باقٕے ٲسۍ﴾، یِم نہٕ بنی اِسرٲیلِس سٍتـ̡ ٲسۍ،\n21.\\tتِہندِ شُرۍ یِم تِمن پَتہٕ زمینس مَنٛز ترٲومٕتۍ، یِمن ہٕندِس بُلِس تہِ ہیوٚک نہٕ پوٗرٕ پٲٹھۍتباہ کٔرِتھ، تِمن پیٹھ کٔر سُلیمانن از تام غلامی ہُند خراج دِنہٕ۔\n22.\\tمگر بنی اسرٲیلِس منز بنوو نہٕ سُلیمانن کانہہ تہِ غلام مگر تِم ٲسۍ جنگی شخص، تہٕ تٔمۍ سٕندِ خادم، تہٕ تٔمۍ سٕندِ شہزادہٕ، تہٕ تٔمۍ سٕندِس رتھَن ہٕندِ حکمران تہٕ تٔمۍ سٕندِس گُرِ سوارِ۔\n23.\\tیِم ٲسۍ سُلیمان سٕنزِ کامہِ پیٹھ پانژھ ہتھ پنژاہ افسرن ہٕندِس سردارس سٍتـ̡ یِم اتھ کامہِ منز کٲم کران ٲسۍ۔\n24.\\tمگر فرعون سنز کورِ دراو داؤد شہرہ منزہ پننِس مکانس منز یُس سُلیمانن أمس خٲطرٕ بنوومُت اوس، تمہ پتہ بنوو تمٔۍ ملو ۔\n25. تہٕ أکِس ؤریس منز تریہ لٹہِ کٔر سُلیمانن تتھ قربان گاہس پیٹھ زالنہٕ تہٕ امن ہٕنز قربانی پیش یُس تٔمۍ خداوند سٕندِ خٲطرٕ تعمیر کورمُت اوس، تہٕ تٔمۍ زٲلِن قربان گاہس پیٹھ بخور یُس خداوند سٕندِ برونہہ کُن اوس۔ چنانچہ کوٚر تمۍ مکانہ ختم۔ {قربان گاہس پیٹھ یہ: ہیب۔ اتھ پیٹھ، وغیرہ}\n26. تہٕ بادشاہ سُلیمانن بنوو ایزیونگبرس مَنٛز بحری جہازن ہُند اکھ بحری جہاز، یُس ایلوتھس نِش بحر احمر کِس بٹھس پیٹھ، ادوم کِس سرزمینس مَنٛز۔ {ساحل: ہیب۔ لپ}\n27.\\tتہٕ ہیرامن سوٗزۍ سُلیمان سٕندٮ۪ن خدمتگارن سٍتـ̡ پنٕنـ̡ خدمتگار سٍتـ̡ سمندرٕچ زان تھاون وٲلِس سٍتـ̡\n28.\\tتہٕ تِم آیہِ اوفیرس نِش، تہٕ اَتہِ نِش أنِکھ سۄنہٕ ژور ہتھ وُہ ٹیلنٹ، تہٕ أنِکھ بادشاہ سلیمانس نِش۔","1. تہٕ ییلہ شیبا ہٕچ ملکہ خداوند سٕندِس ناوس متعلق سُلیمان سٕنز شہرت بوز، سُہ آیہِ سُہ سخٕت سوالو سٍتـ̡ ثٲبت کرنہٕ خٲطرٕ۔\n2. تہٕ سۄ آیہِ أکِس واریاہ بٔڈِ ٹرینہِ ہیتھ یروشلمس منز، یتھ منز اونٹ تہٕ سٮ۪ٹھاہ سۄنہٕ تہٕ قیمتی پتھرٕ ٲسۍ، تہٕ ییلہ سُہ سلیمانس نِش آیہ، تٔمۍ کٔر أمِس سٍتـ̡ سارِنٕے چیزن ہٕنز کتھ باتھ۔\n3. تہٕ سُلیمانن ووٚن أمِس پنٕنۍ سٲری سوال: بادشاہس نِش اوس نہٕ کانٛہہ تہِ چیز ژوٗرِ تھوومُت، یُس نہٕ تٔمِس ووٚنمُت۔ {سوال: حب۔ لفظ}\n4. تہٕ ییلہ سِباہٕچ ملکہٕ سُلیمان سٕنز سورے حکمت وُچھمٕژ، تہٕ یُس مکانہٕ تٔمۍ بنوومُت اوس،\n5. تہٕ تٔمۍ سٕندِس دسترُک ماز، تہٕ تٔمۍ سٕندٮ۪ن خدمتگارن ہٕنز بِہنہٕ، تہٕ تٔمۍ سٕندِس وزیرن ہٕنز حاضری، تہٕ تٔمۍ سٕندِس پیالہ بردارن ہٕنز حاضری، تہٕ تٔمۍ سٕندِس کھسنہٕ سٍتـ̡ سُہ خداوند سٕندِس گرس تام کھسُن۔ تس منز اوس نہ بییہ کانہہ جذبہ۔ {حاضری: ہیب۔ کھڑا} {کپ بیئررز: یا، بٹلرز}\n6.\\tتہٕ تٔمۍ ووٚن بادشاہس زِ یہ ٲس اکھ پوٚز خبر یُس میہ پننِس زمینس منز چانہِ اعمال تہٕ چانہِ حکمتٕچ خبر بوزمٕژ۔ {رپورٹ: ہیب۔ لفظ} {اعمال: یا، اقوال}\n7.\\tبہٕ بہٕ اوسُس نہٕ یِمن لفظن پیٹھ یقین کٔرِتھ، یوٚت تام بہٕ آو، تہٕ میانہِ أچھن ٲس وُچھمٕژ: تہٕ وُچھ، نصف اوس نہٕ مے وَننہٕ آمُت: چانۍ حکمت تہٕ خوشحالی چھے تمہ شہرت کھوتہٕ زیادٕ یُس مے بوزمُت اوس۔ {thy...: Heb. ژے چھے حکمت تہٕ نیکی شٲمل کٔرمٕژ}\n8.\\tچانہِ مرد چھہِ خوش روزان، خوش باش چھہِ تۅہہِ برونہہ کنہِ کھڑا روزان، {تہِ} یُس تہنز حکمت بوزان چھہِ۔\n9. خداوند چُھہ تُہند خدا، یُس ژے سٍتـ̡ خوش گوو، یُس ژے اسرٲیلِکِس تختس پیٹھ بِہاونہٕ خٲطرٕ خوش گوو، کیازِکہِ خداوند اوس اسرٲیلِس ہمیشہٕ خٲطرٕ محبت کران، تێمہِ مۄکھٕ بنووُن ژے بادشاہ، فیصلہ تہٕ انصاف کرنہٕ خٲطرٕ۔\n10. تہٕ تٔمۍ دِژ بادشاہس اکھ ہتھ وُہ ٹیلنٹ سۄن، تہٕ مسالہٕ واریاہ بٔڈ ذخیرٕ، تہٕ قیمتی پتھر، تِمن ہٕنز کثرت ٲس نہٕ یِم شیبا ہٕچ ملکہٕ بادشاہ سلیمانس دِژمٕژ۔\n11.\\tتہٕ حیرامٕچ بحری فوج تہِ، یُس اوفیرس نِش سون أنِتھ، اوفیرس نِش أنِن واریاہ کُلۍ تہٕ قیمتی پتھر۔ {المگ...: یتھ الگم ٹری تہِ ونان چھِ}\n12.\\tتہٕ بادشاہن بنوو المگ کُلِیو سٍتـ̡ خداوند سٕندِ گرٕ خٲطرٕ تہٕ بادشاہ سٕندِ گرٕ خٲطرٕ، ہارپ تہٕ گیون والٮ۪ن ہٕندِ خٲطرٕ تہٕ زبور تہِ: یِتھۍ کُلۍ آیہ نہٕ از تام وُچھنہٕ۔ {ستون: یا، ریلز: ہیب۔ اکھ پروپ}\n13.\\tتہٕ بادشاہ سُلیمانن دِژ شیبا ہٕنزِ ملکہِ سٲرۍسٕے خٲہش، یُس سُلیمانن أمِس شٲہی عنایت دِژمُت اوس۔ چنانچہ سۅ گٔیہِ پننِس ملکس کُن، سۅ تہٕ تٔمۍ سٕندۍ نوکر۔ {تٔمۍ سٕندِ...: ہیب۔ بادشاہ سلیمان سٕندِ اتھہٕ مطٲبق}\n14.\\tسُہ وزن یُس أکِس ؤریس منز سلیمانس نِش آو سُہ اوس شیہ ہتھ ترے تہٕ شیہ ٹیلنٹ سۄنہٕ،\n15.\\tامہ علاوٕ اوس تٔمِس سوداگرن تہٕ مسالہٕ سوداگرن تہٕ عربہٕ کین سارنٕے بادشاہن تہٕ ملکٕکۍ گورنرن ہٕنزِ تجارت۔ {گورنرز: یا، کیپٹن}\n16.\\tتہٕ بادشاہ سُلیمانن بنوو زٕ ہتھ نشانہٕ: شیہ ہتھ {شیکل} سون گۆو أکِس نشانس پیٹھ۔\n17.\\tتہٕ {تٔمۍ بَنو} ترے ہتھ ڈھالہٕ {of} مارنہٕ آمُت سۄنہٕ۔ ترے پاؤنڈ سون گۆو أکِس ڈھالس منز، تہٕ بادشاہن تھوو تم لبنان کِس جنگل کِس گرس منز۔\n18.\\tامہِ علاوٕ بنوو بادشاہن ہٕندِ دندن ہُند اکھ بوٚڈ تخت، تہٕ اتھ پیٹھ تھووُن بہتٔریٖن سۄنہٕ۔\n19.\\tتختس ٲس شیہ ہیر تہ تختُک پیٹھم اوس پتھ کُن گول تہ تخت کِس جایہ ٲسۍ دۅشوے طرفہ تہ زٕ شیر ٲسۍ بسترس اندۍ پکھۍ کھڑۍ۔ {پَتہٕ: ہیب۔ امہ کس پتمہ حصس پیٹھ} {روزان: ہیب۔ اتھہٕ}\n20. تہٕ اَکہِ طرفہٕ تہٕ دوٚیمہِ طرفہٕ شیٚن ہیرن پیٹھ باہ شیر کھڑا ٲسۍ: کُنہِ تہِ سلطنتس منٛز اوس نہٕ یِتھُے بناونہٕ آمُت۔ {پٲٹھۍ: ہیب۔ تو}\n21.\\tتہٕ بادشاہ سُلیمان سٕندِ سارِنٕے بانہٕ سٍتـ̡ سۄنہٕ سٍتـ̡ تہٕ لبنان کِس جنگلٕکِس گرٕکِس سارِنٕے بانہٕ ٲسۍ خالص سۄنہٕ سٍتـ̡ ۔ کانہہ تہِ اوس نہٕ رۄپہٕ: سلیمان سٕندِس زمانس منز اوس نہٕ اتھ کانہہ تہِ حساب۔ {کانہہ تہِ...: یا، تمن منز اوس نہ کانہہ رۄپہٕ}\n22.\\tکیازِ بادشاہس اوس سمندرس منز ہیرم سٕندِس بحرس سٍتۍ تھرشیش سُند بحری بحری جہاز: تریہ ؤرین منز اکہِ لٹہِ آو تھارشُک بحری بحرہ، یُس سۄن، رۄپھ، دند، تہٕ بندر تہٕ مور أنِتھ۔ {ہاتھی دندن: یا، ۂستین ہٕندِ دند}\n23.\\tیێلہِ کٔر بادشاہ سُلیمان دولتس تہٕ دانٲیی خٲطرٕ زمینہٕ کین سارِنٕے بادشاہن سٍتـ̡ پتھ ۔\n24. تہٕ سارِنٕے زمینہٕ کٔر سُلیمانس سٍتـ̡ تسٕنزِ حکمت بوزنہٕ خٲطرٕ، یُس خداین پننِس دِلس مَنٛز تھوومُت اوس۔ {یژھنہٕ آمُت: ہیب۔ بُتھ ژھانڈُن}\n25.\\tتہٕ تِمو أنۍ پرٮ۪تھ أکِس شخصس تٔمۍ سُند تحفہٕ، رۄپہٕ ہٕندۍ بانہٕ، تہٕ سۄنہٕ ہٕندۍ بانہٕ، پلو، تہٕ ہتھیار تہٕ مسالہٕ، گُرِ تہٕ خچر، ؤری پتہٕ ؤری۔\n26. تہٕ سُلیمانن کٔر رتھٕ تہٕ گُرۍ سوارِ جمع تہٕ أمِس ٲسۍ اکھ ساس ژور ہتھ رتھ تہٕ باہ ساس گُرۍ سوار، یِم تٔمۍ شہرن منز رتھن خٲطرٕ تہٕ بادشاہس سٍتۍ یروشلمس منز دِژٕ۔\n27.\\tتہٕ بادشاہن بنوو یروشلمس مَنٛز رۄپہٕ پٲٹھۍ، تہٕ دیودار بنوو سُہ {آسُن} کُلۍ یُس وادی مَنٛز {چُھ}، کثرت خٲطرٕ۔ {بنیومُت: ہیب۔ دِنہٕ آمُت}\n28.\\tتہٕ سُلیمانن أنِن مصرہٕ منزٕ گُرِ تہٕ کُن یار: بادشاہ سٕندِس سوداگرن دِژ کُنہِ قٕمتس پیٹھ کُن یار۔ {تہٕ سلیمان...: ہیب۔ تہٕ گُرٮ۪ن ہُند نیرُن یُس سُلیمان سُند اوس}\n29.\\tتہٕ اکھ رتھ آو تہٕ مصرہٕ منزٕ دراو شیہ ہتھ رۄپہٕ تہٕ اکھ گُرِ ہتھ ہتھ ہٕندِس خٲطرٕ، تہٕ یِتھے پٲٹھۍ ہِتٮ۪ن ہٕندٮ۪ن سارِنٕے بادشاہن تہٕ شام کین بادشاہن ہٕندِ خٲطرٕ کٔر تِمو پننہ ذٔریعہٕ نیبر۔ {بذریعہ تِہُند...: ہیب۔ تہندِ اتھہٕ سٍتۍ}","1. مگر بادشاہ سُلیمان اوس واریاہن عجیب زنانن سٍتـ̡ محبت کران، یێلہِ فرعون سٕنزِ کورِ، موآبین ہٕنز، عمونی، ادومی، زیدونین تہٕ حِتِین سٍتـ̡ زنانہٕ سٍتـ̡ سٍتـ̡ محبت کٔرِتھ۔ {یکوٹے...: یا، امہ علاوٕ}\n2. یِمن قومن متعلق، یِمن مُتلق خداوند بنی اسرٲیلِس ووٚنمُت، تُہۍ گژھِو نہٕ تِمن نِش اژُن، تہٕ تِم گژھن تُہٕندِس نِش اژُن: {تِکیازِ} یِمن ہُند دِل پھیُرِن پَنٕنـ̡ پۯاوُن: سُلیمانن کٔرِو یِمن سٍتـ̡ محبتس سٍتـ̡ یِمن سٍتـ̡ دِل دِنہٕ۔\n3. تہٕ أمِس آسہٕ سَتھ ہتھ زنانہٕ، شہزادِ تہٕ ترے ہتھ لونڈی: تہٕ تٔمۍ سٕنزِ زنانہٕ پھیرۍ أمۍ سُند دِل۔\n4. یێلہِ سُلیمان بُزرگ اوس تہٕ تٔمۍ سُند دِل اوس نہٕ خداوند سٕندِس خداہس سٍتـ̡ کامل گومُت، یِتھٕ پٲٹھۍ اوس تٔمۍ سُند دِل دِنہٕ آمُت۔\n5.\\tکیازِ سلیمان گۆو زیدونین ہنز دیوی اشتوریتھ تہ ملکومس پتہٕ اوس امونین ہنز مکروہ پٲٹھۍ۔ {ملکوم: تہٕ چُھ ونان، مولیچ}\n6.\\tتہٕ سُلیمانن کٔر خداوند سٕندِس نظرس منز بُر، تہٕ ہیوٚت نہٕ پورٕ پٲٹھـ̡ خداوند سٕندِس پَتہٕ پٲٹھۍ، یِتھٕ پٲٹھـ̡ تٔمۍ سٕندِس مٲلِس داؤد سٕندِ پٲٹھۍ۔ {گٔیہ...: ہیب۔ امہ پتہ چھہ نہ پورہ سپدان}\n7. پتہٕ کٔر سُلیمانن یروشلمس برونہہ کُن پہاڑس مَنٛز موآب سٕندِ مکروہ کموش سٕندِ خٲطرٕ اکھ تھدِ جاے تہٕ مولیخ سٕندِ خٲطرٕ یُس عمون سٕندِ اولاد ہُند مکروہ اوس۔\n8. تہٕ یِتھے پٲٹھۍ کوٚر تٔمۍ پننین سارنٕے عجیب زنانن خٲطرٕ، یِمو بخور زالان تہٕ پننین دیوتاہن خٲطرٕ قربان کٔرۍ۔\n9.\\tتہٕ خداوند اوس سُلیمانس سٍتـ̡ ناراض گومُت، تکیازِ تٔمۍ سُند دِل اوس اسرٲیلِکِس خدایہِ سٍتـ̡ پھیُراونہٕ آمُت، یُس أمِس دۄیہِ لٹہِ ظٲہر گومُت اوس،\n10.\\tتہٕ اوسُن أمِس اَتھ کتھہِ مُتعلِق حُکُم دِتمُت زِ سُہ گژھِ نہٕ باقین دیوتاہن پتہٕ گژھُن، مگر تٔمۍ کٔر نہٕ سُہ یُس خداوند حُکُم دِیُتمُت اوس۔\n11. اَمہِ مۄکھٕ چُھہ خداوند سُلیمانس ووٚنمُت، یێلہِ تێیہِ سٍتـ̡ چُھہ یہِ کرنہٕ آمُت، تہٕ ژے چُھہ میٲنۍ عہد تہٕ میٲنۍ قونوُن، یُس میہ ژے حُکُم چُھ، بہٕ کٔرٕ ژے نِش بادشاہت ژٔٹِتھ تہٕ دِیہٕ چانہِ خادمَس دِنہٕ۔ {چُھ کرنہٕ آمُت...: ہیب۔ چُھ ژے سٍتۍ}\n12. بہٕ تہٕ تہندِس دۅہس منز کٔرٕ نہٕ بہٕ تہندِس مٲلہِ سٕندِ خٲطرٕ تہٕ ژٔٹِتھ تہٕ ژٔٹِتھ تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ ژٔٹِتھ تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ ژٔٹِتھ تہٕ ژ\n13. بہٕ کٔرٕ نہٕ سٲرٕے بادشٲہی ژٔٹِتھ {مگر} دِیہ پننِس نیچوِس اکھ قبیلہٕ، میانہِ خادم سٕندِ خٲطرٕ، تہٕ یروشلم سٕندِ خٲطرٕ یُس مے ژٲرمُت چُھ۔\n14.\\tتہٕ خداوند کٔر سُلیمانس سٍتـ̡ اکھ مُخٲلِف، حداد ادومی سٕندِس سٍتـ̡ سُہ اوس ادومس مَنٛز بادشاہ سٕندِس اولادُک ۔\n15. یێلہِ سٍتـ̡ سپُد یێلہِ داؤد ادومس مَنٛز اوس، تہٕ میزبانُک کپتان یوآب گۆو مقتولن دفن کرنہٕ خٲطرٕ، یێمہِ سٍتـ̡ تٔمۍ سُند پرٮ۪تھ کانہہ مرد دفناونہٕ آمُت۔\n16. (یوآب روٗد سارنٕے اسرٲیلِس سٍتـ̡ شیہ ریتن تتہِ، یوتام تٔمۍ اَدومُک پرٮ۪تھ کانہہ مرد ژٹِھ:)\n17.\\tزِ حداد ژوٚل سُہ تہٕ أمِس سٍتـ̡ مٲلہِ سٕندِس نوکرس سٍتـ̡ مصر گژھنہٕ خٲطرٕ۔ حداد {آسن} وُنہِ تہِ اکھ لۄکُٹ شُر۔\n18.\\tتہٕ تِم گٔیہِ مِدیان پى۪ٹھہٕ تہٕ آۓ پران، تہٕ تِمو نِیہِ پانس سٍتـ̡ نِش تہٕ تِم آیہ مصر کِس بادشاہ فرعونس نِش۔ یٔمۍ أمس اکھ مکانہٕ دِیُت، تہٕ أمِس دِژُن خزانہٕ، تہٕ دِتُن أمِس زمین۔\n19.\\tتہٕ حدادس لوٚگ فرعونس نِش سٮ۪ٹھاہ احسان تہ تٔمۍ دِژ أمِس پننہِ زنانہِ ہٕنز بینہِ، یۄسہٕ تہپینس ملکہ سٕنزِ بینہِ ٲس۔\n20. تہٕ تاہپینس سٕنزِ بینہِ زٲو تس پنُن نیچو جینوبت، یُس فرعون سٕندِس گرس مَنٛز دۄد دِژمُت اوس، تہٕ جینوبت اوس فرعون سٕندِس گرس مَنٛز فرعون سٕندِس نیچوِس منز۔\n21.\\tییلہ حدادس مصرس منز بوز زِ داؤد اوس پننین مٲلن سٍتۍ شوٚنگمت، تہٕ لشکرُک سردار یوآب اوس موٗدمُت، حدادن ووٚن فرعونس زِ بہٕ گژھ پننِس ملکس منز۔ {لیٹ...: ہیب۔ مے سوز دوٗر}\n22. اَمہِ پتہٕ ووٚن فرعونن أمِس زِ ژے کیاہ چُھس میانہِ سٍتـ̡ کُنہِ سٍتـ̡ یێلہِ تێلہِ چ تہٕ تٔمۍ دیُت جواب، کیٚنٛہہ تہِ: بہٕ تہٕ دِیُت بہٕ کُنہِ تہِ پٲٹھۍ گژھُن۔ {کیٚنٛہہ: ہیب۔ نہٕ}\n23.\\tتہٕ خداین کٔر أمِس بیاکھ مُخٲلِف، الیادہ سُند نیچو ریزون، یُس پننِس آقا حدادزر بادشاہس نِش ژوٚل:\n24.\\tتہٕ تٔمۍ کٔر پانس نِش نفر جمع تہٕ بنیوو أکِس جمٲژ ہُند کپتان، ییلہ داؤدن تِم مٲرِتھ تہٕ تِم گٔیہِ دمشقس تہٕ اَتھ مَنٛز روزُن تہٕ کٔرٕن دمشقس مَنٛز حکومت۔\n25.\\tتہٕ سُہ اوس سُلیمان سٕندِس سارِنٕے دۅہس سٍتـ̡ اِسرٲیلُک مُخٲلِف، یێمہِ سٍتـ̡ حدادَن کٔرٕن تہٕ سُہ اوس اِسرٲیلِس سٍتـ̡ نفرت، تہٕ کٔرٕن شامس پؠٹھ بادشاہ۔\n26.\\tتہٕ یربعام نیبت سُند نیچو، یُس زریدہ سُند اِفراتھی اوس، سُلیمان سُند خادم، یٔمۍ سٕنزِ ماجہ ہُند ناو زرواہ اوس، یُس اکھ بیواہ زنانہٕ اوس، تٔمۍ تُل بادشاہس کُن اتھہٕ۔\n27. تہٕ یہِ اوس سُہ وجہ یُس تٔمۍ بادشاہس خلاف اتھہٕ تُلِتھ: سُلیمانن بنوو مِلو، تہٕ کٔرٕن پننِس مٲلِس داؤد سٕندِس شہرٕچ پھُٹٕچ مرمت ۔ {مرمت: ہیب۔ بند}\n28.\\tتہٕ یروبعام اوس اکھ طاقتور بہادر شخص: تہٕ سُلیمانن وُچھِتھ زِ سُہ چُھ محنتی تہٕ بنوو سُہ یوسف سٕندِس گرٕ کِس سارِنٕے عہدس پیٹھ حُکُمران۔ {اوس محنتی: ہیب۔ کٔر کٲم} {چارج: Heb. بوجھ}\n29.\\tتہٕ سپُد تمہِ وِزِ ییلہ یروبوعام یروشلم منزٕ نیبر نیرِ، پیغمبر احیاہ شِلونین وُچھ تس وتہِ منز۔ تہٕ تٔمۍ اوس پانس اکھ نوٚو پلو لٲگتھ۔ تہٕ تِم ٲسۍ زٕ میدانس منٛز کُنی زٕنۍ:\n30.\\tتہٕ احیجہ رٔٹِتھ نٔو پلو یُس أمِس پیٹھ اوس، تہٕ دِژُن بہن ٹُکرَن سٍتـ̡\n31. تہٕ تٔمۍ ووٚن یربوامس زِ ژے نِش دَہ ٹُکرٕ، یِتھ کٔنۍ چُھ خداوند اسرائیلُک خدا، یِتھٕ پٲٹھۍ چُھ ونان زِ بہٕ کٔرٕ سُلیمان سٕندِ اتھہٕ نِش بادشٲہی ژٔٹِتھ تہٕ دِیہٕ ژے داہ قبیلہٕ۔\n32. (مگر تس آسہِ اکھ قبیلہٕ میانِس خادم داؤد سٕندِ خٲطرٕ، تہٕ یروشلم سٕندِ خٲطرٕ، سُہ شہر یُس میہ سارِنٕے اسرٲیلِیو قبیلو منزٕ ژٲرمُت چُھ:)\n33.\\tکیازِ یِمو چُھکھ میہ ترٲومُت، تہٕ چُھکھ زیدونین ہٕنز دیوی اشتوریتس، موآبین ہُند دیوتا، تہٕ عمون سٕندِس اولادَن ہٕندِس دیوتا، تہٕ چُھکھ نہٕ میانین وتہٕ پٲٹھۍ، یُس میانین نظرن منز صحیح چُھ، تہٕ میانین قونونن تہٕ فیصلن ہٕنز پاسگزاری کرنہٕ خٲطرٕ، یِتھٕ پٲٹھـ̡ تٔمۍ سٕندِس مٲلس داؤدس کٔر۔\n34. بہٕ نِہ نہٕ سورے سلطنت تٔمۍ سٕندِ اتھہٕ نِش نِنہٕ، مگر بہٕ بناوٕ سُہ پننہِ زندگی ہٕندِس سارِنٕے دۅہہٕ داؤد سٕندِ خٲطرٕ شہزادہٕ، یُس مے ژٲرمُت، کیازِ تٔمۍ کٔر میٲنۍ حکمہٕ تہٕ میٲنۍ قونونن ہٕنز پابندی:\n35. مگر بہٕ نِیہٕ بادشاہت تٔمۍ سٕندِس نیچوۍ سٕندِ اتھہٕ نِش نِن، تہٕ دِیہ ژے دَہ قبیلہٕ۔\n36. تہٕ بہٕ دِیہ تٔمۍ سٕندِس نیچوِس اکھ قبیلہٕ، یُتھ میون خادم داؤد یروشلمس مَنٛز ہمیشہ میانہِ برونہہ کُن گاش روزِ، سُہ شہر یُس میہ پنُن ناو تھاونہٕ خٲطرٕ منتخب کورمُت چُھ۔ {گاش: ہیب۔ شمع، یا، شمع}\n37. تہٕ بہٕ کرٕ ژے نِن، تہٕ تہٕ ژٕ کرٕ پننہِ روح یژھہٕ مُطٲبق بادشاہ تہٕ بنہٕ اسرٲیلِس پیٹھ بادشاہ۔\n38. تہٕ یێلہِ تہٕ یێلہِ تہٕ یێلہِ بہٕ یێلہِ تہٕ میانہِ وتہِ پٲٹھـ̡ پٔکِھہ، تہٕ میانہِ نظرِ سٍتـ̡ کٔرِو میٲنۍ قونونن تہٕ حُکمن ہٕنز پاسداری، یِتھٕ پٲٹھـ̡ میانہِ خادمَس داؤد سٕندِ حُکمن ہٕنز کٲم کٔرِو۔ زِ بہٕ روزٕ ژے سٍتـ̡ تہٕ ژے اکھ یقینی مکانہٕ بناوُن، یِتھ کٔنۍ مے داؤد سٕندِ خٲطرٕ بنوومُت، تہٕ دِیہٕ اسرٲیلِس ژے دِنہٕ۔\n39.\\tتہٕ بہٕ کٔرٕ داؤد سٕندِس بُلِس مُتعلِق، مگر ہمیشہٕ خٲطرٕ نہٕ۔\n40. سُلیمانن کٔر یروبعام مارنٕچ کوشش۔ تہٕ یربعام ووٚتھ، تہٕ ژوٚل مصرس منٛز، مصر کِس بادشاہ شیشک نِش، تہٕ سُلیمان سٕندِس مرنس تام روٗد مصرس منٛز۔\n41.\\tتہٕ سُلیمان سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕنزِ حکمت، کیا تِم چھِنہٕ سُلیمان سٕنزِ اعمالن ہٕنزِ کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟ {اعمال: یا، الفاظ، یا، چیز}\n42. تہٕ سُہ وقت یُس سُلیمانن یروشلمس مَنٛز سارِنٕے اسرٲیلِس پیٹھ حکومت کٔر، سُہ اوس ژتٲجی ؤری۔ {وقت: ہیب۔ دۄہ}\n43.\\tتہٕ سُلیمان گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ سُہ آو پننِس مٲلس داؤد سٕندِس شہرس مَنٛز دفن کرنہٕ۔ {Rehoboam: Gr. Roboam}","1.\\tتہٕ رحبعام گۆو شیکیمس کُن، تکیازِ سارِوٕے اِسرٲیل اوس أمِس بادشاہ بناونہٕ خٲطرٕ شکیمس نِش آمُت۔\n2.\\tتہٕ سپُد یہِ سپُد، یێلہِ نیبت سُند نیچو یربعام، یُس وُنہِ تہِ مصرس مَنٛز اوس، بوز (تکیازِ سُہ اوس بادشاہ سلیمان سٕنزِ موجودگی نِش ژلنہٕ آمُت، تہٕ یربعام اوس مصرس مَنٛز روزان؛)\n3.\\tیُس تمو سوزمُت تہٕ بُلوو۔ تہٕ یروبعام تہٕ سارِوٕے اسرٲیلٕچ جماعت آیہ، تہٕ وونُن رحبعامس سٍتـ̡ کتھ کرنہٕ،\n4.\\tتێلہِ بنوو پننِس مٲلہِ سٕنزِ گۅب خدمت، تہٕ تٔمۍ سُند گوٚب یوُل یُس تٔمۍ اسہِ پیٹھ تھوو، ہلکہٕ تہٕ أسۍ کٔرِو چانہِ خدمت۔\n5.\\tتہٕ تٔمۍ ووٚن تِمَن زِ ترٚین دۅہن نیرُن، پتہٕ یِن میانہِ نِش دُبارٕ۔ تہٕ لوٗکھ گٔیہِ روانہٕ۔\n6.\\tتہٕ بادشاہ رہبعام کٔر بُزرگس سٍتـ̡ مشورٕ، یُس سُلیمانس مٲلِس برونہہ کنہِ کھڑا اوس، تہٕ وونُن، ژٕ کِتھہ کٔنۍ چُھہ مشورٕ دِوان زِ بہٕ ہیٛکہٕ یِمن لوکن جواب دِتھ۔\n7. تہٕ تِمو کٔر أمِس سٍتـ̡ کتھ ، یێلہِ ژٕ از یِمن لُکن ہُند خادم بٔنِتھ تہٕ تِمن ہٕنز خدمت کٔرِو، تہٕ تِمن سٍتـ̡ رٔژ کتھ کٔرِو، تێلہِ روزن تِم ہمیشہٕ خٲطرٕ تُہٕندِس خادم۔\n8.\\tمگر تٔمۍ ترٲو بُزرگَن ہُند مشورٕ، یُس تِمو أمِس دِژمُت اوس، تہٕ تِمن نوجوانَن سٍتۍ مشورٕ کٔرِتھ یِم أمِس برونہہ کنہِ کھڑا ٲسۍ۔\n9.\\tتہٕ تٔمۍ ووٚن تِمَن زِ أسۍ کیاہ مشورٕ دِوان زِ أسۍ یِمن لُکن جواب دِتھ، یِمو میانہِ سٍتـ̡ کتھ کٔرمٕژ چھِ، سُہ کٔرِو ہلکہٕ یُس چُھہ تٔمۍ سٕندِس مٲلہِ سٍتـ̡ اسہِ پیٹھ تھوومُت اوس۔\n10.\\tتہٕ یِمو جوان أمِس سٍتـ̡ بٔڈِتھ بٔڈِتھ وَنُن زِ یِتھٕ پٲٹھـ̡ کٔرِو تٔمِس لُکن سٍتـ̡ کتھ یِمن سٍتـ̡ تۅہہِ سٍتـ̡ کتھ کٔرِتھ وَنُن زِ تێہٕندِس مٲلہِ سٍتـ̡ چُھہ سٍتـ̡ ہلکہٕ کٔرِتھ کٔرِتھ تہٕ یێلہِ سٍتـ̡ چُھہ یێمہِ سٍتـ̡ یتھہ پاٹھۍ ونن تمن میون لۅکٹۍ {اونگجہ} آسہِ میٲنس مٲلہِ سٕنزِ کمرہ کھۅتہ زیادہ موٚٹ۔\n11. تہٕ وۄنۍ ییٚلہِ میانہِ مٲلہِ ژےٚ گۄب جوُر دِژمٕژ، بہٕ کَرٕ ژےٚ کوڑو سۭتۍ سزا، مگر بہٕ دِیہٕ ژےٚ بِچھو سۭتۍ سزا۔\n12. یێلہِ یێربعام تہٕ سارِوٕے لُکھ آیہِ تریمہِ دۅہہ رِہبعام یُس بادشاہن مقرر کورمُت اوس تہٕ وونُن زِ تریمہِ دۅہہ آو میہ نِش۔\n13. تہٕ بادشاہن دیُت لُکن سختی سان جواب، تہٕ بُزرگ سُند مشورٕ ترٲوُن یُس تمو أمس دِژمُت۔ {تقریباً: ہیب۔ شاید}\n14.\\tتہٕ نوجوانَن ہٕندِ مشورٕ پتہٕ وونُن تِمن سٍتـ̡ زِ میانہِ مٲلہِ کٔر تُہُند جوُر گوٚب، تہٕ بہٕ کٔرٕ تُہٕندِس جوتس منز اضافہٕ: میانہِ مٲلہِ تہِ دِژ ژےٚ کوڑو سٍتـ̡ سزا، مگر بہٕ کٔرٕ ژےٚ بِچھو سٍتـ̡ سزا۔\n15.\\tلہذا کٔر نہ بادشاہن لوکن ہنز کتھ بوز۔ تکیازِ یہِ وجہ اوس خداوند سٕندِ طرفہٕ، یُس خداوند شِلونایت احیاہ سٕندِ ذریعہٕ نیبت سٕندِس نیچوِس یربعام سٕندِس سٍتـ̡ کتھ کٔرمٕژ۔\n16. تێلہِ ییلہ سارِنٕے اسرٲیلَن وُچھ زِ بادشاہن چُھ نہٕ تِمن بوزمُت، لوکو دِژ بادشاہس جواب دِتھ زِ اسہِ کُس حصہٕ چُھ داؤدس مَنٛز۔ نہ چُھہ اسہِ یسیٰ سٕندِس نیچوس سٍتـ̡ وراثت: اے اسرائیل، وۅنۍ وُچھو پنُن گرٕ داؤد۔ چنانچہ دراو اسرائیل پننین خیمن کُن۔\n17.\\tمگر یێلہِ یہوداہ کِس شہرس مَنٛز روزان ٲس، رہوبعام کٔر تِمن پیٹھ بادشاہت۔\n18.\\tتمہِ پتہٕ سوٗز بادشاہ رحبعام اڈورام، یُس خراج دِنس پیٹھ اوس۔ تہٕ سارِوٕے اِسرٲیلَن لگٲوۍ أمِس کَنہِ پَنٕنہِ سٍتـ̡ سُہ مٔرِتھ۔ تَمہِ کِنۍ کٔر بادشاہ رہبعام سُہ پننِس رتھس تام واتناوُن، یروشلم کُن ژلنہٕ خٲطرٕ۔ {بنیومُت...: ہیب۔ پنُن پان کٔرُن مضبوط}\n19.\\tیێلہِ کٔر اسرٲیلَن از تام داؤد سٕندِس گرس خلاف بغاوت ۔ {بغاوت: یا، پیوٚو دور}\n20. تہٕ سپُد یێلہِ سارِنٕے اِسرٲیلِیو یہِ بوٗز زِ یروبعام آو دُبارٕ آمُت، تِمو سوٗزِتھ بُلووُکھ سُہ سارِنٕے اسرٲیلِس پٲٹھـ̡ بادشاہ۔\n21.\\tییلہ رحبعام یروشلم آو تٔمۍ کٔر یہوداہ کِس سارِنٕے گرس سٍتـ̡ بنیامین سٕندِس قبیلس سٍتـ̡ اکھ ہتھ ژۅن ساس منتخب نفر، یِم جنگجو ٲسۍ، یُس اسرٲیلِس گرس خلاف لڑنہٕ مۅکھہٕ تہٕ بادشاہت دُبارٕ سُلیمان سٕندِس نیچوِس رحبعام نِش اننہٕ مۅکھہٕ۔\n22.\\tمگر خدایہ سُند کلام ووت خدایہ سٕندِس انسانس نِش وونُن،\n23. یہوداہ کِس بادشاہ سُلیمان سٕندِس نیچوِس رحبعام سٍتـ̡ تہٕ یہوداہ تہٕ بنیامین سٕندِس سارِنٕے گھرس سٍتـ̡ تہٕ باقٕے لُکن سٍتـ̡ کتھ کرٕن،\n24. یِتھٕ پٲٹھـ̡ چُھ خداوند فرماوان زِ تُہۍ گژھِو نہٕ ہیوٚر کھسُن، تہٕ نہ کرو پننین باین سٍتـ̡ اسرٲیلِس سٍتـ̡ لڑُن: پرٮ۪تھ کانہہ نفر کرو پننِس گرس مَنٛز واپس۔ تکیازِ یہ چیز چھُ میانہِ طرفہٕ۔ تێمہِ کِنۍ بوز تِمو خداوند سُند کلام، تہٕ گٔیہِ خداوند سٕندِ کلامٕ مُطٲبق نیرنہٕ خٲطرٕ واپس۔\n25.\\tپتہٕ بنیوو یربعام کوہ افرائیم کِس مَنٛز شیکیم تہٕ اَتھ مَنٛز روزُن۔ تہٕ تتہٕ نیٚبر تہٕ بنووُن پینویل۔\n26. تہٕ یربعام ووٚن پننِس دِلس منز، وۄنۍ گژھِ بادشٲہی داؤد سٕندِس گرس مَنٛز واپس۔\n27.\\tیێلہِ یہوداہ کِس بادشاہ رحبعام سٕندِس کُن دُبارٕ پھیرِ، تہٕ تِم گژھن میہ مٲرِتھ تہٕ دُبارٕ یہوداہ کِس بادشاہ رحبعام کِس نِش گژھن۔\n28. اَمہِ پتہٕ کٔر بادشاہن مشورٕ تہٕ بَنووُن زٕ بَچھرٕ سۄنہٕ تہٕ تِمن وونُن، یروشلم تام گژھُن چُھ تۅہہِ خٲطرٕ واریاہ زیادٕ: اے اسرائیل، وُچھِو پنٕنۍ دیوتا، یٔمۍ ژے مصر کہِ سرزمینہٕ منزٕ نیبر کٔرۍ۔\n29.\\tتہٕ تٔمۍ تھوو اکھ بیت ایلس منٛز، تہٕ بیٛاکھ تھووُن سُہ دانس منٛز۔\n30.\\tتہٕ یہِ چیز بنیوو گۅناہ: تکیازِ لُکھ گٔیہِ أکِس برونہہ کُن عبادت کرنہٕ خٲطرٕ، {حتیٰ کہ} دانس نِش۔\n31. تہٕ بنوو تھدِ مقامن ہُند اکھ گر، تہٕ بنووُن سارِوٕے کھۄتہٕ بٔنِم لُکن ہٕندِس پادٕرۍ، یِم نہٕ لیوی سٕندِس نیچوِس سٍتـ̡ ٲسۍ۔\n32.\\tتہٕ یربعام کٔر ٲٹھمہِ ریتس مَنٛز اکھ دعوت مقرر یُس یہوداہ کِس دعوتس مُتلق چُھ، تہٕ تٔمۍ کٔر قربان گاہس پیٹھ پیش کرنہٕ۔ یِتھے پٲٹھۍ کٔر تٔمۍ بیتھلس مَنٛز، تِمن بَچھرٮ۪ن خٲطرٕ قربان یِم تٔمۍ بنٲومٕتۍ ٲسۍ، تہٕ تٔمۍ تھووُن بیتھلس مَنٛز تِمن تھدٮ۪ن مقامن ہٕندۍ پادٕرۍ یِم تٔمۍ بنٲومٕتۍ ٲسۍ۔ {پیش کرنہٕ...: یا، گٔیہٕ قربان گاہس تام وغیرہ} {قربانی: یا، قربانی دِنہٕ}\n33.\\tیێلہِ کٔر تٔمِس قربان گاہس پیٹھ یُس تٔمۍ ٲٹھمہِ ریتہٕ کِس پنٛدٲہمہِ دۅہہٕ بنوومُت اوس، تتھ ریتس مَنٛز یُس تٔمۍ پننہِ دِلہٕ سٍتـ̡ بنوومُت اوس۔ تہٕ کوٚرُن بنی اِسرٲیلِس خٲطرٕ دعوت مقرر تہٕ تٔمۍ کٔرٕن قربان گاہس پیٹھ پیش تہٕ زٲلِن بخور ۔ {پیش کرنہٕ...: یا، گٔیہٕ قربان گاہس تام وغیرہ} {تہٕ دزنہٕ...: ہیب۔ اگربتی زالنہٕ خٲطرٕ}","1. تہٕ وُچھ یہوداہ سٕندِ کلامٕ سٍتـ̡ خدایہِ سُند اکھ انسان دراو بیتھل کُن، تہٕ یربعام ووت قربان گاہس نِش بخور زالنہٕ خٲطرٕ۔ {برن: یا، پیشکش}\n2. تہٕ تٔمۍ کٔر خداوند سٕندِس کلامَس مَنٛز قربان گاہس خلاف فریاد تہٕ وونُن، اے قربان گاہ، یِتھٕ پٲٹھۍ چُھ خداوند وَنان۔ وُچھِو، داؤد سٕندِس گرس مَنٛز گژھہِ اکھ شُر زامُت، یُس یوسیاہ ناو آسہِ۔ تہٕ سُہ کرِ توے پیٹھٕ تھدٮ۪ن جاین ہٕندۍ پادٕرۍ پیش یِم توے پیٹھ بخور زالان چھِ، تہٕ انسانن ہٕنزِ أڈجہِ یِن توے پیٹھ زالنہٕ۔\n3.\\tتہٕ تٔمۍ دِژ امی دۅہہ اکھ نشانہٕ، یُس خداوند سُند ونُن چُھ۔ وچھ قربان گاہ ییہ پھٹنہٕ، تہٕ اتھ پیٹھ یُس سوٗر یِن تراونہٕ۔\n4. تہٕ سپُد یہِ سپدُن، یێلہِ بادشاہ یربعام سُند یہ کلام بوز، یُس بیت ایلس مَنٛز قربان گاہس خلاف فریاد اوس دِژمُت، تٔمۍ تروو قربان گاہٕ پیٹھٕ اتھہٕ تہٕ وونُن زِ أمِس تھپھ کٔرِو۔ تہٕ تٔمۍ سُند اتھ، یُس تٔمۍ پانس خلاف تھوو، گوٚو خشک تہ سہ ہیوٚک نہٕ یہ دُبارٕ پانس کُن لٔگتھ۔\n5.\\tقربان گاہ تہِ آو پھٹراونہٕ، تہٕ سوٗر آو قربان گاہ منزٕ دِنہٕ، یُس خدایہ سٕندِ انسانس خداوند سٕندِ کلامٕ سٍتـ̡ دِژمُت اوس۔\n6. تہٕ بادشاہن دیُت جواب تہٕ وونُن خدایہ سٕندِس انسانس زِ وۅنۍ کرٕ خداوند پنُن خدایہ سُند بُتھ رٔٹِتھ تہٕ میانہِ خٲطرٕ دُعا کٔرِتھ یُتھ میون اتھہٕ دُبارٕ دُبارٕ دُعا کرنہٕ۔ تہٕ خدایہِ سُند انسان کٔر خداوند سٕندِ اتھہٕ دُبارٕ دُبارٕ بحال تہٕ بنیوو یُتھ {یہِ} گوڈٕ اوس۔ {خداوند تہٕ: ہیب۔ رب سُند بُتھ وغیرہ}\n7. تہٕ بادشاہن ووٚن خدایہ سٕندِس انسانس سٍتـ̡ یِمن سٍتـ̡ گَرٕ یِن، تہٕ پَنُن پان تازٕ کرُن، تہٕ بہٕ دِیہٕ ژے اکھ انعام۔\n8. تہٕ خدایہِ سٕندِس انسانس ووٚن بادشاہس زِ اگر ژٕ ژٕ پنُن نصف مکانہٕ دِیُو، بہٕ گژھٕ نہٕ ژےٚ سٍتـ̡ اژُن، نہ بہٕ کھیٚیہٕ روٹی تہٕ نہ چیٚہٕ آب یَتھ جایہ۔\n9.\\tیِتھے پٲٹھۍ آو میہ خداوند سٕندِ کلامٕ سٍتـ̡ حکم دِنہٕ، یێلہِ نہٕ کھیٚیو نہٕ روٹی تہٕ نہ پییُن آب تہٕ نہ پھیُر یِتھٕ پٲٹھۍ۔\n10. تہٕ سُہ گوٚو بییِس وتہِ تہٕ واپس آو نہٕ یُس سُہ بیتھل آو ۔\n11. وۅنۍ اوس بیت ایلس منز اکھ پرون پیغمبر روزان۔ تہٕ تٔمۍ سٕندۍ نیچوۍ آیہِ تہٕ وونُن تٔمِس تِم سٲری کٲم یِم خدایہِ سٕندِ انسانن تمہِ دۅہہ بیتھلس منز کٔرمٕژ ٲسۍ، تِم لفظ یِم تٔمۍ بادشاہس سٍتـ̡ کٔرۍمٕتۍ، تِم ٲسۍ تِمو پننِس مٲلِس تہِ وننہٕ آمٕتۍ۔\n12.\\tتہٕ تِہٕندِس مٲلہِ ووٚن تِمن کُس وَتہٕ گٔیہِ؟ تکیازِ تٔمۍ سٕندِس نیچویو اوس وُچھمُت زِ خدایہ سُند انسان کُس وتہِ چُھ، یُس یہوداہ پیٹھہٕ آو۔\n13.\\tتہٕ تٔمۍ ووٚن پننین نیچوین زِ میہ کٔرِو گٔرۍ۔ تہٕ تِمو لوٚگ أمِس گَرٕ تہٕ سُہ سوارِ سوار،\n14.\\tتہٕ وُچھ خدایہ سٕندِس انسانس پَتہٕ، تہٕ وُچھُن سُہ أکِس بلوطس تَل بِہِتھ، تہٕ تٔمِس ووٚنُن، {کیا تُہۍ چھُکھ خدایہِ سُند انسان یُس یہوداہ پیٹھہٕ آمُت چھُ؟ تہٕ تٔمۍ ووٚن، بہٕ چھُس۔\n15.\\tاَمہِ پتہٕ ووٚن أمِس زِ مےٚ سٍتـ̡ گَرٕ یِنہٕ تہٕ کھیٚیہِ بٔرِتھ۔\n16.\\tتہٕ ووٚن بہٕ ہیوٚک نہٕ ژےٚ سٍتـ̡ واپس یِتھ، تہٕ نہ گژھٕ ژے سٍتـ̡ یَتھ جایہِ پى۪ٹھ۔\n17.\\tیِکیازِ یہِ چُھہ میہ خداوند سٕندِ کلامَس سٍتـ̡ وننہٕ آمُت زِ ژے گژھ نہٕ روٹی کھٮ۪وان تہٕ نہ چیٚہٕ آب تہٕ یێلہِ پٲٹھـ̡ پۯاوٕ۔ {یہ...: ہیب۔ اکھ لفظ اوس}\n18.\\tتٔمۍ ووٚن تٔمِس زِ بہٕ چُھس تہِ پیغمبر تہِ یِتھے پٲٹھۍ۔ تہٕ أکِس فرشتہٕ کٔر میہ رب سٕندِ کلامٕ سٍتـ̡ وونُن زِ سُہ أنِو پانس سٍتـ̡ پننِس گَرَس مَنٛز، یُتھ سُہ کھیٚیہِ روٹی تہٕ آب چیٚنہٕ۔ {مگر} اوس تٔمِس اپُز اپُز۔\n19. تہٕ سُہ گوٚو أمِس سٍتـ̡ واپس، تہٕ کھیوٚن پننِس گَرَس مَنٛز روٹی تہٕ آب چیوٚن۔\n20.\\tتہٕ ییلہ تم میزس پیٹھ بِہتھ ٲسۍ، خداوند سُند کلام آو پیغمبرس نِش یُس تس واپس ان:\n21. تہٕ تٔمۍ کٔر یہوداہ سٕندِس انسانس کُن یُس یہوداہ پیٹھہٕ آمُت چُھ، یِتھٕ پٲٹھۍ چُھ خداوند سٕندِس ٲسِس نافرمانی کٔرمٕژ، تہٕ یُس حُکُم چُھہ نہٕ پورٕ کٔرِتھ یُس خداوند تُہٕندِس خدایہِ سُند حُکُم دِیُتمُت چُھ،\n22.\\tمگر آو واپس تہٕ کھیوٚن روٹی تہٕ آب چیٚوُن، یُس {خدا} ژےٚ ووٚنمُت چھُ، روٹی کھیٚیو نہٕ تہٕ آب چیٚو۔ تُہند لاش گژھِ نہٕ پننین مٲلن ہٕندِس قبرس پیٹھ واتہِ۔\n23.\\tتہٕ سپُد تٔمِس روٹی کھٮ۪نہٕ پَتہٕ تہٕ چیٚنہٕ پتہٕ سپُد أمِس نبی سٕندِ خٲطرٕ گَرٕ دِنہٕ۔\n24.\\tتہٕ ییلہ سُہ درٛاو، اَکھ سٕہہ وَتہِ وَتہِ مِلیوٚو، تہٕ مارُن سُہ تہٕ تٔمۍ سُند لاش آو وتہِ کُن تراونہٕ، تہٕ گَرٕ اوس اَتھ نِش کھڑا، سٕہہ تہِ کھڑا لاشہٕ نِش۔\n25.\\tتہٕ وُچھ انسان اَتھ وتہِ منز، تہٕ وُچھُن لاشہٕ وتہِ منز، تہٕ وُچھُن سٕہہ لاشہٕ نِش کھڑا تہٕ تِم آیہ تہٕ وونُن تتھ شہرس مَنٛز ییتہِ پرون پیغمبر روزان اوس۔\n26. تہٕ ییلہ أمِس وتہٕ پیٹھٕ واپس اننہٕ وٲلِس پیغمبرن بوز، تٔمۍ ووٚن زِ یہِ چُھ خدایہِ سُند انسان یُس خداوند سٕندِس کلامٕچ نافرمانی اوس کٔرمٕژ، تێمہِ مۅکھٕ چُھ خداوند سٕندِس کلامَس مُطٲبق سُہ شیرس حوالہٕ کورمُت تہٕ مٲرِتھ دِژمُت یُس تٔمِس سٍتـ̡ کتھ کٔرمٕژ چُھ۔ {پھٹمُت: ہیب۔ پھُٹمُت}\n27.\\tتہٕ تٔمۍ ووٚن پننٮ۪ن نیٚچوٮ۪ن سٍتـ̡ کٔرِتھ وَنُن زِ مے کٔرِو گَرٕ کٔرِتھ۔ تہٕ تمو کٔر سیڈ۔\n28.\\tتہٕ سُہ گوٚو تہٕ وُچھ پنُن لاشہٕ وتہِ وتہِ کٔرِتھ، تہٕ گَرٕ تہٕ شیر اوس لاشہٕ نِش کھڑا کھڑا اوسمُت: شیرن اوس نہٕ لاشہٕ کھٮ۪ومُت تہٕ نہ اوس گَردٕ ژٔٹمُت۔ {پھٹمُت: ہیب۔ پھُٹمُت}\n29.\\tتہٕ پیغمبرن تُل خدایہ سٕندِ انسان سُند لاشہٕ تہٕ تھووُن گَرَس پیٹھ، تہٕ أنِن واپس۔ تہٕ پرون پیغمبر آو شہرس مَنٛز، ماتم کرنہٕ تہٕ دفن کرنہٕ خٲطرٕ۔\n30.\\tتہٕ تٔمۍ ترٛوو پنُن لاش پننہِ قبرِ منٛز۔ تہٕ تِمو کٔر أمِس پیٹھ ماتم تہٕ وَنُن، افسوس، میون بٲے!\n31.\\tتہٕ یہِ سپُد أمِس دفن کرنہٕ پتہٕ، یێلہِ بہٕ مرُن، تیلہِ کٔرِو مے تتھ قبرس مَنٛز دفن یَتھ مَنٛز خدایہِ سُند انسان دفن کرنہٕ آمُت چھُ۔ میٲنۍ أڈجہِ ترٲو تٔمۍ سٕنزِ أڈجہِ سٍتۍ:\n32.\\tیُس کلام یُس تٔمِس خداوند سٕندِ کلامٕ سٍتـ̡ بیتھلس مَنٛز قربان گاہس خلاف تہٕ سامریہٕ کین شہرن مَنٛز موجود تھدٮ۪ن مقامن ہٕندِس سارنٕے گرن خلاف یُس کُنہِ کلامَس سٍتـ̡ وُچھمُت چُھ، سُہ گژھہِ یقینا سپدُن۔\n33.\\tامہ پتہ آو نہٕ یربعام پننہِ بد وتہِ نشہِ واپس، بلکہ بنووُن دُبارٕ تھدٮ۪ن مقامن ہٕندِس پادٕرۍ سٍتـ̡ یُس یژھہٕ کرُن، سُہ بنوو سُہ مقدس تہٕ بنیوو تھدٮ۪ن مقامن ہٕندِس پادٕرۍ سٍتـ̡ ۔ {بنیومُت...: ہیب۔ واپس تہٕ بنوو} {مقدس ...: ہیب۔ پنن اتھہ بٔرتھ}\n34.\\tتہٕ یہِ چیز بنیوو یربعام سٕندِس گرس خٲطرٕ گۅناہ، حتیٰ کہ یہِ ژٹنہٕ خٲطرٕ تہٕ زمینہٕ پیٹھٕ تباہ کرنہٕ خٲطرٕ۔","1.\\tتمہِ وِزِ گۆو یروبعام سُند نیچو ابییاہ بٮ۪مار۔\n2.\\tتہٕ یروبعام ووٚن پننہِ زنانہِ وُچھِتھ تہٕ بہٕ ژے دُعا کٔرِتھ تہٕ پَنُن پوش کٔرِتھ زِ ژٕ گژھ نہٕ یربعام سٕنز زنانہٕ زاننہٕ یِنہٕ۔ تہٕ ژے واتہٕ شیلوہس نِش: وچھ اتہِ چھُ احیجہ پیغمبر، یمۍ مے ووٚنمُت زِ بہٕ گژھہِ یِمن لوکن ہُند بادشاہ بنُن۔\n3.\\tتہٕ پانس سٍتۍ نِیو داہ روٹۍ، تہٕ ماچھ تہٕ أمِس نِش گژھِ، سُہ وَنُن زِ شُرِس کیا بنہِ۔ {with...: Heb. تۅہہِ اتھس منز} {کریکنلز: یا، کیکس} {کروز: یا، بوتل}\n4. تہٕ یربعام سٕنزِ زنانہِ کٔر یۅہے تہٕ ووٚتھ، تہٕ گٔیہِ شیلوہ کُن تہٕ آیہِ احیجہ سٕندِس گَرَس مَنٛز۔ مگر احیجاہ ہیوٚک نہٕ وُچھان۔ تکیازِ تٔمۍ سٕنزِ وٲنسہِ ہٕندِ وجہ سٍتۍ ٲس تٔمۍ سٕنز أچھ بٔنِتھ۔ {ٲس...: ہیب۔ تٔمۍ سٕنٛدس ہورینس خٲطرٕ کھڑا}\n5.\\tتہٕ خداوند ووٚن احیجاہَس زِ وُچھِو یروبعام سٕنز زنانہٕ چھے تۅہہِ نِش پننِس نیچوِس منگنہٕ خٲطرٕ یِوان۔ تکیازِ سُہ {چُھ} بیمار: یِتھٕ پٲٹھۍ تہٕ یِتھٕ پٲٹھۍ تہٕ تٔمِس وَنُن: کیازِ ییلہ سۄ اژِ، سُہ گژھہِ پانس بیاکھ {زنانہٕ} بننُک بہانہ کرُن۔\n6.\\tتہٕ یێلہِ یێلہِ اَحیاہ ہٕندِس قدمن ہٕنز آواز بوز، یێلہِ سُہ دروازس پیٹھ اژِ، تٔمۍ ووٚن اژُن، اے یربعام سٕنزِ زنانہٕ۔ ژیہ کیازِ چھکھ پانس بیاکھ بنُن ظٲہر کران؟ تکیازِ بہٕ چُھس {am} ژے سوزمُت {سٍت} گٔبۍ {خبر}۔ {ہیو: ہیب۔ ہارڈ}\n7. یێلہِ چُھہ یێربعامُک خداوند وَنُن، یێلہِ چُھہ ژے لُکہٕ منزٕ تھزراونہٕ آمُت، تہٕ بنووُکھ ژے پننین لوکن ہٕندِس اسرٲیلس پیٹھ بادشاہ،\n8.\\tتہٕ کٔرٕن بادشاہت داؤد سٕندِس گرس نِش ژٔٹِتھ تہٕ دِژُن ژے تہٕ توتہِ چُھہ نہٕ میانہِ خادم داؤدٕکۍ پٲٹھۍ، یُس میانہِ حُکمن پیٹھ عمل کٔرِتھ، تہٕ یُس میانہِ نظرِ سٍتـ̡ دِل دِنہٕ آمُت اوس، سُہ کٔرِتھ {یُس} میانہِ نظرِ منز صحیح۔\n9. مگر ژے کٔرٕن سارِوٕے کھۄتہٕ زیادٕ بُرکار کٔرِتھ، تکیازِ ژے چھُکھ پانس بییِہ دیوتا بنٲومٕتۍ، تہٕ پٔہلِتھ مجسمہٕ بنٲومٕتۍ، تہٕ ژے کٔرِکھ میہ پَنٕنہِ پَتہٕ کُن دِنہٕ۔\n10. تێمہِ وِزِ بہٕ یروبعام سٕندِس گرس پیٹھ بد کار اَن، تہٕ یروبعام سٕندِس دیوارس سٍتـ̡ ژٔٹِتھ ژٔٹِتھ تہٕ یُس اسرٲیلِس مَنٛز بند تہٕ تراونہٕ آمُت چُھ، تہٕ یِتھٕ کٔنۍ یێربعام سٕندِس گرٕچ باقیات نِش نِش نِتھ یُس اِسرٲیلِس مَنٛز بند آسہِ۔\n11. یُس شہرس مَنٛز یربعام سُند مرُن آسہِ، سُہ گژھہِ ہونۍ کھٮ۪ن۔ تہٕ یُس کھاہس منز مران چُھ، سُہ گژھہِ ہوہٕکۍ جاناوار کھٮ۪ن: کیازِ خداوند چُھ کتھ کٔرمٕژ۔\n12.\\tتَمہِ مۄکھٕ وُچھِو پَنٕنِس گَرَس مَنٛز: {تہٕ} ییٚلہِ تُہٕندِس کھۅر شہرس مَنٛز اژِو، شُر گژھہِ مَرُن۔\n13. تہٕ سارِوٕے اِسرٲیل کرِ أمِس سٕندِ خٲطرٕ ماتم تہٕ دفن کرنہٕ، تکیازِ یێلہِ سُہ یێلہِ یروبعام سٕندِس گرس مَنٛز یِنہٕ وٲلِس خدایہِ سٕندِس خداہس سٍتـ̡ یێلہِ\n14. امہِ علاوٕ کرِ خداوند سُہ اسرٲیلس پیٹھ اکھ بادشاہ کھڑا کرُن، یُس تمہِ دۅہہ یربعام سُند گرٕ ژٹِھہِ: مگر کیا؟ وُنہِ تہِ۔\n15.\\tیِتھ کِنۍ خداوند کرِ اسرٲیلِس مارُن، یِتھٕ کٔنۍ آبس مَنٛز نِش لٔٹِتھ تہٕ سُہ کٔرِن اسرٲیلِس یَتھ اصل زمینہٕ منز، یُس تٔمۍ تِہندین مٲلن دِژمُت اوس، تہٕ دِیہِ تِم دریاوس اپارِ پھِرِتھ، کیازِ تِمو چُھ پنٕنۍ باغ بنٲومٕژ، یێلہِ سٍتـ̡ خداوند سُند شَرارتہٕ ہُند شِرارتہٕ دِنہٕ آمُت۔\n16. تہٕ سُہ تراوِ یربعام سٕندِ گۅنہہ سٍتـ̡ یێمہِ سٍتـ̡ گۅناہ کٔرِتھ تہٕ یٔمۍ اسرٲیلـ̡ گۅنہٕ بنوومُت چُھ۔\n17.\\tتہٕ یروبعام سنز زنانہِ ووٚتھ، تہٕ دراو ترزاہس نِش: {تہٕ}ییلہ سۄ دروازٕ کِس دروازس پیٹھ آیہ، شُر موٗد۔\n18.\\tتہٕ تِمو دفن کٔرِتھ دفن۔ تہٕ سارِنٕے اسرٲیلَن کٔر خداوند سٕندِ کلامَس مُطٲبِق أمِس خٲطرٕ ماتم ، یُس تٔمۍ پننِس خادم احیجا نبی سٕندِ اتھہٕ سٍتـ̡ کتھ کٔر۔\n19. تہٕ یروبعام سٕندِ باقٕے اعمال ، کِتھہ کٔنۍ کوٚر تٔمۍ جنگ تہٕ کِتھہٕ کٔنۍ کٔر تٔمۍ بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ۔\n20.\\tتہٕ یِم دۅہ یِمن ہٕندِس دۅہہٕ یِمن ہٕندِس مٲلِس سٍتـ̡ شوٚنگِتھ تہٕ تٔمۍ سٕندِس نیچوِس ندابن کٔر أمِس بدلہٕ بادشاہ۔ {شوٚنگتھ: ہیب۔ لیٹ ڈاون}\n21. تہٕ سلیمان سُند نیچو رحبعام کٔر یہوداہَس مَنٛز حکومت۔ رحبعام اوس ژتٲجی وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز سدہ ؤری حکومت، سُہ شہر یُس خداوند اسرائیل کین تمام قبیلو منزٕ ژٲرمُت اوس، تتہِ پنُن ناو تھاونہٕ خٲطرٕ۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس نعمہ اکھ امونائیٹیس۔\n22. تہٕ یہوداہَن کٔر خداوند سٕندِس نظرس مَنٛز بُر، تہٕ تِمو کٔر أمِس پننیو گۅناہو سٍتـ̡ حسد کرنہٕ خٲطرٕ اِجازت دِنہٕ۔\n23.\\tتکیازِ تِمو بنٲو تِمن تھدِ جایہ، مجسمہٕ تہٕ باغ، پرٮ۪تھ تھدِ بالس پیٹھ، تہٕ پرٮ۪تھ سبز کُلِس تل۔ {تصویر: یا، کھڑا تصویر، یا، مجسمہٕ}\n24.\\tتہٕ زمینس مَنٛز ٲسۍ سدومی تہِ: {تہٕ} تِمو کٔر قومن ہٕندِس سارِنٕے ناپاک مُطٲبق یِم خداوند بنی اسرٲیلِس برونہہ کُن کٔرۍ۔\n25.\\tتہٕ یہِ سپُد بادشاہ رہوبعام سٕندِس پوٗنٛژمِس ؤریس مَنٛز، {یہ} مصرُک بادشاہ شیشاک آو یروشلمس خلاف ۔\n26. تہٕ تٔمۍ نِش نِش خداوند سٕندِ گرُک خزانہٕ تہٕ بادشاہ سٕندِ گرُک خزانہٕ۔ تٔمۍ نِش نِیہِ سورُے تہِ: تہٕ تٔمۍ نِیہِ سۄنہٕ سٕنزِ سارِنٕے ڈھال یِم سُلیمانن بنٲومٕژ ٲسۍ۔\n27.\\tتہٕ بادشاہ رہبعام بنوو تِمن ہٕندِ بدلہٕ بریسن ڈھالہٕ، تہٕ کوٚرُن بادشاہ سٕندِس گرُک دروازٕ تھاون وٲلِس سردارس اتھس حوالہٕ۔ {گارڈ: ہیب۔ رنرز}\n28.\\tتہٕ یہِ اوس {یێلہِ} ییلہ بادشاہ خداوند سٕندِس گرس منز ژاو تہٕ رٲچھ کرن والٮ۪ن کٔر تِم نِش تہٕ أنِن واپس رٲچھ خانس مَنٛز۔\n29.\\tوۅنۍ چھہِ رحبعام سٕندِ باقی اعمال تہٕ یُس تٔمۍ کٔرۍ، کیا تم چھہِ نہٕ یہوداہ کین بادشاہن ہٕنزِ تواریخ کِس کتابہِ منز لیکھنہٕ آمٕتۍ؟\n30.\\tتہٕ رِحبعام تہٕ یربعام درمِیان اوس سارِنٕے دۅہن جنگ۔\n31. تہٕ رحبعام گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ سُہ آو پننین مٲلن سٍتـ̡ دفن کرنہٕ۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس نعمہ اکھ امونائیٹیس۔ تہٕ أمۍ سٕنٛدِ نیچوۍ ابیجامَن کٔر أمۍ سٕنٛدِ بدلہٕ حکوٗمت۔ {ابیجام: ابیجہ تہِ ونان چھہِ}","1. وۅنۍ کٔر بادشاہ یربعام سٕندِس اردٲہمہِ ؤریس منز نیبت سٕندِ نیچو ابیجامس پیٹھ یہوداہَس پیٹھ حکومت۔\n2. تریہ ؤری کٔر یروشلمس مَنٛز حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس ماچہ، یۄس ابیشلوم سٕنز کوٗر ٲس۔ {ماخہ...: یتھ تہِ ونان چھہِ، میکایا یُس یوریل سنز کوٗر تہِ ونان چھہِ} {ابیشالوم: یتھ ابسالوم تہِ ونان چھِ}\n3. تہٕ سُہ اوس پننِس مٲلہِ سٕندِس سارِنٕے گۅنہہ سٍتـ̡ پٔکِتھ، یُس تٔمِس برونہہ کُن اوس کٔرمُت، تہٕ تٔمۍ سُند دِل اوس نہٕ خداوند سٕندِس خداہس سٍتـ̡ کامل یُس تٔمۍ سٕندِس مٲلِس سٍتـ̡ دِل اوس۔\n4. بہر حال دِژ خداوند تٔمۍ سٕندِس خدایہِ سٕندِ خٲطرٕ یروشلمس مَنٛز اکھ شمع، یُس تٔمِس نیچوِس پَتہٕ قٲیم کرنہٕ خٲطرٕ، تہٕ یروشلم قٲیم کرنہٕ خٲطرٕ: {چراغ: یا، شَمبہٕ}\n5.\\tکیازِ داؤد کٔر خداوند سٕندِس نظرِ منز سُہ تہٕ کُنہِ تہِ چیزس نِش پھیُر نہٕ یُس أمِس سارِنٕے دۅہہٕ حُکُم دِیُت، سوائے یوریاہ ہِٹی سٕندِس معاملس مَنٛز۔\n6.\\tتہٕ تٔمۍ سٕنزِ زندگی ہٕندِس سارِنٕے دۅہن اوس رحبعام تہٕ یربعامس درمِیان جنگ۔\n7.\\tوۅنۍ ابیجام سٕندِ باقٕے اعمال تہٕ یُس تٔمۍ کٔرۍ، کیا تِم چھِنہٕ یہوداہ کین بادشاہن ہٕنزِ تواریخ کِس کتابہِ منز لیکھنہٕ آمٕتۍ؟ تہٕ ابیجامس تہٕ یربعامس درمیان اوس جنگ۔\n8.\\tتہٕ ابیجام گۆو پننین مٲلن سٍتـ̡ شوٚنگ۔ تہٕ تِمو دفن سُہ داؤد شہرس مَنٛز: تہٕ تٔمۍ سٕندِس نیچوِس آسا کٔر أمِس بدلہٕ حکوٗمت۔\n9. تہٕ یربعام سٕندِس وُہمہِ ؤریس مَنٛز کٔر اسرٲیلٕکۍ بادشاہ یہوداہَس پیٹھ آسا سٕنز حکومت۔\n10. تہٕ ژتٲجی ؤرین کٔر یروشلمس مَنٛز حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس ماچہ، یۄس ابیشلوم سٕنز کوٗر ٲس۔ {ماجہ: یعنی نانہِ}\n11.\\tتہٕ آساہن کٔر خداوند سٕندِس نظرِ مَنٛز صحیح، یِتھ کٔنۍ تٔمۍ سٕندِس مٲلِس داؤد۔\n12.\\tتہٕ تٔمۍ کٔرِن سَدومی زمینہٕ منزٕ نِش تہٕ تِم سٲری بُت ہٹٲوِن یِم تٔمۍ سٕندِس مٲلہِ سٕندِ بٔنِتھ ٲسۍ۔\n13.\\tتہٕ ماچہ تہِ ٲس تسٕنزِ موج، حتیٰ کہ أمِس ٲس ملکہ نِش ہٹٲومٕژ، تکیازِ تٔمۍ ٲس أکِس باغس مَنٛز بُت بنوومُت۔ تہٕ آساہن کٔر پنُن بُت تباہ، تہٕ زٲلِن نالہٕ کِڈرن سٍتۍ۔ {تباہ: ہیب۔ کٹ آف}\n14.\\tمگر تھدِ جایہ آیہ نہٕ ہٹاونہٕ، توتہِ اوس آسا سُند دِل سارِنٕے دۅہن خداوند سٕندِ سٍتـ̡ کامل۔\n15.\\tتہٕ تِم چیز یِم أمۍ سٕندِس مٲلہِ وقف کٔرۍمٕتۍ ٲسۍ، تہٕ یِم چیز پانہٕ وقف کٔرۍمٕتۍ، رۄپہٕ تہٕ سۄنہٕ تہٕ بانہٕ۔ {چیز: ہیب۔ مقدس}\n16.\\tتہٕ اوس آسا تہٕ اسرائیلٕکۍ بادشاہ بعشاہس درمِیان سارِنٕے دۅہن جنگ سپدان۔\n17.\\tتہٕ اسرائیلُک بادشاہ باشا ووت یہوداہُک خٕلاف، تہٕ بنوو رامہ یُتھ نہٕ یہوداہ کِس بادشاہ آساہس نِش اژُن۔\n18.\\tپتہٕ نِیُن سٲرِے رۄپہٕ تہٕ سۄنہٕ یُس خداوند سٕندِس گرٕ کِس خزانس مَنٛز باقٕے اوس، تہٕ بادشاہ سٕندِس گرٕکۍ خزانہٕ تہٕ دِتُن تِم پننین خدمتگارن ہٕندِس اتھس مَنٛز۔ تہٕ بادشاہ آساہن سوٗزۍ تِم شامُک بادشاہ حزیون سُند نیچو تبریمون سٕندِس نیچوِس بنہادادس نِش۔  یُس دمشقس مَنٛز روزان اوس، وونُن،\n19.\\tمیہ تہٕ تۅہہِ درمِیان چُھہ اکھ اتحاد، {تہٕ} میٲنس مٲلس تہٕ تہندس مٲلس درمِیان چُھہ: وچھ مے سوزمُت ژے رۄپہٕ تہٕ سۄنہٕ ہُند تحفہٕ۔ یِو تہٕ پَنُن اتحاد پھُٹرٲوِو اِسرٲیلِکِس بادشاہس سٍتـ̡ یُتھ سُہ میانہِ نِش نیرِ۔ {روانہ: ہیب۔ ہیوٚر گژھو}\n20. چنانچہ بنہاداد بوز بادشاہ آسا سٕندِس سٍتـ̡ تہٕ سوٗزِن تِمن فوجن ہٕندِس کپتان، یِم أمِس اسرٲیلِس خٕلاف ٲسۍ، تہٕ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ سٍتـ̡ یِمن ہٕندِس سٍتـ̡\n21.\\tتہ سپد ییلہ بعشہِ یہ بوز زِ تم تروو رامہ چہ عمارت ترٲوتھ ترزاہس منز بسان۔\n22.\\tبادشاہ آساہن کٔر سٲرۍسٕے یہوداہ سٕندِس سٍتـ̡ اعلان ۔ کُنہِ تہِ اوس نہٕ استثنیٰ دِنہٕ آمُت: تہٕ تِمو نِش رمہٕ سٕندِ کٔنہِ تہٕ تِمن ہٕنزِ لٔکٕر، یِمو سٍتـ̡ بَعشہٕ سٍتـ̡ بٔنـ̡ بٔنـ̡ ۔ تہٕ بادشاہ آساہن بنوو تمن سٍتۍ بنیامین تہٕ مزپاہُک گیبا۔ {مستثنیٰ: ہیب۔ مُفت}\n23.\\tآسا سٕندِ باقٕے سارِنٕے اعمال، تہٕ تٔمۍ سٕندِ سارِنٕے طاقتہٕ تہٕ یِم شہر یِم تٔمۍ بنٲومٕتۍ، کیا تِم چھِنہٕ یہوداہ کِس بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟ توتہِ اوس بُزرگ وٲنسہِ منز تس کھۅرن منز بیمار۔\n24.\\tتہٕ آسا گۆو پننین مٲلن سٍتـ̡ شوٚنگ، تہٕ سُہ آو پننین مٲلن سٍتـ̡ دفن کرنہٕ، تہٕ تٔمۍ سٕندِس نیچوِس کٔر تٔمۍ سٕندِ بدلہٕ بادشاہت۔ {یہوشافعت: Gr. Josaphat}\n25.\\tتہٕ یربعام سٕندِ نیچوِس ندابن کٔر یہوداہ کِس بادشاہ آسا سٕندِس دٔیمِس ؤریس مَنٛز اسرٲیلِس پیٹھ حکوٗمت شروع تہٕ دۄن ؤرین کٔرٕن اسرٲیلِس پیٹھ حکومت۔ {شروع...: ہیب۔ راج کٔر}\n26. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز بُر، تہٕ پَنٕنِس مٲلہِ سٕنزِ وتہِ پٲٹھۍ، تہٕ پنہٕ نِس گۅنہاہس مَنٛز پٔکِتھ ییمہِ سٍتـ̡ تٔمۍ اسرٲیلِس گۅناہ کٔرِ۔\n27.\\tتہٕ احیجہ سٕندِس نیچوِس بعشاہن کٔر أمِس خلاف سٲزِش۔ تہٕ باشاہن دِژ أمِس گِبتھنس مَنٛز، یُس {فلسطینیَن} سٍتـ̡ اوس۔ تکیازِ نداب تہٕ سارِنٕے اسرٲیلن کوٚر گبتھنس محاصرٕ۔\n28.\\tیہوداہ کِس بادشاہ آسا سٕندِس تریمہِ ؤریس منز تہِ کٔر بعشاہن سُہ مٲرِتھ تہٕ کورُن أمِس بدلہٕ حکوٗمت۔\n29. تہٕ سپُد یہِ سپدُن، ییلہ تٔمۍ بادشاہت کٔر، {یہ} تٔمۍ کٔر یربعام سٕندِس سارِنٕے گرس مار۔ تٔمۍ ترٲو نہٕ یربعامس نِش کانہہ تہِ یُس شاہ دِیُت، یوتام نہٕ تٔمۍ سُہ تباہ کرُن، یُس تٔمۍ پننِس خادم احیجہ شیلونایٹ سٕندِ طرفہٕ کٔرِتھ:\n30. یِمو سٍتـ̡ یێمہِ سٍتـ̡ تٔمۍ گۅناہ کٔر، تہٕ یُس تٔمۍ اسرٲیلـ̡ خدایہِ سٍتـ̡ شرارت دِنہٕ سٍتـ̡ دِژمُت۔\n31.\\tوۅنۍ چھہ نداب سٕندِ باقی اعمال تہٕ یُس تٔمۍ کٔرۍ، کیا تِم چھِنہٕ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابہِ منز لیکھنہٕ آمٕتۍ؟\n32.\\tتہٕ اوس آسا تہٕ اسرائیلٕکۍ بادشاہ بعشہٕ درمِیان سارِنٕے دۅہن جنگ سپدان۔\n33.\\tآسا سٕندِس تریمہِ ؤریس مَنٛز کٔر یہوُہِ تہٕ ژۅوُہن ؤرین سارنٕے اسرٲیلِس پیٹھ حکومتہٕ کرنہٕ خٲطرٕ۔\n34. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس مَنٛز بُد کٔرِتھ، تہٕ پَنٕنِس گۅنہٕ سٍتـ̡ پٔکِتھ پٔکِتھ یێمہِ سٍتـ̡ تٔمۍ اسرٲیلِس گۅناہ کٔرِ۔","1. اَمہِ پَتہٕ ووت خداوند سُند کلام حنانی سٕندِس نیچوِس یہوَس مَنٛز بَعشہِ خٕلاف وَنُن،\n2. یێلہِ بہٕ ژے ژے میژِ منزٕ تھوٚد کٔرِتھ تہٕ بنووُکھ ژے پننین لوکن ہٕندِس اسرٲیلس پیٹھ شہزادہ۔ تہٕ ژے چُھکھ یربعام کِس وتہِ پٔکِتھ، تہٕ میانین لوکن ہٕندِس اسرٲیلِس گۅنہٕ سٍتـ̡ گۅنہٕ سٍتـ̡ شرارت کرنہٕ خٲطرٕ بنوومُت۔\n3.\\tوچھو بہٕ نِش بہ تہ تٔمۍ سٕندِس گرس ہٕنز اولاد۔ تہٕ بناوِ تُہند گرٕ نیبت سٕندِس نیچو یربعام سٕندِس گرس ہیوٗ ۔\n4.\\tیُس شہرس منز بعشہِ سٍتـ̡ مرُن چُھہ سُہ گژھہِ ہونۍ کھٮ۪ن۔ تہٕ یُس کھہَن مَنٛز مرُن سُہ گژھِ ہوہٕکۍ جاناوار کھٮ۪ن۔\n5.\\tوۅنۍ چھہ بعشہِ سٕندِ باقٕے اعمال تہٕ تٔمۍ سُند کیا کورمُت تہٕ تٔمۍ سٕندِس طاقتس چھُنہٕ یِم اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n6.\\tیِتھ کٔر بعشہٕ پننِس مٲلِس سٍتـ̡ شوٚنگتھ تہٕ ترزاہس مَنٛز دفن کرنہٕ۔\n7.\\tتہٕ حضرت حنانی سٕندِس نیچو نبی یہو سٕندِ اتھہٕ سٍتـ̡ آو خداوند سُند کلام بعشہِ خلاف تہٕ تٔمۍ سٕندِس گرس خٕلاف، یُس تٔمۍ خداوند سٕندِس نظرس مَنٛز کٔر، یُس تٔمِس اَتھٕ کامہِ سٍتـ̡ شرارت دِنہٕ سٍتـ̡ یێلہِ یێربعام سٕندِس گرس ہٕندۍ پٲٹھۍ۔ تہٕ امہ مۅکھہ زِ تٔمۍ کوٚر سُہ مٲرِتھ۔\n8.\\tآسا سٕندِس وُہمہِ تہٕ شُہمہِ ؤریس مَنٛز کٔر یہوداہُک بادشاہ ایلاہ سٕندِس نیچوِس ترزاہس مَنٛز اسرٲیلِس پیٹھ حکومت کرنُک آغاز۔\n9.\\tتہٕ تٔمۍ سٕندِس نٮ۪صف رتھَن ہُند کپتان زِمری کٔر أمِس خلاف سٲزِش، یِتھ کٔنۍ سُہ ترزاہس مَنٛز اوس، تِرزاہَس مَنٛز اوسُس اَرزہ سٕندِس گرس مَنٛز شرابَس مَنٛز شراب۔ {سٹیورڈ...: ہیب۔ یُس ختم اوس گومُت}\n10.\\tتہٕ زِمری ژاو أمِس تہٕ مارُن یہوداہ کِس بادشاہ آسا سٕندِس وُہمہِ تہٕ سٔتِمِس ؤریس مَنٛز، تہٕ کورُن أمِس بدلہٕ حکوٗمت۔\n11.\\tتہٕ سپُد ییلہ تٔمۍ بادشاہی ہیوٚت، یُتھ سُہ پننِس تختس پیٹھ بِہتھ، تٔمۍ مارۍ بعشہٕ سُند سورُے گرٕ: تٔمۍ تروو نہٕ تس دیوارس سٍتـ̡ رٔٹِتھ تہٕ نہ پننین یارن ہُند۔ {نہ تہِ...: یا تٔمۍ سٕندۍ رشتہٕ دار تہٕ تٔمۍ سٕندۍ یار}\n12.\\tیِتھٕ پٲٹھۍ کٔر زِمری یُس خداوند سٕندِ کلامَس مُطٲبق بعشہٕ سٕندِس سٍتـ̡ کٔرِتھ تباہ۔ اتھہٕ سٍتۍ }\n13. بعشہٕ سٕندِس سارِنٕے گۅنہٕ خٲطرٕ، تہٕ تٔمۍ سٕندِس نیچوِس ایلاہ سٕندِس گۅنہٕ سٍتـ̡ یِمو گۅنہٕ کٔرِتھ تہٕ یێمہِ سٍتـ̡ تِمو اسرٲیلِس پٲٹھـ̡ گۅناہ کٔرِتھ، یێمہِ سٍتـ̡ تِمو اسرٲیلِس خدایہِ سٍتـ̡ تِمن ہٕندِس باطل سٍتـ̡ شرارت کرنہٕ خٲطرٕ اِشارٕ دِنہٕ آمُت۔\n14.\\tوۅنۍ چھہ ایلا سٕندِ باقی اعمال تہٕ یُس تٔمۍ کٔرۍ، کیا تم چھہِ نہٕ اسرائیلکۍ بادشاہن ہٕنزِ تواریخ کتابہِ منز لیکھنہٕ آمٕتۍ؟\n15.\\tآسا سٕندِس وُہمہِ تہٕ سٔتِمِس ؤریس مَنٛز کٔر زِمری ترزاہس مَنٛز ستن دۅہن حکومت۔ تہٕ لوکو کٔر گِبتھنس خلاف ڈیرٕ ترٲومُت، یُس فلسطینن سٍتـ̡ اوس۔\n16.\\tتہٕ یِمو لُکہٕ یِمو ڈیرٕ ترٲوِتھ بٔنِتھ بوز زِمریَن کٔر سٲزِش تہٕ کوٚرُن بادشاہ تہِ مارُن، اَمہِ مۄکھٕ بَنوو سارِوٕے اِسرٲیلَن ہٕندِس لشکرُک کپتان عمری تمہِ دۅہہ خٲمس مَنٛز اِسرٲیلُک بادشاہ۔\n17.\\tتہٕ عمری ووت گِبتھن پیٹھٕ تہٕ سارِنٕے اسرٲیلِس سٍتـ̡ تہٕ تِمو کٔر ترزاہُک محاصرٕ۔\n18.\\tتہٕ سپُد یہِ سپدُن، ییٚلہِ زِمری یَن وُچھ زِ شہر آو قبضہٕ کرنہٕ، سُہ گوٚو بادشاہ سٕندِس محلس مَنٛز، تہٕ زٲلِن بادشاہ سُند مکانہٕ نارٕ سٍتۍ، تہٕ موٗدُن،\n19. تٔمۍ سٕندِس گناہَن خٲطرٕ یُس تٔمۍ خداوند سٕندِس نظرس مَنٛز بد کار کرنس مَنٛز، یربعام سٕنزِ وتہِ پَکُن پَکُن تہٕ تٔمۍ سٕندِس گۅناہ سٍتـ̡ یُس تٔمِس گۅنہٕ سٍتـ̡ کٔر، یُس تٔمۍ کٔر اسرٲیلِس گۅناہ کرنہٕ خٲطرٕ۔\n20.\\tوۅنۍ زِمری سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕنز غداری یُس تٔمۍ کٔر، کیا تِم چھِنہٕ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابس مَنٛز لیکھنہٕ آمٕتۍ؟\n21. اَمہِ پَتہٕ گٔیہِ اِسرٲیلٕکۍ لُکھ دۄن حصن مَنٛز تقسیٖم کرنہٕ: نٮ۪صٕف لُکھ گِناتھ سٕندِس نیچوِس تِبنی سٕندِس بادشاہ بناونہٕ خٲطرٕ۔ تہٕ نٮ۪صف اوس عمری پتہٕ۔\n22.\\tمگر عمری سٕندِس نیچوِس تِبنی سٕندِس پٲٹھـ̡ لُکن ہٕندِس خٕلاف گٔیہِ تِمن لُکن ہٕندِس خٕلافس سٍتـ̡ یِمو تِمن ہٕندِس سٍتـ̡ تِمن ہٕندِس سٍتـ̡ گٔیہِ تِمن ہٕندِس سٍتـ̡ تِمن ہٕندِ\n23.\\tیہوداہ کِس بادشاہ آسا سٕندِس اکترٕہ ؤریس مَنٛز کٔر عمری اسرٲیلس پیٹھ حکومت کرنہٕ خٲطرٕ، باہ ؤری: شیہ ؤری کٔر تِرزاہَس مَنٛز حکومت۔\n24.\\tتہٕ تٔمۍ ہیوٚت شیمیرُک بالہٕ سامریہ رۄپہٕ ہٕندِس دۄن ٹیلنٹَن مَنٛز تہٕ بالہٕ پٲٹھۍبنوُن تہٕ تٔمِس شہرُک ناو تھووُن یُس تٔمۍ سامریہُک مٲلِک شیمر سٕندِس ناوس پیٹھ بنوومُت اوس۔ {سامریہ: ہیب۔ شومیرون}\n25.\\tمگر عمری ین کٔر خداوند سٕندِس نظرِ منز بدکار تہٕ کٔرٕن أمِس برونہہ کُن سارِوٕے کھۄتہٕ بدتر کٔرِتھ۔\n26. تکیازِ سُہ پوٚک نیبت سٕندِس نیچو یربعام سٕندِس سارِنٕے وتہِ منز، تہٕ پننِس گۅنہٕ سٍتـ̡ یێمہِ سٍتـ̡ تٔمِس سٍتـ̡ یێمہِ سٍتـ̡ تٔمِس اسرٲیلِس گۅناہ کرنہٕ آمُت، تہٕ یێمہِ سٍتـ̡ تِمن ہٕندِس خدایہِ سٍتـ̡ تِمن ہٕندِس باطلس سٍتـ̡ شرارت کرنہ\n27.\\tوۅنۍ یُس عمری سٕندِ باقی اعمال یُس تٔمۍ کٔرۍ، تہٕ تٔمۍ سٕنز طاقت یُس تٔمۍ ہٲومُت، کیا تِم چھِنہٕ اسرٲیلِکۍ بادشاہن ہٕندِس تواریخ کِس کتابہِ منز لیکھنہٕ آمٕتۍ؟\n28.\\tیێلہِ اوس عمری پننین مٲلن سٍتـ̡ شوٚنگتھ سامریاہس مَنٛز دفن کرنہٕ آمُت۔\n29.\\tتہٕ آسا سٕندِس ٲٹھہمہِ ؤریس مَنٛز کٔر یہوداہ کِس بادشاہ عمری سُند نیچو احاب، اسرٲیلِس پیٹھ حکومت کرنہٕ خٲطرٕ، تہٕ عمری سُند نیچو احاب کٔر سامریہ مَنٛز زُوُہن وُہن ؤرین اسرٲیلس پیٹھ حکومت۔\n30.\\tتہٕ عمری سُند نیچو احاب کٔر خداوند سٕندِس نظرِ منز سارِوٕے کھۄتہٕ زیادٕ بُرٲے کٔرِتھ۔\n31.\\tتہٕ سپُد یہِ زَن تٔمِس خٲطرٕ نیبت سٕندِس نیچوِس یربعام سٕندِس گۅنہن منز پکُن ہلکہٕ کتھ آسہِ، زِ تٔمۍ نیو زیدونین ہٕندِس بادشاہ اِتھبعل سٕنزِ کورِ یِزبیل سٕنزِ خانٛدارِنہِ سٍتـ̡ تہٕ گٔیہِ بعلٕچ خدمت تہٕ کٔرٕن أمِس پوٗزا کرنہٕ۔ {یتھہ پاٹھۍ...: ہیب۔ یہ اوسا ہلکہٕ چیز وغیرہ}\n32.\\tتہٕ تٔمۍ بنوو بعل سٕندِس گرس مَنٛز بعل سٕندِ خٲطرٕ اکھ قربان گاہ، یُس تٔمۍ سامریاہس مَنٛز بنوومُت اوس۔\n33.\\tتہٕ احابن بنوو اکھ باغ۔ تہٕ احابن کٔر اسرٲیلِک خداوند خداہس پانس برونہہ کنہِ موجود سارِنٕے بادشاہن کھوتہٕ زیادٕ شرارتس منز اشتعال دِنہٕ خٲطرٕ۔\n34.\\tپننِس زمانس مَنٛز کٔر ہیلن بیت القدس یریحا بنومُت، تٔمۍ ترٲو پننِس گۄڈنِکِس نیٚچوِس ابیرامس مَنٛز اَمیُک بُنیاد تہٕ خداوند سٕندِ کلامٕ مُطٲبق کٔرٕن پننِس لۄکٹِس نیچوِس سیگوبس مَنٛز اَمیُک دروازٕ قٲیم، یُس تٔمۍ نون سٕندِ نیچوِس یشوع سٕندِ دٔسۍ کتھ کٔر۔","1. تہٕ ایلیاہ تِشبیت، یُس گلعاد کین بسکینن منز اوس، ووٚن احابس زِ یێلہِ چُھہ اسرٲیلُک خداوند روزان، یێمِس برونہہ کُن بہٕ کھڑا چُھس، یێمہِ ؤرین منز آسہِ نہٕ شبنم تہٕ نہ روٗد، مگر میانہِ کلامٕ مطٲبق۔ {ایلیاہ: ہیب۔ الیجاہو: Gr. Elias}\n2. تہٕ خداوند سُند کلام آو أمِس نِش وَننہٕ،\n3.\\tژیہ نیرِو تہٕ مشرقس کُن پھیُرِتھ تہٕ پان ژٔلِتھ کٔرِتھ یُس اردنس برونہہ کُن چھُ۔\n4. تہٕ یہِ گژھہِ یہِ زِ ژے چُھہ نالہٕ سٍتـ̡ چُھہ؛ تہٕ مے چُھس کۅکُن حکم دِژمُت زِ تتہِ دِیہِ ژےٚ کھٮ۪نہٕ۔\n5.\\tیێلہِ گۆو سُہ تہٕ کٔرُن خداوند سٕندِ کلامَس مُطٲبِق، تکیازِ سُہ گۆو تہٕ بٔنِتھ کٔرِتھ نالہِ نِش روزُن، یعنی اردنس برونہہ کُن۔\n6.\\tتہٕ کۅکر دِژ تس صبحس روٹی تہٕ ماز، تہٕ شامس روٹی تہٕ ماز۔ تہٕ تٔمۍ چُھ نالہٕ چُھ۔\n7.\\tتہٕ کینژس کالس پَتہٕ گوو یہ نالہٕ خشک تکیازِ زمینس منز اوس نہٕ کانہہ روٗد پیوٚومُت۔ {پتہٕ...: ہیب۔ دۅہن ہندِس ٲخرس پیٹھ}\n8. تہٕ خداوند سُند کلام آو أمِس نِش،\n9.\\tوۅتھٕ وُتھ، ژے گژھ زرفتھس کُن، یُس زِدونس سٍتـ̡ چُھ، تہٕ اتہِ روزُن: وچھ میہ چُھہ تتہِ أکِس بیواہ زنانہِ ہُند حُکُم دِژمُت زِ سُہ چُھہ ژے رژھراونہٕ خٲطرٕ۔ {زرفتھ: Gr. Sarepta}\n10.\\tتہٕ ووت سُہ ووٚتھ تہٕ زرفتھ کُن۔ تہٕ ییلہ سُہ شہر کس دروازس پیٹھ ووت، وُچھ بیواہ زنانہٕ ٲس تتہِ لورِ جمع کٔرتھ، تہٕ تٔمۍ ووٚن أمِس بُلاونہٕ تہٕ وونُن، مے أنِن، بہٕ چھُس ژےٚ أکِس بانس منٛز رژھ رژھ آب، تاکہ بہٕ چیٚنہٕ۔\n11.\\tییلہ سۅ اننہِ ٲس تٔمۍ أمِس بُلاونہٕ تہٕ وونُن، بہٕ اَنُن تہٕ دُعا کٔرِتھ اَنُن تہٕ دُعا کٔرِتھ اَنُن۔\n12. تہٕ تٔمۍ ووٚن، {یُتھ} خداوند تُہند خدا زندٕ چُھ، مےٚ چُھ نہٕ کیک، بلکہ چُھس أکِس بیرلس مَنٛز اکھ مُٹھہٕ کھٮ۪ن، تہٕ صلیبس مَنٛز تھوڑا تیٖل: تہٕ وُچھ، بہٕ چُھس زٕ لورِ جمع کٔرِتھ، یُتھ بہٕ اژِتھ پانس تہٕ پننِس نیچوِس خٲطرٕ لاگُن، یُتھ أسۍ یہ کھٮ۪تھ تہٕ مرُن۔\n13.\\tتہٕ ایلیاہ ہن ووٚن أمِس نہٕ خوف۔ گژھ {تہٕ} یُتھ ژے ووٚنمُت چُھ، مگر مے بناو گۅڈٕ اَمہ سٍتۍ اکھ لۄکُٹ کیک، تہٕ اَنِن میہ نِش، تہٕ پتہٕ بناوُن پانس تہٕ پننِس نیچوِس خٲطرٕ۔\n14. یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خدایہِ فرماوان زِ کھٮ۪نُک بیرل گژھِ نہٕ ضایع تہٕ نہ گژھِ تیلُک کرٛاوُن، یوتام نہٕ خداوند زمینس پیٹھ روٗد وسان۔ {سوزُن: ہیب۔ دِیُو}\n15.\\tتہٕ سۅ گٔیہِ تہٕ ایلیاہ سٕندِ قولہٕ مُطٲبق کٔرٕن تہٕ سُہ تہٕ تٔمۍ سٕندِس گرس کھیوٚو {واریہ} دۄہ۔ {واریاہ ...: یا، پورٕ ؤری}\n16.\\t{تہٕ} کھٮ۪نُک بیرل گۆو نہٕ ضایع، تہٕ نہ ہیوٚک تیلُک کُرُن ناکام، یُس تٔمۍ ایلیاہ سٕندِ کلامَس مُطٲبق کٔرِتھ۔ {by: Heb. اتھہٕ سٍتۍ }\n17.\\tتہٕ یِمو پَتہٕ سپُد یہِ زِ زنانہِ ہُند نیچو، یُس گرٕچ مالکن اوس، بیمار گوو۔ تہٕ تٔمۍ سٕنٛز بٮ۪مارِ ٲس تیوٗت دَگ زِ أمِس اوس نہٕ شاہ باقٕے۔\n18.\\tتہٕ تٔمۍ ووٚن ایلیاہ ہس سٍتـ̡ ، اے خدایہِ سٕندِس انسانس سٍتـ̡ کیا چُھہ میہ سٍتـ̡ کیا ژٕ چُھکھ میانہِ نِش میون گۅناہ یاد کرنہٕ خٲطرٕ تہٕ میون نیچو مارنہٕ خٲطرٕ آمُت؟\n19. تہٕ تٔمۍ ووٚن أمِس پنُن نیچو دِیُن۔ تہٕ تٔمۍ کوٚڈ سُہ پننہِ چھۅکہٕ منزٕ نیبر تہٕ نِن أکِس تھزرس منز، ییتہ سُہ روزان اوس، تہٕ لوٚگُن پننِس بسترس پیٹھ۔\n20.\\tتہٕ تٔمۍ کٔر خداہس نِش فریاد تہٕ وونُن، اے خدایہ، کیا ژے چھُکھ تٔمِس بیواہ سٍتـ̡ یٔمِس سٍتـ̡ بہٕ روزان اوس، تٔمۍ سُند نیچو مارِتھ بُرٕ ہٲومُت؟\n21.\\tتہٕ تٔمۍ کٔر شُرِس پیٹھ تریہ لٹہِ پان پھِرِتھ، تہٕ وونُن خدایہِ خدایہ، بہٕ چُھس ژے دُعا کران زِ أمِس شُرۍ سُند روح گژھہِ دُبارٕ تس مَنٛز۔ {پھیلٲوتھ: ہیب۔ پیمائش} {into...: Heb. تٔمۍ سٕنٛدس اندرونی حصن منٛز}\n22. تہٕ خداوند بوز ایلیاہ سٕنز آواز۔ تہٕ شُرۍ سُند روح آو أمِس منز دُبارٕ تہٕ سُہ گوو زندٕ۔\n23.\\tتہٕ ایلیاہ ہن نِیوو شُر، تہٕ أنِن سُہ خانہٕ منزٕ نٮ۪بر گرس منز، تہٕ دیتُن پننہِ ماجہِ نِش۔ تہٕ ایلیاہ ہن ووٚن، وُچھ، تُہند نیچو چُھ زندٕ۔\n24. تہٕ زنانہِ ووٚن ایلیاہ ہس زِ وۅنۍ چُھہ میہ پتاہ زِ تہٕ چُھہ خدایہ سُند کلام تہٕ تُہندِ ٲسس مَنٛز خداوند سُند کلام {چُھ} صحیح۔","1. تہٕ واریہن دۅہن پَتہٕ سپُد خداوند سُند کلام تریمہِ ؤریس مَنٛز ایلیاہ ہس نِش ووتُن، یُس وَنُن زِ گژھ پنُن پان اہابس نِش ہٲوِو۔ تہٕ بہٕ تراوٕ زمینس پیٹھ رود۔\n2.\\tتہٕ ایلیاہ گۆو پنُن پان احابس نِش ہاونہِ۔ تہٕ سامریاہس منز اوس اکھ شدید قحط۔\n3.\\tتہٕ احابن ووٚن عوبدیہ یُس {پننِس} گرُک گورنر۔ (وۅنۍ اوس عبادیہ خداونس سٍتـ̡ سٮ۪ٹھاہ کھوژان: {Obadiah: Heb. Obadiahu} {گورنر...: Heb. تٔمۍ سٕنٛدس گھرس پیٹھ}\n4.\\tیێلہِ یِزبیلن خداوند سٕندِ پیغمبرن ژٔٹِتھ ژٔٹِتھ ، عوبدیاہن نِش ہتھ نبی تہٕ پانژاہ گۅپھِ منز ژوُرِتھ تہٕ دِژُن تِمن روٹی تہٕ آبہٕ دِنہٕ۔ {Jezebel: Heb. Izebel}\n5.\\tتہٕ احابن ووٚن عبدیاہس زِ زمینس منز، آبہٕ کین سارنٕے چشمن تہٕ سارنٕے نالن کُن، شاید گژھ اسہِ گُرِ تہٕ خچر زِندٕ بچاونہٕ خٲطرٕ گاسہٕ ژھٲنڈِتھ، یُتھ زِ أسۍ گژھِ نہٕ سارِنٕے درندٕ رٲوِتھ۔ {یہ...: ہیب۔ زِ أسۍ ژٔٹۍ نہٕ درندَن نِش پنُن پان ژٹنہٕ}\n6. تہٕ یِمو کٔر زمین پانس مَنٛز تقسیم کرنہٕ خٲطرٕ، اَہاب پوٚک پانَے اَکہِ وتہِ تہٕ عبَبیاہ پَکہٕ پانَے أکِس وَتہِ۔\n7.\\tییلہ عبادیہ وتہِ وتہِ اوس، وُچھ ایلیاہ أمِس سمکھیو، تہٕ سُہ اوس أمِس زانان تہٕ پیوٚو بُتھِس پیٹھ تہٕ وونُن، {کیا تُہہ} چھُکھ میون آقا ایلیاہ ؟\n8.\\tتہٕ تٔمۍ دیُت أمِس جواب، بہٕ چُھس: گژھ پننِس مٲلکَس وَنُن، وُچھ، ایلیاہ {چُھ}۔\n9.\\tتہٕ ووٚن میہ کیا گۅناہ کورمُت زِ ژے کٔرِکھ پنُن خادم اہاب سٕندِس اتھس منز تہٕ مے مارنہٕ خٲطرٕ۔\n10. یێلہِ چُھہ تُہُند خدا زندٕ چُھ، تێلہِ چُھہ نہٕ کانہہ قوم تہٕ بادشاہی، یێتہِ نہٕ میانہِ آقا چُھہ تۅہہِ ژھانڈنہٕ خٲطرٕ سوزمُت، تہٕ ییلہ تمو وۆن، {سُہ چُھ} نہٕ تتہِ۔ تٔمۍ کٔر بادشٲہی تہٕ قومُک حلف، یُس نہٕ تِمو لٔبِتھ چھُ۔\n11.\\tتہٕ وُنہِ چُھہ وَنُن، گژھِو پننِس مٲلکَس وَنُن، وُچھِو، ایلیاہ {چُھہ یِتھ}۔\n12. تہٕ یێلہِ بہٕ ژے نِش نیرِ، یێلہِ یێلہِ بہٕ ژے نِش نیرِ، یێلہِ نہٕ بہٕ پتاہ چُھہ، یێلہِ تہٕ یێلہِ نہٕ بہٕ پتاہ آسہِ۔ تہٕ {تو} ییلہ بہٕ آۓ تہٕ احابس وَنُن، تہٕ سُہ چُھ نہٕ ژےٚ لٔبِتھ، سُہ کرِ مے مٲرِتھ، مگر بہٕ چُھس تُہند خادم پننہِ جوانی پیٹھے خداوند سُند خوف تھاوان۔\n13.\\tکیا یہ وننہ آمت زِ میہ کیا کوٚر یێلہِ ییزبیلن رب سٕندِ پیغمبرن مار، کِتھہ کٔنۍ کٔر میہ رب سٕندٮ۪ن پیغمبرن ہٕندِ ہتھ نفر أکِس غارس مَنٛز ژوُر، تہٕ تِمن روٹی تہٕ آبہٕ دِژمٕتۍ۔\n14. تہٕ وُنہِ چُھہ ژے وَنُن، گژھ پننِس آقا سٍتـ̡ وَنُن، وُچھ ایلیاہ {چُھہ} تہٕ سُہ کرِ مے مٲرِتھ۔\n15. تہٕ ایلیاہ ہن ووٚن، {یێلہِ} لشکرن ہُند رب زندٕ چُھ، یێمِس برونہہ کُن بہٕ کھڑا چُھس، بہٕ کَرٕ یٔژ پٲٹھـ̡ تس برونہہ کُن ہاونہٕ۔\n16.\\tتہ عوبیاہ گۆو احابس سمکھنہِ تہ وونُن تہ اہاب گۆو ایلیاہ سٍتـ̡ سمکھنہِ۔\n17.\\tتہٕ ییلہ احابن ایلیاہ وُچھمُت، اہابن ووٚن أمِس زِ کیا تُہۍ چھُکھ یُس اسرٲیلِس پریشان کران چھُ؟\n18.\\tتہٕ تٔمۍ دیُت جواب، مے چُھہ نہٕ اسرٲیلِس پریشان کٔرمٕژ۔ مگر تۅہہِ تہٕ پننِس مٲلہِ سٕندِس گرس سٍتـ̡ چُھہ خداوند سٕندِ حُکمن ترٲومُت، تہٕ توے چُھکھ بعلیمٕچ پیروی کٔرمٕژ۔\n19.\\tتێلہِ سوز سارِنٕے اسرٲیلِس میہ نِش کارملس کُن تہٕ بعلٕکۍ پیامبر ژور ہتھ تہٕ ژور ہتھ تہٕ باغن ہٕندِ پیغمبرن ہٕندِس ژۅن ہتھ پیغمبرن یِم یِزبیل سٕندِس دسترس پیٹھ کھیوان چھِ۔\n20. یێمہِ سٍتـ̡ سوٗزُن اَحابَن سارِنٕے بنی اِسرٲیلِس نِش تہٕ کٔرِن پیغمبرن سٍتـ̡ کارمل کِس پہاڑس مَنٛز جمع کرنہٕ۔\n21.\\tتہٕ ایلیاہ آو سارِنٕے لُکن نِش تہٕ وونُن، دۄن راے درمِیان کوتاہ کالس رُکٲوِو؟ اگر خداوند خدا آسہِ، تٔمِس کٔرِو تٔمِس پٲرو۔ تہٕ لوٗکن دیت نہٕ أمِس کانٛہہ تہِ لفظُک جواب۔ {رائے: یا، خیالات}\n22.\\tتێلہِ وۆن ایلیاہ ہن لُکن سٍتـ̡، بہٕ چُھس صرف خداوند سُند پیغمبَر روزان۔ مگر بعل سٕندِ پیغمبرن چھِ ژور ہتھ پنژاہ نفر۔\n23.\\tتَمہِ کِنۍ دِیُن اسہِ زٕ بیل۔ تہٕ تِم ژٲرِن پانس خٲطرٕ اکھ بیل تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ لٔکرِ پیٹھ تھووُن، تہٕ دِیہٕ نہٕ نار {بۄنہٕ}: تہٕ بہٕ دِیہٕ بییِس بیلس پَلو، تہٕ لٔکرِ پیٹھ تھووُن، تہٕ دِیہٕ نہٕ نار {بۄنہٕ}۔\n24. تہٕ پَنٕنـ̡ خداہٕ سٕندِس ناوٕ سٍتـ̡ بُلناوُن، تہٕ یُس خدا نارٕ سٍتـ̡ جواب دِیہ، سُہ گژھہِ خدا۔ تہٕ سارِوٕے لوٗکو دِژ جواب تہٕ وونُن، یہِ چُھ جان پٲٹھۍ۔ {یہٕ چُھ...: ہیب۔ لفظ چُھ اصل}\n25.\\tتہٕ ایلیاہ ہن ووٚن بعل کین پیغمبرن زِ پانس خٲطرٕ اکھ بیل ژٲرِو، تہٕ گۅڈٕ لٲگِو پَلو۔ تکیازِ تم چھہِ واریاہ چھہِ؛ تہٕ پَنٕنٮ۪ن دیوتاہن ہُند ناو پَنُن، مگر نار تراوُن نہٕ۔\n26.\\tتہٕ تِمو رٔٹِتھ یُس تِمن دِنہٕ آمُت اوس، تہٕ تِمو لٲگِتھ صبحٲے پیٹھٕ دوپہرس تام بعل سُند ناو وُچھِتھ وَنُن اے بعل، بوزو۔ مگر {اتہِ} ٲس نہ کانہہ آواز، نہ اوس کانہہ جواب دِوان۔ تہٕ تِمو وۄٹھ دِژ قربان گاہس پیٹھ یُس بناونہٕ اوس آمُت۔ {بوزو: یا، جواب} {جواب: یا، بوز} {وۄٹھ دِژ...: یا، قربان گاہس پیٹھ ہیوٚر بۄن وۄٹھ دِژ}\n27.\\tتہٕ دُپہرَس آو یہِ سپدِتھ زِ ایلیاہ ہن کٔر تِمن ٹھٹھہٕ تہٕ وونُن، بَڑِ پٲٹھۍ، کیازِ سُہ چُھ خدا۔ یا تہ چھہ سہ کتھ کران، نتہ چھہ سہ پیچھا کران، نتہ چھہ سہ سفرس منز، {یا} شاید سہ شوٚنگتھ تہ بیدار گژھہِ آسن۔ {بَڑِ پٲٹھۍ: ہیب۔ اَکھ بٔڈ آوازٕ سٍت} {سُہ چُھ کتھ کران: یا، سُہ چُھ مراقبہٕ کران} {چُھ تعاقب کران: حب۔ ہیتھ اکھ تعاقب}\n28.\\tتہٕ تِمو کٔر بَڑِ کٔرِتھ، تہٕ ژٔٹِکھ پنُن پان چُرِ تہٕ لُکہٕ سٍتـ̡ ژٹنہٕ، یوٚت تام تِمن پیٹھ خوُن ووٚتھ دِنہٕ۔ {خون...: ہیب۔ تمن پیٹھ تروو خون}\n29.\\tتہٕ سپُد یہِ سپُد، ییلہ دوپہر پوٚت گوو، تہٕ تِمو کٔر {شامٕچ قربانی} ہٕندِس وقتس تام پیشن گویی زِ {شام} قربانی دِنہٕ کِس وقتس تام ٲس نہٕ کانہہ آواز، تہٕ نہ اوس کانہہ جواب دِنہٕ خٲطرٕ، تہٕ نہ اوس کانہہ تہِ یُس خیال تھاوان اوس۔ {پیشکش: ہیب۔ اَتھ مَضموٗنَس مَنٛز چھُ یِمَن مَضموٗنَن ہُنٛد مَضموٗن مَضموٗن کَرنہ توجہ}\n30.\\tتہٕ ایلیاہ ہن ووٚن سارِنٕے لُکن زِ یِمو میہ نزدیک۔ تہٕ سٲری لُکھ آیہِ أمِس نزدیک۔ تہٕ تٔمۍ کٔر خداوند سٕنز قربان گاہ مرمت {یُس} پھُٹمُت۔\n31.\\tتہٕ ایلیاہ ہن رٔٹِتھ یعقوب سٕندٮ۪ن نیچوین ہٕندِس قبیلن ہٕندِ تعدادٕ مُطٲبق باہ کٔن، یِمن نِش خداوند سُند کلام آو تہٕ وونُن زِ اسرٲیل گژھہِ تُہند ناو آسُن:\n32. تہٕ کٔنِو سٍتـ̡ بنوو تٔمۍ خداوند سٕندِ ناوٕ سٍتـ̡ اکھ قربان گاہ: تہٕ تٔمۍ بنوو قربان گاہس اندۍ اندۍ اکھ خندق، یُس زٕ بٔڈ بیٲلۍ آسہِ۔\n33.\\tتہٕ تٔمۍ تھووُن لٔکرِ ترتیبہٕ، تہٕ ژٔٹِتھ لٔکرِ پیٹھ، تہٕ وونُن ژور بیرل آبہٕ سٍتـ̡ بٔرِتھ، تہٕ دزنہٕ آمٕژ قربانی تہٕ لٔکرِ پیٹھ۔\n34.\\tتہِ ووٚن دویم لٹہِ کرُن۔ تہٕ تِمو کوٚر دوٚیمہِ لَٹہِ {یہ}۔ تہٕ تٔمۍ ووٚن، ترٛیٚیِمہِ لَٹہِ کٔرِو یہِ۔ تہٕ تمو کوٚر تریمہِ لٹہِ {یہ}۔\n35.\\tتہٕ آب ووت قربان گاہس اندۍ اندۍ اندۍ پکھۍ۔ تہٕ أمۍ بٔرِتھ خندق تہِ آبہٕ سٍتۍ۔ {ران: ہیب۔ گٔیہِ}\n36.\\tتہٕ سپُد {شامٕچ قربانی دِنہٕ وِز} زِ ایلیاہ پیغمبر آو نزدیک، تہٕ وونُن، اے ابراہیم، اسحاق تہٕ اسرٲیلُک خدا، از گژھہِ یہ زان زِ ژٕ چُھہ اسرٲیلس مَنٛز خدا تہٕ بہٕ چُھس تُہند بندہ تہٕ {یہ} چُھس یِم سارِنٕے چیٖز تُہندِ کلامَس سٍتـ̡ کٔرمٕتـ̡۔\n37.\\tاے خداوند، بوزو مے بوزو، یێلہِ یێمہِ لُکھ گژھہِ پتاہ زِ تُہۍ چُھہ خداوند خدا، تہٕ {یہ} چُھہ تِہُند دِل دُبارٕ پھیُرُن۔\n38.\\tپَتہٕ پیوٚو خداوند سُند نار تہٕ دزمُت قربانی تہٕ لٔکرِ تہٕ کٔنہِ تہٕ گردِ تہٕ لوٚگ خندقس مَنٛز آب ژٹنہٕ۔\n39.\\tتہٕ ییلہ سارِوٕے لُکھ وُچھ، تِمو پٔرِتھ تہٕ وونُن، خدا، سُہ چُھ خدا۔ خدا، سُہ چُھ خدا۔\n40. تہٕ ایلیاہ ہن ووٚن تِمن نِش بعل سٕندِس پیغمبرن نِیو۔ تمن منز گژھہِ نہ کانہہ تہِ ژلُن۔ تہٕ تِمو نِیہِ تِم تہٕ ایلیاہ أنِن تِم کِشون کِس نالہِ کُن تہٕ تِم مٲرِتھ مٲرِتھ۔ {رٔٹِو: یا، رٔٹِو}\n41.\\tتہٕ ایلیاہ ہن ووٚن اہابس، وۅتھٕ کھیوٚن تہٕ پییُن۔ تکیازِ {اتہِ} چُھ رودٕچ کثرت ہٕنز آواز۔ {اکھ آواز...: یا، رودُک شور}\n42.\\tیێلہِ گۆو اہاب کھٮ۪نہٕ تہٕ چنہٕ خٲطرٕ۔ تہٕ ایلیاہ ووت کارمل کِس تھزرس تام۔ تہٕ تٔمۍ ترٛٲو پنُن پان زمینس پیٹھ، تہٕ تھووُن پنن بُتھ پننین کوٹھن منٛز،\n43.\\tتہٕ ووٚنُن پننِس خادمَس زِ وۅنۍ گژھ سمندرس کُن نظر۔ تہٕ سُہ ووت تھوٚد تہٕ وُچھُن تہٕ ووٚنُن، {اتہِ} چھُنہٕ کیٚنٛہہ۔ تہٕ تٔمۍ ووٚن، بیٚیہِ سَتھ لَٹہِ گژھ۔\n44.\\tتہٕ سٔتِمہِ لٹہِ سپُد یہِ وَنُن زِ وُچھِو سمندرٕ منزٕ اَکھ لۅکُٹ اوٚبر، یُس انسان سٕندِ اتھہٕ سٕندۍ پٲٹھۍ۔ تہٕ ووٚن، ہیوٚر گژھ اہابس وَنُن، تیار کرُن {پنُن رتھ} تہٕ بۄن وُن، یُتھ نہٕ روٗد رُکاونہٕ یُن۔ {تیار: حب۔ ٹای، یا، بِنڈ}\n45.\\tتہٕ اَتھ دوران سپد یہ زِ آسمانس اوس اوٚبرٕ تہٕ واو سٍتـ̡ سیاہ گومُت، تہٕ اَتہِ اوس واریاہ روٗد۔ تہٕ احاب ووت سوارِ تہٕ گوٚو یزریلس کُن۔\n46. تہٕ خداوند سُند اَتھٕ اوس ایلیاہ ہس پیٹھ۔ تہٕ تٔمۍ ژوٚل پنٕنۍ کمر رٔٹتھ تہٕ ژوٚل احابس برونہہ کُن یزریل کِس دروازس تام۔ {کُن...: ہیب۔ یوتام نہٕ ژے یزریل یِن}","1.\\tتہٕ احابن ووٚن یِزبیلس سُہ سورُے یُس ایلیاہ ہن کورمُت اوس، تہٕ کِتھہ پٲٹھـ̡ اوس تٔمۍ سارِنٕے پیغمبرن تلوار سٍتـ̡ مارمُت۔\n2. اَمہِ پَتہٕ سوُز یِزبیلَن ایلیاہ نِش اکھ قاصد تہٕ وونُن زِ یێلہِ دِیُت دیوتاہَن تہٕ یێلہِ بہٕ پگہہ یِمن منزٕ أکِس سٕنزِ زِنٛدگی ہٕندِس پٲٹھۍ۔\n3.\\tتہٕ ییلہ تٔمۍ وُچھ سُہ ووٚتھ، تہٕ ووت پننہ زندگی خٲطرٕ، تہٕ آو بیرشبع کُن، یُس یہوداہ سُند {چُھ} اوس، تہٕ ترووُن پنُن نوکر تتہِ۔\n4.\\tمگر سُہ گۆو پانہٕ أکِس دۅہُک سفر بیابانس مَنٛز، تہٕ آو تہٕ بیوٹھ أکِس جونیپر کُلِس تَل تہٕ تٔمۍ کٔر پانس خٲطرٕ درخواست زِ سُہ گژھہِ مرُن۔ تہٕ ووٚنن، یہ چُھ کافی۔ وۅنۍ نِش نِش میانہِ زُو نِش نِش تکیازِ بہٕ چُھس نہٕ پننین مٲلن کھوتہٕ بہتر۔ {پانس خٲطرٕ: ہیب۔ پننہٕ زندگی خاطرٕ}\n5.\\tییلہ سُہ أکِس جونیپر کُلِس تَل لوٚگِتھ شوٚنگِتھ، وُچھ أکِس فرشتہٕ سٕندِس اَتھٕ تہٕ وونُن تٔمِس وُچھُن، وُچھُن وُچھِتھ کھٮ۪وُن۔\n6.\\tتہِ وُچھِتھ وُچھِتھ {اَتہِ} ژٔلِس پیٹھ کیک بٔنِتھ تہٕ أمِس کَلس کُن آبہٕ کُن کُنہِ تہٕ تٔمۍ کٔر کھٮ۪وان تہٕ چیٚوُن تہٕ لوٚگ سُہ دُبارٕ۔ {ہیڈ: ہیب۔ بولسٹر}\n7. تہٕ خداوند سُند فرشتہ آو دوٚیمہِ لٹہِ تہٕ کوٚرُن أمِس اتھہٕ تہٕ وونُن، وُچھُن کھٮ۪وُن۔ تکیازِ سفر {چُھ} چُھ ژےٚ خٲطرٕ واریاہ بوڈ۔\n8.\\tتہٕ سُہ ووٚتھ، کھیوٚن تہٕ چیوٚو، تہٕ ژتٲجی دۅہہٕ تہٕ ژتجی رٲژ ہٕندِس ماز سٍتـ̡ خدایہ سٕندِس پہاڑس تام ووت حوریب کُن۔\n9.\\tتہٕ سُہ آو تتہِ أکِس گۅپھِ مَنٛز، تہٕ روٗد اَتہِ روزُن۔ تہٕ وُچھ خداوند سُند کلام آو أمِس نِش، تہٕ تٔمِس وونُن، ایلیاہ کیا چُھہ یتہِ چُھہ؟\n10. تہٕ ووٚن بہٕ چُھس خداوند سٕندِس خدایہِ سٕندِ خٲطرٕ سٮ۪ٹھاہ حسد گومُت، کیازِ بنی اسرٲیلِو چُھ تُہند عہد ترٲومُت، تُہٕندِس قربان گاہٕ ترٛٲوِتھ تہٕ تُہٕندِس پیغمبرن تلوار سٍتـ̡ مارنہٕ آمُت۔ تہٕ بہٕ، {حتیٰ کہ} بہٕ چُھس صرف باقٕے؛ تہٕ تِم چھِ میانہِ زِنٛدگی ژھاران، یہِ نِنہٕ خٲطرٕ۔\n11.\\tتہٕ ووٚن، نیرِو تہٕ خداوند سٕندِس برونہہ کُن پہاڑس پیٹھ کھڑا گژھُن۔ تہٕ وُچھ، خداوند پٔکۍ، تہٕ اکھ زبردست تہٕ تیز واو ژٔٹِتھ پہاڑ پھٔٹِتھ، تہٕ کٔرٕن خداوند سٕندِ برونہہ کنہِ کٔنہِ ٹُکرٕ ٹُکر۔ {مگر}رب اوس نہٕ ہوہس منز: تہٕ واو پتہٕ زلزلہٕ؛ {مگر}خداوند {اوس} نہٕ زلزلس منز:\n12. تہٕ زلزلہٕ پتہٕ نار {مگر}رب اوس نہٕ نارس منز: تہٕ نارٕ پتہٕ ٲس اکھ لۅکٹ آواز۔\n13.\\tتہِ ییلہ ایلیاہ ہن بوٗز تہ سُہ اوس پنن بُتھ پننہِ پوشہِ منز ؤلِتھ نیبر نیران تہ گۅپھِ منز اژنس منز کھڑا گوو۔ تہٕ وُچھِتھ آو أمِس نِش اَکھ آواز، تہٕ وونُن، ژٕ کیا چُھکھ یَتہِ کٔرِتھ، ایلیاہ؟\n14. تہٕ تٔمۍ ووٚن، بہٕ چُھس خداوند سٕندِس خدایہِ سٕندِس سٍتـ̡ سٍتـ̡ حسد گومُت، کیازِ بنی اسرٲیلـ̡ چُھہ تُہُند عہد ترٲومُت، تُہٕندِس قربان گاہٕ ترٲوِتھ تہٕ تُہٕندِس پیغمبرن تلوار سٍتـ̡ مارُن۔ تہٕ بہٕ، {حتیٰ کہ} بہٕ چُھس صرف باقٕے؛ تہٕ تِم چھِ میانہِ زِنٛدگی ژھاران، یہِ نِنہٕ خٲطرٕ۔\n15.\\tتہٕ خداوند ووٚن أمِس زِ گژھ دمشق کِس بیابانس کُن واپس، تہٕ ییلہ تہٕ یێلہِ\n16.\\tتہٕ نِمشی سُند نیچو یہو، تہٕ اَبلمہولا ہٕندِس شفعت سُند نیچو الیشع کرِ تُہۍ پنٕنِس کمرس مَنٛز پیغمبر بننہٕ خٲطرٕ مسح کرنہٕ۔ {الیشا: Gr. Eliseus}\n17. تہٕ یُس یُس حزایل سٕنزِ تلوار نِش بچِتھ یُس یہو مارِ، تہٕ یُس یہو سٕنزِ تلوار نِش ژلِتھ آسہِ، سُہ کرِ الیشع مارِ۔\n18.\\tتوتہِ ترٲوۍ میہ ستھ ساس اسرٲیلِس منز، سارِنٕے کۅٹھہِ یِم نہٕ بعلس برونہہ کُن نمٕژ آسہِ، تہٕ پرٮ۪تھ کانہہ ٲسس یُس نہٕ تس بوسہ دِژمُت چھُ۔ {میہ چُھ...: یا، بہٕ نیرِ}\n19.\\tتہٕ وُچھ سُہ اَتہِ نِش تہٕ وُچھُن شافَت سُند نیچو الیشا، یُس أمِس برونہہ کُن باہ کُنہِ کُنہِ تہٕ سُہ اوس بٔہِمِس سٍتـ̡ ہل چلاوان۔\n20. تہٕ سُہ دراو بیلہٕ تہٕ ژوٚل ایلیاہ پتہٕ، تہٕ وونُن، بہٕ دُعا کٔرِتھ پننِس مٲلِس تہٕ ماجہِ بوسہ دِنہٕ، تہٕ {پتہٕ} بہٕ کٔرٕ ژےٚ پتہٕ۔ تہٕ تٔمۍ ووٚن أمِس دُبارٕ واپس: مے کیا کوٚر ژے سٍتۍ؟ {گژھو...: ہیب۔ واپسی}\n21.\\tتہٕ سُہ آو أمِس نِش واپس، تہٕ نِیُن بیلن ہُند اکھ جو، تہٕ مارُن تہٕ تِہُند ماز دِژُن بیلن ہٕندِس آلہٕ سٍتـ̡ تہٕ دِتُن لُکن تہٕ تِمو کھیوٚن۔ تمہ پتہ ووٚتھ تہ ایلیاہ ہس پتہ گۆو تہ کورُن أمس خدمت۔","1.\\tتہٕ شامُک بادشاہ بن ہداد کٔر پنُن سورے لشکر جمع تہٕ أمِس سٍتۍ ٲسۍ ترٕہ تہٕ زٕ بادشاہ تہٕ گُرِ تہٕ رتھ، تہٕ سُہ ووت سامریاہس محاصرٕ تہٕ کوٚرُن اتھ خلاف جنگ۔\n2. تہٕ سوٗزۍ اِسرٲیلِس بادشاہ احابس نِش شہرس مَنٛز، تہٕ وونُن تٔمِس یِتھٕ پٲٹھۍ چُھ بنہداد وَنان۔\n3. تُہند رۄپہٕ تہٕ تُہند سون {چُھ} میٲنۍ چانۍ زنانہٕ تہٕ تہند شُرۍ، {حتیٰ کہ} نیک ، {چِھ} میٲنۍ ۔\n4. تہٕ اسرائیلٕکۍ بادشاہن دیُت جواب تہٕ وونُن، میانہِ آقا، اے بادشاہ، تہندِ کلامَس مطٲبق چُھس بہٕ چُھس تُہند تہٕ سُہ یُس میہ نِش چھُ۔\n5.\\tتہٕ رسول آیہ دُبارٕ تہٕ وونُن، یِتھٕ پٲٹھۍ چُھ بنہداد ونان زِ بہٕ چُھس ژےٚ نِش سوزمُت، تہٕ وَنُن زِ ژٕ دِیُن پَنُن رۄپہٕ، پنُن سۄن، تہٕ پنٕنۍ زنانہٕ تہٕ پنٕنۍ شُرۍ۔\n6.\\tتوتہِ سوز بہٕ پَنٕنـ̡ پَنٕنـ̡ خادمَن نِش پَگہہ تہٕ تُہٕندِس گَرَس تہٕ تُہٕندِس خادمَن ہٕندِس گَرَس تلاش۔ تہٕ یہِ آسہِ، {یہ} یُس تہِ چانہِ نظرن منز خۅش آسہِ، تِم تھاون {یہ} پننِس اتھس منز، تہٕ نِن {یہ}۔ {خوشگوار: ہیب۔ پسندیدٕ}\n7. اِسرٲیلٕکۍ بادشاہن بُلوو زمینہٕ کِس سارِنٕے زِٹھہٕ تہٕ وونُن، مارک، بہٕ چُھس دُعا کران تہٕ وُچھِتھ زِ یہِ انسان کِتھہ کٔنۍ چُھ شرارت ژھاران، کیازِ تٔمۍ سوز میانہِ زنانہٕ خٲطرٕ، میانین شُرین خٲطرٕ، میانہِ رۄپہٕ تہٕ میانہِ سۄنہٕ خٲطرٕ۔ تہٕ مے کوٚر نہٕ تس انکار۔ {مے کوٚر انکار...: ہیب۔ میہ تھوو نہ تس نش واپس}\n8.\\tتہٕ سارِوٕے بزرگو تہٕ سارِنٕے لوٗکو ووٚن أمِس زِ بوز نہٕ تہٕ رضامندی دِیُن۔\n9. اَمہِ مۄکھٕ ووٚن تٔمۍ بنہداد کِس رسولَن زِ میٲنِس آقا بادشاہس وَنُن زِ یُس ژے گۄڈٕنِچہِ لٹہِ پننِس خادمَس سوزمُت اوس، بہٕ کرٕ بہٕ یہِ کَرُن، مگر یہِ کتھ بہٕ ہیوٚک نہٕ کٔرِتھ۔ تہٕ قاصد دراو تہٕ أمِس دُبارٕ خبر دِنہٕ۔\n10.\\tتہٕ بن ہدادن سوز أمِس نِش تہٕ وونُن زِ دیوتا چھِ میانہِ سٍتـ̡ یۅہے کران تہٕ زیادٕ تہِ، یێلہِ سامریہٕچ گرد میانہِ پٲروکار سارِنٕے لُکن ہٕندِ خٲطرٕ کٲفی آسہِ۔ {فالو...: ہیب۔ میانین قدمن پیٹھ}\n11.\\tتہٕ اسرائیلٕکۍ بادشاہن دیُت جواب تہٕ وونُن، یُس سُہ یُس لٔٹِتھ لٔگِتھ آسہِ، سُہ گژھِ نہٕ پانس پیٹھ فخر کرُن۔\n12.\\tتہٕ سپُد یہِ پٲغام، یێلہِ سُہ {بنہداد} یہِ پٲغام بوٗزِ، سُہ تہٕ بادشاہن ہٕندِس پویلینَس مَنٛز، تٔمۍ ووٚن پننین خادمَن زِ تٔمۍ کٔرِو صفہٕ پٲٹھۍ۔ تہٕ تِمو کٔر شہرس خٕلاف صفہٕ منٛز۔ {پیغام: ہیب۔ لفظ} {پویلین: یا، خیمہٕ} {سیٹ کرُن...: یا، انجن تھاوُن۔ تہٕ تمو تھوو انجن}\n13.\\tتہٕ وُچھ اَکھ پیغمبر آو اِسرٲیلِکِس بادشاہ اہاب نِش یُس وُچھمُت چھُ، یِتھٕ پٲٹھـ̡ چُھہ خداوند فرماوان زِ کیا ژے چھے یێمہِ سارِوٕے بٔڈ بٔڈ ہُند وُچھمُت؟ وچھ بہٕ از دۅہہ یہ چانہِ اتھس منز واتناوُن۔ تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس۔ {آو: ہیب۔ اپروچس}\n14.\\tتہ احابن ووٚن کمہِ ذریعہ؟ تہٕ تٔمۍ ووٚن، یِتھٕ پٲٹھۍ چُھ خداوند ونان، صوبن ہٕندٮ۪ن شہزادن ہٕندِس نوجوانَن ہٕندِ دٔسۍ تہِ۔ تمہ پتہ ووٚن جنگُک حکم کُس کرِ؟ تہٕ تٔمۍ دیُت جواب، ژےٚ۔ {نوجوان...: یا، خادم} {آرڈر: ہیب۔ بانڈ، یا، ٹائی}\n15.\\tتمہِ پتہ کٔر تٔمۍ صوبن ہٕندٮ۪ن شہزادن ہٕندِس نوجوانَن ہُند گنزر، تہٕ تِم ٲسۍ زٕ ہتھ تہٕ ترٕہ تہٕ تِمن پَتہٕ سارِنٕے لُکھ گٔنزراوٕن، حتیٰ کہ سارِنٕے اِسرٲیلٕکۍ سَتھ ساس۔\n16. تہٕ تِم گٔیہِ دوپہرس نیبر۔ مگر بن ہداد اوس پویلینن منز شرابس منز شراب، سہ تہ بادشاہ، ترہ تہٕ بُترہ بادشاہ یمو أمس مدتھ کٔر۔\n17.\\tتہٕ صوبن ہٕندٮ۪ن شہزادن ہٕندِ جوان گٔیہِ گۄڈٕ نٮ۪بر۔ تہٕ بن ہداد سوز تہٕ تِمو ووٚن أمِس زِ سامریہٕ منزٕ چھِ انسان نیران۔\n18.\\tتہٕ تٔمۍ ووٚن، یێلہِ تِم امن خٲطرٕ نٮ۪بر نیرِن، تِم رٔٹِو زِندٕ۔ یا کیا تم جنگہٕ خٲطرٕ نیرن، تم نِن زندٕ۔\n19.\\tتہ صوبن ہٕندٮ۪ن شہزادن ہٕندِ یِم جوان دراو شہرٕ منزٕ تہٕ یِمن پتہٕ یِنہٕ وول لشکر دراو ۔\n20.\\tتہٕ تِمو مارۍ أمۍ سُند پرٮ۪تھ کانہہ نفر تہٕ شامٕکۍ ژٔلۍ۔ تہٕ اسرٲیلَن لوٚگ تِمن ہُند پیچھا تہٕ شامُک بادشاہ بن ہداد ژوٚل گُرِ سوارَن سٍتـ̡ گُرِ سٍتـ̡ ۔\n21. تہٕ اسرائیلُک بادشاہ درٛاو نیٚبر، تہٕ گُرٮ۪ن تہٕ رتھَن مارُن تہٕ مارُن شامی بٔڑِس قتلہٕ سٍتۍ۔\n22. تہٕ پیغمبر آو اسرٲیلِکِس بادشاہس نِش، تہٕ وونُن زِ گژھ پنُن پان مضبوٗط تہٕ نشان زد کرُن، تہٕ وُچھِو تہٕ وُچھِو کیا چُھہ کران، کیازِ ؤری واپس یِنہٕ وِزِ شامُک بادشاہ گژھہِ توے سٍتـ̡ خٕلاف۔\n23.\\tتہٕ شام کِس بادشاہ سٕندِس خدمتگارو ووٚن أمِس زِ تِہٕندِ دیوتا چھِ بالن ہٕندِس دیوتا۔ لہذا ٲسۍ تم اسہِ کھوتہ زیادہ مضبوط۔ مگر اسہِ کرو تمن خلاف میدانس منز لڑان، تہٕ یقینا أسۍ بٔنِو تِمو کھوتہٕ زیادٕ طاقتور۔\n24.\\tتہٕ یہِ کٔرِو یہِ کامہِ، بادشاہ نِش نِن، پرٮ۪تھ کانٛہہ نفر نِش نِش تہٕ کپتان تھاوُن تِہنٛدِس کمرس منٛز۔\n25.\\tتہٕ ژے کٔرِو اکھ لشکر گنزراونہٕ، یُس ژے ہارمُت چھُ، گُرِ بدلہٕ گُرِ تہٕ رتھ بدلہٕ رتھ: تہٕ أسۍ کرو تمن خلاف میدانس منز لڑان، {تہٕ} یقینا أسۍ بٔنِو تِمن کھوتہٕ زیادٕ مضبوط۔ تہٕ تٔمۍ بوز تہنزِ آواز، تہٕ کوٚرُن یہ۔ {that thou...: Heb. یہ اوس پیوٚو}\n26. تہٕ ؤری واپس یِنہٕ وِزِ سپُد بنہداد شامٕکۍ شُمار تہٕ سپُد افیکس کُن اسرٲیلس خلاف لڑنہٕ خٲطرٕ۔ {لڑنہٕ خٲطرٕ...: ہیب۔ اسرائیلس سۭتۍ جنگس تام}\n27.\\tتہٕ بنی اسرٲیلِس گٔیہِ گنزراونہٕ تہٕ سارِوٕے ٲسۍ حٲضِر تہٕ یِمن خلاف گٔیہِ۔ تہٕ بنی اِسرٲیلِیو گٔیہِ تِمن برونہہ کُن شُرین ہٕندِس دۄن لۄکٹٮ۪ن ریوڑن ہٕندۍ پٲٹھۍ۔ مگر شامیو کوٚر مُلکس بٔرتھ۔ {سٲری ٲسۍ...: یا ٲسکھ پرورش کٔرمٕژ}\n28.\\tتہٕ خدایہِ سُند اکھ انسان آو تہٕ وونُن اِسرٲیلِکِس بادشاہس سٍتـ̡ تہٕ وونُن خداوند چُھہ یِتھٕ پٲٹھۍ فرماوُن، کیازِکہِ شامٕکۍ باشندن چُھ ووٚنمُت، خداوند چُھہ پہاڑن ہُند خدا، مگر سُہ چُھنہٕ وادین ہُند خدا، تێلہِ کٔرٕ بہٕ یہِ سارِوٕے بٔڈ بٔڈ بٔڈِس پانس اتھس مَنٛز، تہٕ ژے گژھہِ پتاہ زِ بہٕ چُھس خداوند چُھس۔\n29. تہٕ تِمو کٔر اکھ اوور بیٚیِس سَتن دۄہَن خٕلاف۔ تہٕ یِتھے پٲٹھۍ سپُد سٔتِمہِ دۅہہٕ جنگہٕ شُروع تہٕ بنی اسرٲیلِیو مارۍ أکِس دۅہس منز اکھ لچھ ساس پیدل ۔\n30.\\tمگر باقٕے ژٔل افیکس کُن، شہرس منٛز۔ تہٕ {تتہِ} پیوٚو اکھ دیوار وُہن ساس نفرن پیٹھ یِم باقٕے ٲسۍ۔ تہٕ بن ہداد ژوٚل تہٕ آو شہرس منز، أکس اندرمس کمرس منٛز۔ {منز...: یا، چیمبر پیٹھہٕ چیمبرس تام: ہیب۔ اکس چیمبرس اندر اکس چیمبرس منٛز}\n31.\\tتہٕ تٔمۍ سٕندِس خادمَو ووٚن أمِس زِ وُچھِو وُنہِ زِ اسرٲیلِکِس گرٕکۍ بادشاہ چھِ رحم دل بادشاہ: بہٕ چُھس ژےٚ دُعا کران زِ أسۍ تراوُن پننین کمرن پیٹھ بۄٹہٕ پلو تہٕ کلَس پیٹھ رزٕ لاگُن، تہٕ نیرِو اسرٲیلِکِس بادشاہس نِش۔\n32.\\tتہٕ تِمو لٲگِتھ پننِس کمرس پیٹھ رَزٕ تہٕ رَزِ لٲگِتھ تہٕ وونُن تُہند خادم بن ہداد چُھس ونان زِ بہٕ چُھس ژے دُعا کٔرِتھ زِندٕ روزُن۔ تہٕ تٔمۍ ووٚن، {کیا سُہ چھا وُنہِ تہِ زندٕ؟ سُہ چھُ میون بوے ۔\n33.\\tوۅنۍ اوس مردو محنت سان وچھان زِ أمِس نِش ما ییہ کانہہ چیز، تہٕ رٔٹِتھ رٔٹِتھ تہٕ تِمو وونُن تُہند بٲے بنہداد۔ تمہ پتہ ووٚن تمۍ گژھ تہ انۍ ام۔ پتہٕ آو بن ہداد أمِس نِش۔ تہٕ تٔمۍ دِژ أمِس رتھَس منٛز۔\n34.\\tتہٕ {بنہداد} ووٚن أمِس زِ یِم شہر میانہِ مٲلہِ تُہندِس مٲلِس نِش نِش نِمٕتۍ، بہٕ کٔرٕ بحال ۔ تہٕ ژے بناو دمشقس مَنٛز پننہِ خٲطرٕ سڑکہٕ، یِتھ کٔنۍ میانہِ مٲلہِ سامریاہس مَنٛز بنوو۔ اَمہِ پَتہٕ چھُس بہٕ ژےٚ یَتھ عہدٕ سٍتـ̡ سوزان۔ چنانچہ تٔمۍ کوٚر أمِس سٍتـ̡ معاہدٕ، تہٕ سوٗزُن سُہ دور۔ {سڑکہٕ: یا، بازار جاے}\n35.\\tتہٕ پیغمبرن ہٕندِس نیچویو منزٕ أکۍ شخژن ووٚن پننِس ہمساین خداوند سٕندِس کلامس مَنٛز، مے مارٕ دِیُن، بہٕ چُھس ژے دُعا کران۔ تہٕ مردَن کوٚر أمِس مارنہٕ نِش انکار۔\n36. تێمہِ وۆن أمِس زِ تێلہِ چُھہ نہٕ خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری کٔرمٕژ، وُچھِو یێلہِ ژے میہ نِش نیرِ، سٕہہ مارِ ژے ۔ تہٕ ییٚلہِ سُہ أمِس نِش نیرِ، أکۍ سٕہَن لوٚب سُہ تہٕ مارُن سُہ ۔\n37.\\tتمہِ پتہ لوٚب بیاکھ شخژ، تہٕ وونُن میہ مارُن، بہٕ چھُس ژے دُعا کران۔ تہٕ نفرن دِژ أمِس مار، تہ مارنہٕ سٍتۍ لوٚگ أمِس زخم۔ {تہ یہ...: ہیب۔ مارُن تہٕ زخمی}\n38.\\tتہ پیغمبر دراو تہ وتہِ وتہِ بادشاہس پیارُن تہ لوٚگ بُتھِس پیٹھ آش لٲگتھ۔\n39.\\tتہٕ بادشاہ پٔکِتھ وُچھُن بادشاہس کُن تہٕ ووٚنُن، تُہند خادم دراو جنگس منز۔ تہٕ وُچھ، اکھ نَفر پھٔرِتھ تہٕ اوٚن اکھ نفر میانہِ نِش، تہٕ وونُن، یہِ نفر رٔٹِتھ تھاوُن: اگر کُنہِ تہِ طریٖقہٕ سُہ لاپتہ آسہِ، تیلہِ گژھہِ تۅہہِ ہٕنزِ زِندٕ خٲطرٕ، نتہٕ دِیہِ تۅہہ رۄپہٕ ہُند ٹیلنٹ دِنہٕ۔ {تنخواہ: ہیب۔ وزن}\n40.\\tتہٕ ییلہ تُہند خادم یور تتہِ مصروف اوس، سُہ گوٚو ژٔلِتھ۔ تہٕ اسرٲیلٕکۍ بادشاہن ووٚن أمِس تہٕ تُہند فٲصلہٕ {بنہٕ}؛ تۅہہ چھہ پانہ فیصلہ کورمُت۔ {سُہ اوس...: ہیب۔ سُہ اوس نہٕ}\n41.\\tتہٕ تٔمۍ کٔر جلدی تہٕ تُل پننِس بُتھِس نِش سوٗر۔ تہٕ اسرٲیلِک بادشاہن گوو أمِس زِ سُہ چُھ پیغمبرن مَنٛز آسان۔\n42. تہٕ تٔمۍ ووٚن أمِس یِتھٕ پٲٹھۍ چُھہ خداوند ونان، کیازِ ژے چُھہ أکِس شخٕص سٕندِ اتھہٕ نِش یُس میہ تباہ کرنہٕ خٲطرٕ مقرر کورمُت چُھ، تێلہِ گٔژھ تُہٕنز زُو تہٕ تُہٕندِس لوکن ہٕندِ خٲطرٕ۔\n43.\\tتہٕ اِسرٲیلُک بادشاہ گوٚو گٔیہِ گٔژھِتھ تہٕ ناراض گٔژھِتھ تہٕ آو سامریاہس کُن۔","1.\\tتہٕ یِمو چیزو پَتہٕ سپُد، {یہ} نابوتھ یزرایلِس اوس اَکھ انگور باغ، یُس {اوس} یِزریلَس مَنٛز، یُس سامریہ کِس بادشاہ احاب سٕندِس محلس نِش سختی سان اوس۔\n2.\\tتہٕ احابن ووٚن نابوتس سٍتـ̡ کتھ زِ مے دِیُن پنُن انگور باغ، یُتھ بہٕ ہێکہٕ جڑی بوٹین ہٕندِس باغس خٲطرٕ حٲصل کٔرِتھ، تکیازِ یہِ چُھس میٲنِس گرس نکھٕ تہٕ بہٕ دِیہ ژے اَمہِ کھۅتہٕ بہتر انگور باغ۔ {یا}، اگر یہ ژیہ جان باسان چھُ، بہٕ دِیہ ژے امیک قٲمتھ پونسن منز۔ {بچاو...: ہیب۔ پننین اچھن منز گژھ اچھن منز رژھ رژھ رژھ رژھ\n3.\\tتہٕ نابوتھن ووٚن احابس زِ خداوند کرِ میہ منع زِ بہٕ کرٕ پننین آباؤ اجدادن ہٕنز وراثت ژے دِنہٕ۔\n4. تہٕ احاب آو تٔمۍ سٕندِس گرس مَنٛز گٔژِھتھ تہٕ ناراض گٔژھِتھ یُس نَبوت یِزریلیٹن أمِس سٍتـ̡ وَننہٕ آمُت اوس، تکیازِ تٔمۍ اوس ووٚنمُت زِ بہٕ دِیہ نہٕ ژے پننین مٲلن ہُند وٲرث۔ تہٕ تٔمۍ لوٚگ سُہ بسترس پیٹھ، تہٕ پھیُر پھیُر، تہٕ کھیوٚن نہٕ کانہہ روٹی۔\n5.\\tمگر یِزبیل سٕنزِ خانٛدارِنہِ آیہِ أمِس نِش تہٕ وونُن تٔمِس زِ تُہُند روح کیازِ چُھہ یوتاہ غمگسار زِ ژے چُھہ نہٕ روٹی کھٮ۪وان؟\n6. تہٕ تٔمۍ ووٚن أمِس زِ کیازِ مے کٔر نابوت یزرِیلیٹس سٍتـ̡ کتھ تہٕ وونُن أمِس زِ مے دِیُن پنُن انگور پٲنسہٕ بدلہٕ۔ نتہٕ اگر ژیہ خۅش آسہِ، بہٕ دِیہ ژے اَمہ بدلہٕ بیاکھ انگور باغ: تہٕ تٔمۍ دیُت جواب، بہٕ دِیہ نہٕ ژے پنُن انگور باغ۔\n7.\\tتہٕ یِزبیلَن ووٚن تٔمِس زِ کیا تُہۍ چھُکھ وُنہِ اسرٲیلِچ بادشٲہی ہٕنز حکوٗمت کٔرِتھ؟ وۅتھ، {تہٕ} کھیوٚو روٹی تہٕ پنُن دِل خۅش روزُن: بہٕ دِیہ ژے نابوتھ یزرِیلِٹ سُند انگور باغ۔\n8.\\tتێلہِ لیچھِن تٔمۍ احاب سٕندِس ناوس پیٹھ چِٹھہِ تہٕ تِمن پیٹھ مہرٕ تہٕ سوزٕن زِٹھٮ۪ن تہٕ رئیسن یِم تٔمۍ سٕندِس شہرس مَنٛز روزان ٲسۍ، نابوتس سٍتـ̡ روزان ٲسۍ۔\n9.\\tتہٕ تٔمۍ لیوٗکھ چِٹھہِ مَنٛز زِ روزُک اعلان کٔرِو تہٕ نَبوت تھدِ پٲٹھۍلُکن مَنٛز تھدِ تھزرس پیٹھ۔ لوکن ہندس پیٹھمس حصس منز}\n10.\\tتہٕ بنووُن أمِس برونہہ کُن زٕ نَفر یِم بِلیال سٕندِس نیچوِس أمِس خٕلاف گوٲہی دِنہٕ خٲطرٕ تہٕ وَنُن زِ ژے کٔر خدایہ تہٕ بادشاہس کُفر کُن۔ تہٕ {پتہٕ} نِیُن أمِس نِش تہٕ کٔرِو سُہ مَرُن۔\n11.\\tتہٕ تٔمۍ سٕندِس شہرٕکۍ لوکو {حتیٰ کہ} زِٹھۍ تہٕ رئیس، یِم تٔمۍ سٕندِس شہرس منز روزن وٲلۍ، یِتھٕ پٲٹھۍ کٔر یِتھٕ پٲٹھۍ یِمن چِٹھن منز لیکھنہٕ آمُت اوس۔\n12.\\tتِمو کٔر روزُک اعلان تہٕ کوٚرُکھ نَبوت لُکن مَنٛز تھزرس پیٹھ۔\n13.\\tتہٕ بیلیال سٕندِ شُرۍ دِژ زٕ نفر تہٕ بیوٹھ أمِس برونہہ کُن، تہٕ بِلیال ہٕندِیو لُکن ہٕندِس حٲضِرِس مَنٛز دِژ أمِس خٕلاف، حتیٰ کہ نابوتَس خٕلاف، لُکن ہٕندِس حٲضِرِس سٍتـ̡ وَنُن زِ نابوتَن کٔر خدایہِ تہٕ بادشاہس کُن کُفر کٔرِتھ۔ پتہٕ نِیُکھ تِمو سُہ شہرٕ منٛزٕ نٮ۪بر تہٕ لگٲوِکھ أمِس کَنہِ کَنہِ تہٕ سُہ موٗد۔\n14.\\tپتہٕ سوٗز یِمو یِزبلس نِش یہِ ونان زِ نابوٗت چُھس کَنہِ کٔرِتھ تہٕ سُہ چُھ موٗدمُت۔\n15.\\tتہٕ سپُد یێلہِ یێلہِ یِزبیلن بوز زِ نابوٗتھ آو کَنہِ کٔرِتھ تہٕ موٗدمُت، یێلہِ یِزبیلن ووٚن اہابس زِ وُچھِو نابوت یِزریلیٹ سٕندِس انگورس پیٹھ قبضہ کرُن، یُس تٔمۍ ژے پٲنسہٕ دِنہٕ نِش انکار کوٚر، تکیازِ نابوتھ چُھ نہٕ زندٕ بلکہ موٗدمُت۔\n16.\\tتہ سپد ییلہ احابن یہ بوز زِ نابت چھہ موٗدمُت، تہ ووت اہاب ووٚتھ نبوت یزریلی کِس انگورس منز گژھنہ مۅکھہ اتھ پیٹھ قبضہ کرنہِ۔\n17. تہٕ خداوند سُند کلام آو ایلیاہ تِشبیتس نِش وَنُن،\n18.\\tوُتھ، وُچھِو اِسرٲیلِکِس بادشاہ احاب سٕندِس سٍتـ̡ یُس سامریاہس مَنٛز {چُھ} چُھہ: وُچھِو {سُہ چُھ} نابوت کِس انگورس مَنٛز، یێتہِ سُہ یہِ حٲصِل کرنہٕ خٲطرٕ بۄن گومُت۔\n19.\\tتہٕ تُہۍ کٔرِو أمِس سٍتـ̡ کتھ کٔرِتھ ونُن، یِتھٕ پٲٹھۍ چُھہ خداوند فرماوان زِ کیا ژے چُھکھ مٲرِتھ تہٕ قبضہ تہِ کورمُت؟ تہٕ ژے کٔرِو أمِس سٍتـ̡ کتھ کٔرِتھ، یێلہِ ہُونۍ نابوتُک خوُن چیٚون، تێلہِ چُھہ ہونۍ تُہند خون، چانہِ تہِ چُھس۔\n20. تہٕ احابن ووٚن ایلیاہ ہس زِ کیا ژے لٔبِتھ میہ دُشمن؟ تہٕ تٔمۍ دیُت جواب، مے لوٚب {ژے}: کیازِ ژے چُھ پنُن پان خداوند سٕندِس نظرس منز بد کٲم کرنہٕ خٲطرٕ کٕننہٕ آمُت۔\n21. وچھ بہٕ ژے سٍتـ̡ بد کار انان، تہٕ تُہند اولادٕ نِتھ تہٕ یُس دیوارس سٍتـ̡ رٔٹِتھ تہٕ یُس اسرٲیلِس مَنٛز بند تہٕ تراوُن چُھ،\n22.\\tتہٕ بناوُن پنُن گرٕ نیبت سٕندِس نیچو یربعام سٕندِس گرس ہیوٗ تہٕ احییاہ سُند نیچو بعشہٕ سٕندِس گرس ہیوٗ بنوو، ییمہِ سٍتـ̡ ژے شرارت دِژمٕژ تہٕ اسرٲیلِس گۅناہ کٔرِتھ بنوومُت۔\n23.\\tتہٕ یِزبیل سٍتـ̡ تہِ وونُن زِ ہونۍ یِزبیل یزریل سٕندِس دیوارس نِش کھٮ۪ن۔ {دیوار: یا، کھوڑ}\n24. یُس شہرس مَنٛز اہاب سُند مرُن چُھ، سُہ گژھہِ ہونۍ کھٮ۪ن۔ تہٕ یُس کھاہس منز مران چُھ، سُہ گژھہِ ہوہٕکۍ جاناوار کھٮ۪ن۔\n25.\\tمگر اوس نہ احابس ہیو کانہہ تہِ، یُس خداوند سٕندِس نظرس منز بدکاری کٔرِتھ کٕنُن اوس تہٕ یُس یِزبیل سٕنزِ زنانہِ ہٕندِس نظرس منز بدکاری کٔرِتھ کٕنُن۔ {ہلچل کٔرِتھ...: یا، اِنسائیٹڈ}\n26.\\tتہٕ تٔمۍ کٔر سارِنٕے چیزن مطٲبق بُتن ہٕنز پیروی کرنس منز سٮ۪ٹھاہ مکروہ کٲم یِتھ کٔنۍ زن اموریو کٔر، یِم خداوند بنی اسرٲیلِس برونہہ کُن کٔرۍ۔\n27.\\tتہٕ ییلہ احابن یہ لفظ بوز، تٔمۍ کٔر پَنٕنۍ پلو ژٔٹِتھ تہٕ لوٚگ مازس پیٹھ تہٕ روزٕ تھووُن تہٕ لوٚگ لۅتہٕ لۅتہٕ۔\n28.\\tتہٕ خداوند سُند کلام آو ایلیاہ تِشبیتس نِش وونُن،\n29.\\tژیہ وچھ زِ اہاب کِتھہ پاٹھۍ چھہ میانہِ برونہہ کنہِ عاجز سپدان؟ تکیازِ سُہ چُھس میانہِ برونہہ کُن عاجز کران، بہٕ اَنہٕ نہٕ تٔمۍ سٕندِس دۅہس منز بُردی انان: {مگر} تٔمۍ سٕندِس نیچوۍ سٕندِس دۅہس منز اَنہٕ بہٕ تٔمۍ سٕندِس گرس پیٹھ بُرٕ۔","1. تہٕ تِمو جٲری، شام تہٕ اسرائیلس درمیان جنگ ورٲے تریہ ؤری۔\n2. تہٕ تریمہِ ؤریس مَنٛز سپد یہوداہُک بادشاہ یہوشافات اسرٲیلِکِس بادشاہس نِش وسان۔\n3. تہٕ اسرائیلٕکۍ بادشاہن ووٚن پننین خادمَن زِ تُہۍ چھِو زانان زِ گلعادس مَنٛز راموتھ چُھہ سانہِ تہٕ أسۍ چھِہ وُنہِ تہِ شامٕکۍ بادشاہ سٕندِ اتھہٕ نِش نِنہٕ یِوان۔ {توتہِ...: ہیب۔ یہ رٹنہٕ نِش ژھۄپہٕ}\n4.\\tتہٕ تٔمۍ ووٚن یہوشافتس زِ کیا ژٕ گژھکھ میانہِ سٍتـ̡ راموتگیلاد کِس جنگس مَنٛز؟ تہٕ یہوشافتن ووٚن اسرٲیلِکِس بادشاہس زِ بہٕ چُھس تُہٕندِس پٲٹھۍ، میٲنۍ قوم چُھس تُہند لوک، میٲنۍ گُرِ چُھہ تُہند گُرِ پٲٹھۍ۔\n5. تہٕ یہوشافتن ووٚن اسرٲیلِکِس بادشاہس پرژھہ، بہٕ چُھس ژےٚ دُعا کران یُس از خداوند سٕندِس کلامَس سٍتـ̡ دُعا کران چھُ۔\n6.\\tاَمہِ پَتہٕ کٔر اسرٲیلِکۍ بادشاہن پیغمبرن سٍتـ̡ تقریباً ژور ہتھ نفر جمع تہٕ تِمن وونُن، کیا بہٕ گژھا راموتگیلادس خلاف جنگہٕ خٲطرٕ گژھُن، کِنہٕ بہٕ برداش؟ تہٕ تمو ووٚن، ہیوٚر گژھ۔ تکیازِ خداوند کرِ بادشاہ سٕندِس اتھس مَنٛز۔\n7. تہٕ یہوشافتن ووٚن زِ {کیا یتہِ} چُھہ نہٕ یتہِ خداوند سُند کانہہ پیغمبر، یُتھ أسۍ أمِس پرژھہٕ گٲر کٔرِتھ؟\n8.\\tتہٕ اسرائیلٕکۍ بادشاہن ووٚن یہوشافاطس زِ {اَکھ شخٕص چُھ} میکایاہ یُس املاہ سُند نیچو چُھ، یٔمِس سٍتـ̡ أسـ̡ خداوند سٍتـ̡ پرژھہٕ گٲر کٔرِتھ، مگر بہٕ چُھس أمِس سٍتـ̡ نفرت۔ تکیازِ سُہ چُھ نہٕ میانہِ بارس منز نیکی ہٕنز پیشن گویی کران، بلکہ چُھ بدی ہٕنز پیشن گویی کران۔ تہٕ یہوشفاتن ووٚن زِ بادشاہ گژھہِ نہٕ یہِ وَنُن۔\n9.\\tاَمہِ پَتہٕ بُلوو اِسرٲیلٕکۍ بادشاہن أکِس افسرس تہٕ وونُن زِ عملہ سُند نیچو میکیاہ جلدی کرُن۔ {افسر: یا، خواجہ سرا}\n10.\\tتہٕ اسرائیلُک بادشاہ تہٕ یہوداہُک بادشاہ یہوداہُک بادشاہ بِہتھ پرٮ۪تھ أکِس تختس پیٹھ، سامریہ کِس دروازٕ کِس دروازس پیٹھ أکِس خٲلی جایہِ پیٹھ۔ تہٕ سارِنٕے پیغمبرن کٔر تِمن برونہہ کُن پیشن گوئی۔ {خٲلی...: ہیب۔ فرش}\n11.\\tتہٕ چنانہٕ سٕندِ نیچو زدقیاہ بنوو أمِس ششتٕرٕکۍ سینگ تہٕ وونُن خداوند یِتھٕ پٲٹھۍ چُھہ فرماوان زِ یِمو سٍتـ̡ ژے شامٕکۍ دَکہٕ دِنہٕ یِن، یوتام نہٕ تِم کھٮ۪نہٕ یِن۔\n12. تہٕ سارِوٕے پیغمبرن کٔر یہِ پیشن گویی تہٕ وَنُن زِ رموتھ گیلڈس تام گژھ تہٕ روزُن، تِکیازِ خداوند کرِ یہِ بادشاہ سٕندِس اتھس مَنٛز۔\n13.\\tتہٕ یُس رسول میکایاہ بُلاونہٕ آمُت اوس، ووٚن أمِس سٍتـ̡ وُچھِو، وُچھِو پیغمبرن ہٕندِ کلامَن ہٕندِس کلامَس سٍتـ̡ اَکہِ ٲسِس سٍتـ̡ بادشاہس سٍتـ̡ خیر آسنُک اعلان کرُن: تێہُند کلام گژھہِ یِمو منزٕ أکِس سٕندِس کلامٕکۍ پٲٹھۍ، تہٕ کتھ کرٕنـ̡ یُس اصل چُھہ ۔\n14. تہٕ میکایاہ ووٚن، یێلہِ خداوند زندٕ چُھ، یُس خداوند میانہِ خٲطرٕ چُھ ونان، سُہ چُھس بہٕ کتھ کرٕنـ̡ ۔\n15. تہٕ سُہ آو بادشاہس نِش۔ تہٕ بادشاہن ووٚن أمِس میکایاہ، کیا أسۍ گژھو راموتگیلیدس خلاف جنگہٕ خٲطرٕ، کِنہٕ أسۍ برداش؟ تہٕ تٔمۍ دیُت أمِس جواب، گژھ تہٕ کامیاب گژھُن، تکیازِ خداوند دِیہِ یہِ بادشاہ سٕندِس اتھس مَنٛز۔\n16.\\tتہٕ بادشاہن ووٚن أمِس زِ بہٕ کٲژاہ لٹہِ ژے وَنُن زِ ژے کٔرِو نہٕ میہ کُنہِ تہِ وَنُن یُس خداوند سٕندِ ناوٕ سٍتـ̡ پزر چُھہ؟\n17.\\tتہٕ تٔمۍ ووٚن، مے وُچھ سارِنٕے اِسرٲیلِس بالن پٲٹھۍ، کۅکرِ ہٕندۍ پٲٹھۍ، یِمن نہٕ کُنہِ چرواہ چُھہ، تہٕ خداوند ووٚن، یِمن چُھنہٕ کانہہ مٲلک، تِم گژھن پرٮ۪تھ کانہہ نفر امن سان پننِس گرس منز واپس۔\n18. تہٕ اسرائیلٕکۍ بادشاہن ووٚن یہوشافتس زِ کیا مے ووٚن نہٕ ژے زِ سُہ کرِ نہٕ میانہِ متعلق کانہہ نیکی پیشن گوئی، مگر بُر؟\n19.\\tتہٕ ووٚن، تێمہِ کِنۍ بوزو خداوند سُند کلام: مے وُچھ خداوند پننِس تختس پیٹھ بِہتھ، تہٕ آسمانُک سورُے لشکر اوس أمِس سٍتـ̡ دٔچھنِس تہٕ کھوورِ طرفہٕ کھڑا ۔\n20. تہٕ خداوند ووٚن زِ کُس کرِ احابس آمادہ زِ سُہ گژھہِ ہیوٚر تہٕ راموتگلاڈس پیٹھ پیوٚو۔ تہٕ أکۍ ووٚن اَتھ پٲٹھۍ تہٕ بیٛاکھ ووٚن اَتھ اندازس پیٹھ۔ {قائل کرُن: یا، دھوکہٕ}\n21. تہٕ اَکھ روح دراو تہٕ خداوند سٕندِس برونہہ کُن کھڑا تہٕ وونُن، بہٕ کٔرٕ أمِس رٲضی۔\n22.\\tتہٕ خداوند ووٚن أمِس کُنہِ سٍتـ̡ ؟ تہٕ تٔمۍ ووٚن، بہٕ نیرٕ نیرُن، تہٕ بہٕ بنہٕ تٔمۍ سٕندٮ۪ن سارِنٕے پیغمبرن ہٕندِس ٲسِس مَنٛز اکھ اپُز روح۔ تہٕ تٔمۍ ووٚن، تہٕ ژٕ کرٕ أمس قائل تہٕ غالب تہٕ: نیرُن، تہٕ کرُن۔\n23. تێمہِ وۆن، وُچھو، خداوند چُھ تۅہہِ سارِنٕے پیغمبرن ہٕندِس ٲسِس مَنٛز اکھ اپُز روح تروومُت، تہٕ خداوند چُھ تۅہہِ سٍتـ̡ بد کتھ کٔرمٕژ۔\n24.\\tمگر چِناناہُک نیچو زِدقیاہ ووت نزدیک، تہٕ دیتُن میکایاہ گالِس پیٹھ تھپھ تہٕ وونُن، خداوند سُند روح کمہِ وتہِ ووت میانہِ طرفہٕ ژے سٍتـ̡ کتھ کرنہٕ۔\n25.\\tتہٕ میکایاہ ووٚن، وُچھِو تۅہہ تمہِ دۅہہ وُچھِو، یێلہِ ژیہ پان ژوٗرِ روزنہٕ خٲطرٕ أنٛدرِمِس خانس مَنٛز ژٔلِتھ۔ {into...: یا، چیمبر پیٹھہٕ چیمبرس تام: Heb. أکس چیمبرس منٛز اکھ چیمبر}\n26. تہٕ اسرٲیلٕکۍ بادشاہن ووٚن، میکایاہ رٔٹِتھ نِو شہرُک حاکم آمون تہٕ بادشاہ سٕندِس نیچوِس یواشس نِش۔\n27. تہٕ ونُن بادشاہ چُھہ یِتھٕ پٲٹھۍ ونان زِ یہِ {نفر} تھووُن قٲد خانس منٛز، تہٕ دِیُن أمِس مُصیبتٕچ روٹی تہٕ مُصیبتُک آب، یوتام بہٕ امن یِنہٕ۔\n28.\\tتہٕ میکایاہ ووٚن، یێلہِ ژے سُہ سُہ واپس یِو، خداوند چُھنہٕ میانہِ سٍتـ̡ کتھ کٔرمٕژ۔ تہٕ تٔمۍ ووٚن، بوزو، اے لوکو، تم منزٕ پرٮ۪تھ کٲنسہٕ۔\n29. یێمہِ پٲٹھـ̡ گٔیہِ اسرٲیلُک بادشاہ تہٕ یہوداہُک بادشاہ یہوشافات، راموتگلاڈس کُن۔\n30.\\tتہٕ اسرائیلٕکۍ بادشاہن ووٚن یہوشافتس زِ بہٕ کٔرٕ پنُن پوش تہٕ جنگس مَنٛز دٲخل۔ مگر پَنٕنۍ پوشہٕ لٲگِتھ لٲگِتھ۔ تہٕ اسرٲیلُک بادشاہ لوٚگ پان پوش، تہٕ گوٚو جنگس منٛز۔ {بہٕ کرِ...: یا، ییلہ سہ پوش لٲگِتھ جنگس منز دٲخل گژھہِ}\n31.\\tمگر شامٕکۍ بادشاہن دِژ پننین ترہن تہٕ زٕ کپتانس حُکُم یِم تٔمۍ سٕندٮ۪ن رتھن پیٹھ راج ٲسۍ کٔرِتھ، یہِ وونُن زِ لوٚکٹِس تہٕ بٔڑِس سٍتـ̡ لڑٲے کرُن، صرف اسرٲیلِک بادشاہس سٍتـ̡ لڑُن۔\n32.\\tتہٕ سپُد یہِ سپدُن، یێلہِ رتھَن ہٕندِیو کپتانو یہوشافات وُچھ، تِمو ووٚن، یێلہِ چُھ یہِ اسرٲیلُک بادشاہ۔ تہٕ تِم پھٔرِتھ أمِس خٕلاف لڑنہٕ خٲطرٕ: تہٕ یہوشافتن کٔر کرٛٮ۪کھ۔\n33.\\tتہٕ سپُد یہِ سپدُن، ییٚلہِ رتھن ہٕندِیو کپتانن یہ وُچھ زِ یہِ چُھنہٕ اسرٲیلُک بادشاہ ، تِمو پھیرۍ أمِس پتہٕ پَتہٕ نِش واپس۔\n34.\\tتہٕ أکِس شخصس کٔر أکِس کمانس کُن تہٕ لوٚگُن اسرٲیلِس بادشاہس لٔگِتھ تہٕ لٔگِتھ دِژٕنـ̡ ۔ تکیازِ بہٕ چُھس زخمی۔ {at a...: Heb. پننہِ سادگی منز} {جوڑ...: ہیب۔ جوڑ تہٕ بریسٹ پلیٹ} {زخمی: ہیب۔ بیمار بنیومُت}\n35.\\tتہٕ تمہِ دۅہہ ہُریوو جنگہٕ: تہٕ بادشاہ روٗد پننِس رتھَس منز شامِس خٕلاف، تہٕ سپُد رٲژ ہٕندِس زخمس منزٕ خوُن۔ {اضافہٕ: ہیب۔ عروج } {درمیان: ہیب۔ بوسم}\n36.\\tتہٕ سٲرۍسٕے میزبانس منز آو آفتاب لوسنہٕ کِس بارس منز اعلان کرنہٕ، یتھ منز وونُن زِ پرٮ۪تھ کانہہ انسان پننِس شہرس کُن تہٕ پرٮ۪تھ کانہہ انسان پننِس ملکس کُن۔\n37.\\tیێلہِ گۆو بادشاہ تہٕ سُہ آو سامریاہس منز اننہٕ۔ تہٕ تِمو دفن بادشاہ سامریاہس مَنٛز۔ {آو اننہٕ: ہیب۔ آیا}\n38.\\tتہٕ {أکہِ} کٔر سامریہ کِس تالابس مَنٛز رَتھ واش کٔرِتھ۔ تہٕ ہونین لوٚگ تٔمۍ سُند خون۔ تہٕ تمو واش تٔمۍ سٕندِ ہتھیار واش کٔرۍ۔ خداوند سٕندِ کلامَس مُطٲبِق یُس تٔمۍ کَرُن اوس ۔\n39.\\tوۅنۍ چھہ نہ احاب سٕنزِ باقی کامہِ تہٕ یُس تٔمۍ کٔرۍ، تہٕ یُس تٔمۍ بنوومُت تہٕ سٲری شہر یُس تٔمۍ بنٲومُت چھُ، کیا تِم چھِنہٕ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابس مَنٛز لیکھنہٕ آمٕتۍ؟\n40.\\tیِتھ گۆو اہاب پننین مٲلن سٍتـ̡ شوٚنگ۔ تہٕ تٔمۍ سٕندِس نیچوِس احزیاہ کٔر أمِس بدلہٕ حکومت۔\n41.\\tتہٕ آسا سُند نیچو یہوشافات کٔر یہوداہ سٕندِس ژوٗرمِس ؤریس مَنٛز یہوداہَس پیٹھ حکومت کرٕنـ̡ شروع۔\n42.\\tیہوشفات اوس ترہ پانژٕ وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر۔ تہٕ تٔمۍ کٔر یروشلمس مَنٛز وُہن تہٕ پنٛژٕہن ؤرین حکومت۔ تہٕ تٔمۍ سٕنٛزِ ماجہِ ہُنٛد ناو اوس ازوبہ یۄس شِلہی سٕنٛز کوٗر ٲس۔\n43.\\tتہٕ سُہ پَکُن پَکُن آسا سٕندِس مٲلِس سٕندِس سارِنٕے وَتہٕ پَکُن۔ سُہ اوس نہٕ اَمہِ نِش پتھ کُن، یُس خداوند سٕندِس نظرس منز صحیح اوس، سُہ کٔرِتھ کٔرِتھ:\n44.\\tبہر حال آیہ نہ تھدِ جایہ نِنہٕ۔ {تکیازِ} لوٗکو ٲسۍ وُنہِ تہِ تھدٮ۪ن جاین پیٹھ بخور پیش کران تہٕ زالان۔\n45.\\tتہٕ یہوشافاتن کٔر اسرٲیلِکِس بادشاہس سٍتـ̡ صلح۔\n46.\\tوۅنۍ چھہ یہوداہ کین بادشاہن ہنزِ تواریخ کتابہِ منز لیکھنہ آمت؟\n47.\\tتہٕ سدومی ہُند باقی، یُس أمۍ سٕندِس مٲلِس آسا سٕندِس زمانس مَنٛز روٗدمُت، تٔمۍ کٔر زمینہٕ منزٕ نیبر۔\n48.\\tاَمہِ وِزِ اوس نہٕ اَدومَس مَنٛز کانہہ بادشاہ: اَکھ نٲیِب {اوس} بادشاہ۔\n49.\\tیہوشافتن بنوو تھرشِش سٕندِ جہازٕ سۄنہٕ خٲطرٕ اوفیرس نِش گَژھنہٕ خٲطرٕ، مگر تِم گٔیہِ نہٕ۔ تکیازِ جہازٕ ٲسۍ ایزیونگیبرس منٛز پھُٹمٕتۍ۔ {بنیومُت...: یا، ٲسۍ داہ جہاز}\n50.\\tاَمہِ پتہٕ ووٚن اہاب سٕندِس نیچو احزیاہ یہوشافاطس زِ میانین خادمَن سٍتـ̡ جہازس سٍتـ̡ گژھن پنٕنـ̡ خادمَن سٍتـ̡ جہازس منز۔ مگر یہوشافت کرِ نہٕ۔\n51.\\tتہٕ یہوشفات گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ سُہ آو پننین مٲلن سٍتـ̡ دفن کرنہٕ، تہٕ تٔمۍ سٕندِس نیچوِس کٔر تٔمۍ سٕندِ بدلہٕ بادشاہی۔\n52.\\tاحزیاہ سٕندِس نیچوِس کٔر یہوداہ کِس بادشاہ یہوشافاطس سٕندِس سداہِمِس ؤریس مَنٛز سامریہِ مَنٛز اسرٲیلِس پیٹھ حکومت شروع تہٕ کورُن دۄن ؤرین اسرٲیلس پیٹھ حکومت۔\n53. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس مَنٛز بدکار تہٕ پننِس مٲلہِ سٕنزِ وتہِ پٲٹھۍ، تہٕ پننہِ ماجہ ہٕنزِ وتہِ پٲٹھۍ، تہٕ نیبت کِس نیچو یربعام سٕندِس وتہِ پیٹھ، یٔمۍ اسرٲیلِس گۅنہٕ گار بنوو۔\n54. تکیازِ تٔمۍ کٔر بعلٕچ عبادت تہٕ أمِس پوٗزا کٔرٕن، تہٕ تٔمۍ سٕندِس مٲلہِ سٕندِ کٔرمٕژ سٍتـ̡ کٔرٕن اِسرٲیلِس خداہس شرارت کرنہٕ خٲطرٕ۔"];
